(window.AQIDA_TEXTS = window.AQIDA_TEXTS || {})["526"] = {"atoms": {"526.1": {"x": [[7, "المقدمة\r"]], "pg": [7, 7]}, "526.2": {"x": [[7, "بسم الله الرحمن الرحيم\rسبحان ربنا رب السموات والأرض رب العرش عما يصف الجاهلون. والحمد لله كما ينبغي لكرم وجهه وعز جلاله. وتبارك وتعالى لا يحصى أحد من خلقه وإن جل مقامه ثناء عليه، سبحانه هو كما أثنى على نفسه. نحمده على ما من به من الفرقان. ونسأله المزيد من كرمه حتى نبلغ به أعلى فراد يس الجنان. مع الذين أنعم الله عليهم من النبيين والصديقين والشهداء والصالحين، بجاه الوسيلة العظمى والمنة الكبرى علينا خاصة وعلى المؤمنين عامة خاتم النبيين وأفضل الخلق أجمعين. وصل اللهم وسلم وبارك على هذا النور المبين، والسيد الذي هو عندك أمكن مكين، سيدنا ومولانا محمد الذي هديت به من الضلالة، وبصرت به من العمى، وفرقت به بين الحق الذي كان قد درست معالمه، وبين الباطل الذي قد طبق الأرض ظلامه، وعلى آله الأطهار، وأصحابه الأخيار، وسائر التابعين لهم بإحسان، لا سيما حماة شريعته، والفقهاء في سنته، وعلينا معهم واجعلنا بفضلك منهم، واختم لنا بما ختمت به من الخير لهم إنك حميد مجيد (أما بعد) فاعلم أيها الأخ في دين الله، والرفيق في سبيله الطالب لمرضاته والهارب من غضبه، ثبت الله على دينه قلبي وقلبك، وشرح بنور كتابه وسنة نبيه عليه أفضل الصلاة والسلام صدري وصدرك، أن الله تبارك وتعالى قد أنزل في كتابه على نبيه الأمين وخاتم النبيين صلى الله عليه وعليهم وبارك وسلم قوله المجيد {فَهَلْ يَنْظُرُونَ إِلَّا السَّاعَةَ أَنْ تَأْتِيَهُمْ بَغْتَةً فَقَدْ جَاءَ أَشْرَاطُهَا} [محمد: 18] أي علامات قربها، فان الأشراط جمع شرط ــ بفتحتين ــ وهو العلامة. وصح عنه عليه الصلاة والسلام فيما أخرج إمام المحدثين أبو عبد الله محمد بن إسماعيل البخاري ــ المتوفى سنة ست وخمسين"], [8, "ومائتين ــ في جامعه الذي هو أصح الكتب بعد كتاب الله تعالى، كما اتفقت عليه كلمة جمهور أكابر أهل هذا الشأن، ((بعثت أنا والساعة كهاتين)) ــ وأشار إلى أصبعيه الشريفتين المسبحة والوسطى ــ فكان ذلك من ربنا تبارك وتعالى ونبينا عليه وعلى آله أفضل الصلاة والسلام، حثا للعباد على الانتباه من غفلتهم، والاستيقاظ من رقدتهم، للتأهب والاستعداد لما ينفعهم يوم المعاد، فنفع الله بذلك من شاء من عبادة. وجد سلفنا الصالح رضي الله عنهم في العلم والعمل، حتى لحقوا بربهم عز وجل، وقد رضي الله عنهم ورضوا عنه. أفلا نكون نحن أولى بالتشمير عن ساعد الجد فيما خلقنا لأجله؟ وقد صرنا في النصف الثاني من القرن الرابع عشر من هجرة سيد البشر الذي نزل عليه هذا التحذير، وجاء بهذا النذير، بلى، وقد أحدث الله بعد نبيه أمورا وأمورا من أشراط الساعة، كما أخبر به عليه الصلاة والسلام في الأحاديث الصحاح المستفيضة، وقد أفردت بالتأليف. ومن أجمعها وأنفعها كتاب ((الأشاعة في أشراط الساعة)) للشريف العلامة السيد محمد بن عبد الرسول الحسيني البرزنجي رضي الله عنه المتوفى سنة ثلاث ومائة وألف، وقد طبع بمصر فليطلبه مريد الآخرة، فستعلم إذا قرأته أو ما كتب في أبواب الفتن من صحاح كتب الأئمة المحدثين أنك في آخر آخر الزمان فقد تحققت الأشراط كلها إلا قليلا، وهو الأشراط الكبرى، وكأنك بها وقد فجئتك، ألم تر إلى ما أصبحت فيه من زمان هاجت فيه بحار الفتن، وتلاطمت بالبدع المهلكة أمواجها، وبيع فيه الهدى بالهوى، والتبس فيه الحق بالباطل، وسميت الأشياء بغير أسمائها، فسمى الثبات على الدين الحق جمودا، والخروج على التعاليم الربانية نباهة وتجديدا، والشك فيما علم بالضرورة من دين الله الحق فلسفة ونبلا، والانكار للأوليات من اليقينيات حصافة وعقلا، وانتشرت الفوضى في العقائد الأعمال، والأخلاق والآداب، حتى أسبح لكل جماعة، وأكاد أقول لكل شخص، ما شاء له الهوى وإن نابذ كل فضيلة، ومثل كل "], [9, "رذيلة، ويكفي في نظره أن يضع لما نمسك به ما أحب من الأسماء، وإن أجمع على خلاف ما رآه كل العقلاء، فانه يرى أن لا عقل إلا عقله، ولا رأى إلا ما رآه، ولو كانت هذه الثورة قاصرة على الطوائف البعيدة عن الانتساب إلى العلم، والانتماء إلى خدمة الدين، لهان الأمر بعض الشيء، ولكنها قد دبت إلى تلك الأوساط التي تنادى بأنها خادمة الدين وحاملة لواء السنة، والداعية إلى المحجة وقائمة عن الله بالحجة وكثرت الجمعيات الحاملة للألقاب الخلابة، المتسترة بستور الأسماء الجذابة، فإذا دعاك إليها حسن ما تسمع من خبرها المطوي في أسمائها، صرفك عنها ما ترى في مخبرها الذي تتكشف عنه حقائقها المخبوءة بين جدران دورها، وتنم عنه فلتات ألسنة قادتها ودعاتها، وما تسطره بين آونة وأخرى صحائفها ومجلاتها. فمن كل جمع قلة حزب، ومن كل فرد من الحزب إمام يستفتى ويفتى، وما أسهل الفتيا عليه، فانه لا يرى عليه فيها إلا أن يرجع إلى رأيه الخاص، لا يتحرز من مخالفة إجماع، ولا يتقيد بما عليه الصالحون من سلف هذه الأمة وأئمتها، وليت هذه الفوضى اقتصرت على ما هو من المسائل الفرعية والأبواب غير الأصلية، كالربا والزواج والطلاق، ولكنها تخطتها إلى صميم الأصول، ولباب الدين، والكلام في صفات الله تعالى وأسمائه، بغير علم ولا هدى ولا كتاب منير، والخوض فيما تشابه من آي الكتاب العزيز، وفيما أشكل على أمثالهم من أحاديث رسول الله صلى الله عليه وعلى آله وصحبه وسلم، والله يعلم وأهل العلم يعلمون أن الجل منهم، إن لم نقل الكل، أحط من أن يرقى إلى ما ظهر من علمها، فضلا عن الدخول إلى باطن سرها، وقد تزين هؤلاء للعامة بدعوى الانتساب إلى السلف، والأخذ بالكتاب والسنة، وساعدهم على رواج دعواهم انتشار الجهل بين الناس، وعدم علمهم بما كان عليه السلف الصالح، وقلة تفقههم في أصول الدين وفروعه، كما هو الشأن عند اقتراب الساعة جدا، وفاقا لما جاء به الصادق المصدوق عليه وعلى آله أفضل الصلوات وأنمى البركات ((لا تقوم الساعة حتى يقل العلم ويكثر "], [10, "الجهل)) وفي الحديث الآخر ((لا تقوم الساعة حتى يؤتمن الخائن ويخون الأمين، ويقبض العلم ويلقى الشح)) وفي لفظ آخر ((إن الله لا يقبض العلم انتزاعا ينتزعه من صدور العباد، ولكن يقبض العلم بموت العلماء، حتى إذا لم يبق عالم اتخذ الناس رؤسا جهالا، فسئلوا فأفتوا بغير علم، فضلوا وأضلوا)). وسأل سائل النبي صلى الله عليه وسلم: ((يا رسول الله متى الساعة؟ فمضى في حديثه ولم يجبه، حتى ظنوا أنه لم يسمع ما قال، أو سمعه ولكن كرهه، ثم قال عليه الصلاة والسلام: أين السائل؟ قال: ها أنا ذا يا رسول الله، قال: إذا ضيعت الأمانة فانتظر الساعة. قال كيف إضاعتها؟ قال: إذا أسند الأمر إلى غير أهله)) وفيه ((لا تقوم الساعة حتى يبعث دجالون كذابون يحدثونكم بما لم تسمعوا أنتم ولا آباؤكم، فإياكم وإياهم لا يفتنونكم ولا يضلونكم)) وفي الحديث الآخر ((سيكون في آخر الزمان أقوام حدثاء الأسنان سفهاء الأحلام، يقولون من قول خير البرية، يمرقون من الدين كما يمرق السهم من الرمية)) والرمية فعيلة، بمعنى مفعولة من الرمي، وكل ذلك في الصحاح إلى أشباه له كثيرة، بحيث إذا أحطت بها خبرا رأيت كأن النبي صلى الله عليه وسلم مع أهل كل زمان يحاضرهم ببيان ما هم عليه من فساد، وينصحهم أثمن النصائح وأغلاها بما ينجيهم من ذلك الفساد، وينقذهم يوم التناد، فجازاه الله عن أمته خير الجزاء، ولا عجب فهو المخاطب بقوله تعالى {وَعَلَّمَكَ مَا لَمْ تَكُنْ تَعْلَمُ وَكَانَ فَضْلُ اللَّهِ عَلَيْكَ عَظِيمًا} [النساء: 113] ومن ذا الذي يعرف قدر هذا الفضل، وقد استعظمه الملك الكريم الأكرم الذي هو من كل عظيم أعظم؟ وقد أخرج الإمام أحمد في مسند أبي بكر من مسنده رضي الله عنهما ((أنه عليه الصلاة والسلام صلى الصبح ذات يوم واستمر على جلوسه في مصلاه لا يتكلم ولا يكلمه أحد، حتى إذا كان ساعة الضحى ضحك واستمر على جلوسه وسكوته اليوم كله، لا يقوم إلا لأداء الفريضة، ويعود إلى حاله، ففزع أصحابه الكرام فكلموا أبا بكر رضي الله عنه أن يستخبر لهم عن الأمر، فقص الحديث. وفيه أن رسول الله صلى الله عليه وسلم قال له: عرض على ما هو كائن "], [11, "من أمر الدنيا وأمر الآخرة)) وفي رواية لغير أحمد ((إن ربي أطلعني في يومي هذا على ما كان وعلى ما يكون)) فمن ذا الذي يحصى خصائص هذا النبي الكريم ويقدر نصائحه وجهاده وغناءه وعناءه لمصلحة النوع البشرى كله، من ذا الذي يقدر ذلك حق قدره؟ وتالله ما بالغ مادحه حيث يقول\rفمبلغ العلم فيه أنه بشر. وأنه خير خلق الله كلهم\r(فصل ما من بدعة إلا وفي كتاب الله وسنة رسوله الرد عليها)\r"]], "pg": [7, 11]}, "526.3": {"x": [[11, "واعلم أنه ما من بدعة حدثت أو نحدث بعده عليه الصلاة والسلام وإلا وفى كتاب الله وسنة رسوله صلى الله عليه وسلم الرد عليها، والمخرج عنها، لقوم يفقهون، أجزل الله حظنا وحظك من الفقه في دينه، وآتانا وإياك الفهم في كتابه، وكمال العلم بما تهدى إليه سنة نبيه. ومن ظن أن أهل العلم فضلا عن سواهم سواسية في فهم الكتاب والسنة، فقد ظن خطأ وبعد عن الصواب بعد الشمس عن الأرض، إلا أنه ليس عليه ضياء. وبيانا لهذا التفاوت حث رسول الله صلى الله عليه وسلم حاضري مجلسه الشريف، ومقاماته المنيفة، أن يبلغ اشاهد الغائب. ففي صحيح البخاري وغيره ((ألا ليبلغ الشاهد الغائب فرب مبلغ أوعى من سامع)). فلم يقتصر على الأمر حتى بين لهم عليه الصلاة والسلام سر الأمر وحكمته، وفي لفظ آخر ((نضر الله أمرا سمع منا حديثا فوعاه وأداه كما مسمعه، فرب حامل فقه إلى من هو أفقه منه)) وفي لفظ آخر ((رب حامل فقه ليس بفقيه)) رواه البزار بإسناد حسن وابن حبان في صحيحه وصححه الحافظ المنذري ــ صلى الله وسلم وبارك عليه ما أحسن ما رسم، ولو أن الناس وقفوا عندما رسم ما نكبت الأمة بهذه البدع الشنيعة في الأصول والفروع، فانظر إلى قوله الشريف للراوي عنه ((كما سمعه)) فهو تصريح بالحجر على غير الفقيه أن يخوض فيما رواه بزيادة تفسير أو تأويل، ولكن يدع الأمر في ذلك لمن تأهل له، فما كل من روى يقبل رأيه الذي رأى، ولا كل "], [12, "من حفظ للفظ كان أهلا لبيان كنه المعنى وما يتلبط منه، وإذا كان ذلك كما وصفنا في كلام رسول الله صلى الله عليه وسلم فما ظنك بكلام رب العالمين؟ وواضح كل الوضوح أن كلكل فن مؤهلات، فمن خاض فيه بدونها كان خطؤه أكثر من صوابه وضرره أقرب من نفعه.\rوكان الناس في الصدر الأول على الحدود التي حدها لهم أعرف الناس بالهدى وطرقه، وأرحمهم بهم صلى الله عليه وسلم، فعم الخير كل أمور هم علميها وعمليها، ولما بدأ الناس يبعدون عن عهد النبوة شرعت شرا ذم منهم تتخطى الحدود، فتكلم غير الفقيه فيما روى بما رأى، وقال في الأمور العامة من لا يحسن أموره الخاصة، وتحقق ما أخبر به النبي صلى الله عليه وسلم من أن الساعة ((لا تقوم حتى يتكلم الرويبضة)) وهو تصغير رابض والتاء للمبالغة لا للتأنيث، وهو الرجل الحقير: ربض عن معالي الأمور أي قعد عنها. وقد روى في الحديث تفسيره قيل: يا رسول الله ما الرويبضة؟ قال: ((الرجل التافه ينطق في أمور العامة)) وما زال أولئك الشذاذ يتعصبون لأهوائهم، ويتبعهم أمثالهم، وكثير من الناس ــ كما قال الإمام علي رضي الله عنه ــ همج رعاع أتباع كل ناعق. وطال العهد حتى صار لكل خلف ــ بسكون اللام ــ من تلك الطوائف سلف طالح، كما للخلف السلف الصالح، وقد ثبت في الحديث مرفوعا ((بحمل هذا العلم من كل خلف عدو له ينفون عنه تحريف الغالين وانتحال المبطلين، وتأويل الجاهلين)) رواه عن النبي صلى الله عليه وسلم عدة من الصحابة، وأخرجه ابن عدى من طرق، وجزم الحافظ العلائي بأنه حديث حسن، ورواه النووي في أول تهذيبه، وشرح ما يستنبط منه.\r(فصل: بيان أن بعض الحفاظ وقع في الخطأ لخوضه فيما لا يحسنه)\r"]], "pg": [11, 12]}, "526.4": {"x": [[12, "ومما يؤسف له جد الأسف أن بعض الحفاظ للسنة وقع في هذا الخطأ الكبير فخاض في تفسير الأحاديث المتشابهة وقال في ذات الله وصفاته ما أنكره "], [13, "عليه أجلة الفقهاء لهذا الشأن الأعلى. والفقه فقهان فقه أكبر وهو العلم المتعلق بما ينبغي لله وما لا ينبغي له، وما يتصل بذلك وهو المسمى في عرف المتأخرين بعلم الكلام، وفقه كبير وهو العلم بالأحكام الشرعية العملية. ومن الغلط العظيم الذي وقع فيه الكثير من الناس، فاضلهم ومفضولهم، أن يؤخذ عن الرجل ما لا يحسنه، لأن له الأمامة في فن آخر أحسنه، وكثيرا ما يكون الرجل إماما في علم الأصول وهو متوسط أو دون المتوسط في علم الفروع، وبالعكس، وإماما في الحفظ ونقد الرجال ومتون الأحاديث والعلل، وهو في غير ذلك نازل كل النزول، حتى إنك لتعده فيه من العامة، وأنت إذا أحكمت الفكر واطلعت على طبقات الرجال وعرفت أحوال أهلها، رأيت لما قلنا شواهد كثيرة لا تدع مدخلا للشك إلى نفسك في ذلك، ولو شئنا لتحدثنا إليك عن كثير من أهل العلم كان لهم التقدم الفائق في الفن والفنين والأكثر، فإذا تكلموا فيما أحسنوا رأيت منهم أئمة سادة، ونقدة قادة، وإذا نطقوا في غيره شهدت غبا تندهش له، وعامية لا ينقضي منها عجبك، بيد أن هذه الرسالة عجالة نريد فيها الاختصار بقدر الاستطاعة، ومن هنا تعلم السر فيما قال المصطفى صلى الله عليه وسلم ((أنزلوا الناس منازلهم)) وقد احتج به الإمام مسلم ابن الحجاج المتوفى سنة إحدى وستين ومائتين في مقدمة صحيحه على من يروى عن الضعفاء كأنه يسوى بينهم وبين الثقات، وأصاب رضي الله عنه، فمن كان إماما في حفظ الحديث والخبرة بالأسانيد والعلل فليؤخذ عنه ما هو مبرز فيه من الحكم بصحة الحديث أو حسنه أو ضعفه أو وضعه، أما بقية علوم الحديث دراية كاللغة والصرف والنحو وما إلى ذلك من علوم العربية والفقه بقسميه فلا يؤخذ عنه، فربما كان عاميا أو قريبا منه في بعض هذه الفنون أو كلها، بل ربما ادعى لنفسه بغير حق التبريز والأمامة في غير ما هو مبرز فيه، فأفتى وألف، فلا يغرنك منه ذلك، وإذا أنت أردت ميزانا صادقا تعرف به حقيقة دعوى الرجل فدونك هذا الميزان: ترجع إلى أهل الفن الذي تكلم فيه فتنظر ما قدر الرجل عندهم "], [14, "فبشهادتهم تأخذ، فهم الإخصائيون بالفن، والذين يتميز لديهم المدعى من الصادق، ويستحيل في العادة أن يجمع أهل الفن على القدح في رجل حسدا وبغيا، هذا ولا يسقط الرجل عن إمامته فيما فاق فيه تبعيته لغيره فيما لم يحسن، ورد قوله فيه إذا هو افتأت على الكلام فيما ليس له بأهل. وتاريخ الجهابذة حافل بأخذ كل فن عن إمامه، وأهل الاتقان له، هذا تاج الدين السبكي كان الذهبي من شيوخه في الحديث، وشهد له بالحفظ، ولم يكن يتبعه في آرائه الخاصة المنحرفة، وشهد له وعليه، فقال بعد ما أثنى على حفظه ((والحق أن شيخنا كان قليل الخبرة بمدلولات الألفاظ)) ومثل لذلك بما لا نطيل به. وهذا محمد بن إسحاق بن خزيمة المتوفى سنة إحدى وعشرين وثلاثمائة، له الامامة في الحفظ والعلم بالعلل في المتون والأسانيد وفنون سوى علم الكلام، قال فيه الأستاذ الأجل أبو سهل الصعلوكي المجمع على إمامته في الحديث وأصول الدين وفروعه، المتوفى سنة تسع وستين وثلاثمائة، وهو أحد الرواة عنه ــ حين ألف كتابه الذي سماه التوحيد ــ: إن شيخنا تكلم في ما لا يعنيه. وطعنه الإمام فخر الدين الرازي المتوفى سنة خمس وستمائة في تفسيره بما لعلنا ننقله لك في موضع آخر وإنما أتى هذا الامام المحدث من قبل دخوله فيما لا يحسنه. وفي الأثر ((رحم الله امرأ عرف قدره ولم يتعد طوره)) هذا هو دأب الذين يريدون أن يحيوا سنة نبيهم ويأتوا البيوت من أبوابها، وبفضل الله تعالى ويمن رسوله الكريم توفرت الجماعات المبرزة في الفنون المتعلقة بالدين مباشرة أو بواسطة، واختلفت الدواعي فكثر الاخصائيون حين امتد رواق الإسلام على المشارق والمغارب، حتى تمحصت الحقائق، وصارت العلوم الاعتقادية والخلقية والعملية لبا بلا قشر، وزبدا لا يحتاج إلى مخض ورجعت سهام مكايد أعداء الإسلام في نحورهم، وصار من أجلي الجليات أن حامل لواء السنة في العقائد الإسلامية أبو منصور الماتريدي المتوفى سنة نيف وثلاثين وثلاثمائة، وأبو الحسن الأشعري المتوفى سنة بضع وعشرين وثلاثمائة وشيعتهما، وفي الفقه الشرعي الأئمة الأربعة، والمبرزون من أتباعهم، وفي علم أحوال القلوب الجنيد المتوفى سنة بضع وتسعين ومائتين، وأبو القاسم القشيري المتوفى سنة خمس وستين وأربعمائة، ومن على شاكلتهما. وقد كثر من هؤلاء الافاضل متقدميهم ومتأخريهم المصنفات بين مطول ومختصر وبين ذلك. وكان الناس بخير أيام كانوا يرجعون إلى الاقتباس من هؤلاء النجوم، والاعتراف من أنهار علومهم العذبة الجارية إليهم من بحار الكتاب والسنة.\rأما وقد ديست هذه الرسوم وانتهكت تلك الحرم، واجتمع في كثير من أهل هذا العصر المهلكات الثلاث: الشح المطاع، والهوى المتبع، وإعجاب المرء برأيه، فقد أصبح من الواجب الأكيد، واللازم المحتم، أن أقدم لك أيها الأخ نصيحة تطرد عنك إن شاء الله هذه الظلم المنتشرة، وتزيح عن مشام روحك دخان هذه البدع التي صارت بعد خمولها مشتهرة، وهي نسأل الله السلامة منها ــ كثيرة جدا، ليس في وسع هذا المختصر استقصاؤها، فسأذكر لك أشدها خطرا، وأعمقها في إفساد القلوب وسد أبواب الرحمة الآلهية أثرا، وأكثرها التباسا على من لم يمارس علوم الكتاب والسنة، فان دعاتها ينادون الناس إليها باسم الكتاب والسنة فيما يزعمون، وأنها طريق السلف الصالح، ولذلك تسمعهم يلقبون أنفسهم بأنهم السنيون والسلفيون، وإني بادئ بما هو الأهم من ذلك، وهو ما تعلق بذات الله تعالى وصفاته، فان هؤلاء المبتدعة وصفوا الله تعالى بصفات خلقه، فجوزوا عليه الجلوس والنزول الحسيين، والأجزاء كالوجه والعين واليد والرجل الحسيات، ونسبوا إليه سبحانه المكان والجهة، تمسكا بآيات من الكتاب يقرؤن كملها يحرفون الكلم عن مواضعه، وتمسحا بظواهر أحاديث كثير منها مما لا يحتج به، لما بينه أهل النقد من عالمها، والصحيح منها أجل وأعلا من أن تحوم حول رفيع معانيه هذه الافهام العامية الساقطة، وماذا نصنع وقد امتلأت هذه النفوس عجبا، وسالت ألسنتها زراية على الأولين والآخرين، من أئمة هذه الأمة وأكابرها، "], [15, "ونبزوهم بما استطاعوا من الألقاب الشائنة، وليس لهم ذنب عندهم إلا أنهم فرقوا بين الخالق والمخلوق، فقالوا بتنزيه الله في ذاته العلية، وصفاته المقدسة عن كل ما يختص بالأكوان، وجعلوا القرآن إمامهم في هذا الفرقان، واستغل أولئك النفر جهل كثير من أهل هذا العصر بتاريخ هذه الفرق الجاهلة، فأوهموا الناس أنهم يمثلون السلف الصالح من الصحابة ومن بعدهم من التابعين لهم بإحسان، والتاريخ يشهد والعلم بكتاب الله ينادي أنهم ما مثلوا إلا سلف سوء من أشياخ المشبهة وأئمة المجسمة، الذين يفسرون الكتاب بأهوائهم، ويحملون السنة على آرائهم، ويتقولون على معاني كتاب الله؛ ويضعون على رسول الله، ويأخذون بالضعيف إذا وافق منهم هوى، ويردون الصحيح أو يشككون في صحته إذا كان حج عليهم.\r(فصل: من أراد فهم هؤلاء الفرق)\r"]], "pg": [12, 15]}, "526.5": {"x": [[15, "أما قولنا إن التاريخ يشهد فيكفيك في بيانه أن تطلع على الكتب المبينة للفرق بعد النبي صلى الله عليه وسلم، ككتاب الفصل لابن حزم، والفرق بين الفرق للإمام المحقق عبد القاهر البغدادي، والملل والنحل للشهر ستأتي، وعلى كتب الطبقات كطبقات تاج الدين السبكي، وتهذيب التهذيب ولسان الميزان كلاهما للحافظ ابن حجر العسقلاني، وعلى الكتب الموضوعة في التاريخ العام، كتاريخ ابن الأثير وغيره، فستجدها ناطقة بأن فرقة المشبهة ليست وليدة عصرنا هذا، بل لها عرق ممتد إلى زمن التابعين، وكثيرا ما كانت أستارهم التي ينحجبون بها عن العامة وبعض الخاصة ممن سلم صدره ولم يعن بالتفتيش عن أطوارهم ومؤلفاتهم، هي التزهد والتقشف والاشتغال برواية الحديث وجمعه حتى إذا عرفوا نبذوا، وكان أهل الحق يلقبونهم بألقاب تكشفهم لمن لا يعرفهم: بالمشبهة لتشبيههم الحق تبارك وتعالى بخلقه في وصفه بما هو من خواص الخلق، وبالمجسمة لقولهم في الله "], [16, "تعالى بالاتصاف بما هو من لوازم الجسم لزوما بينا كما ستعرفه إن شاء الله تعالى، وبالحشوية نسبة إلى الحشو بسكون الشين، وهو اللغو الذي لا اعتبار له، فضلا عن أن يكون منسوبا إلى الله وإلى رسوله، أو مذهبا يدان الله تعالى به. وما زال أهل الحق لهم بالمرصاد ــ وهم الكثرة من علماء هذه الأمة في كل زمان بحمد الله تعالى ــ يناظرونهم حتى يفحموهم، ويسردون في الطبقات تاريخهم، ويصنفون المصنفات في الرد على مفترياتهم. اقرأ ترجمة مقاتل بن سليمان المتوفى سنة خمسين ومائة في تهذيب التهذيب، فستجد شهادة إمام الأئمة أبي حنيفة رضي الله عنه ــ وهو من هو في علم أصول الدين وفروعه، والآخذ عن بعض الصحابة وأكابر التابعين ــ تجد هذا الإمام الأعظم شهد على هذا الرجل أنه الذي حمل إليهم من خراسان بدعة التشبيه، ولفظه رضي الله عنه: ((أتانا من المشرق رأيان خبيثان: جهم معطل، ومقاتل مشبه)). وقال أيضا: ((أفرط جهم في النفي حتى قال إن الله ليس بشيء، وأفرط مقاتل في الأثبات حتى جعل الله تعالى مثل خلقه)). فانظر كيف سماها بدعة وقال إنها آتية من ناحية بلاد العجم، ولم تأتهم من ناحية العرب والبلاد التي هي نهضة الوحي. وانظر إلى إمام دار الهجرة مالك بن أنس رضي الله عنه كيف اشتد على من قال له: الرحمن على العرش استوى، كيف استوى؟ وعلته الرحضاء أي العرق الكثير وقال: ((ما أظنك إلا صاحب بدعة)) وإنما ظنه كذلك لأن سؤاله عن كيفية الاستواء يدل على أنه فهم الاستواء على معناه الظاهر الحسي الذي هو من قبيل تمكن جسم على جسم واستقراره عليه، وإنما شك في كيفية هذا الاستقرار فسأل عنها، وهذا هو التشبيه بعينه الذي أشار إليه الإمام بالبدعة، ويوضحه ما روى اللالكائي في شرح السنة بالسند أن الإمام قال في جوابه هذه العبارة، ((الاستواء مذكور، والكيف غير معقول، والإيمان به واجب، والسؤال عنه بدعة)) إلى آخره. فمن رواه ((الاستواء معلوم والكيف مجهول)) ينبغي أن ترد "], [17, "روايته إلى هذا المعنى، يعني أن الاستواء معلوم الورود في الكتاب، فيرجع إلى قوله في الرواية السابقة ((الاستواء مذكور)) وقوله: والكيف مجهول. أي لا تعلم له ماهية بالمعنى المتعارف، ولا يعقل له وجود فيما يتعلق بجناب الحق جل وعلا، فيرجع إلى قوله في تلك الرواية ((والكيف غير معقول)) لا أن هناك كيفا وصفة لذلك الاستقرار لكنها لا تعلم، فان أصل الاستقرار والتمكن لا وجود له، فضلا عن صفته، ومن ظن بالإمام سوى هذا فقد غلط، كيف لا وقد ثبت النقل عنه أنه سئل عن حديث النزول فقال ((هو نزول رحمة لا نزول نقلة)) وممن ذكر ذلك عنه أبو بكر بن العربي. وكان رضي الله عنه لا يعجبه من المحدث ان يحدث العامة بهذا الحديث وأشباهه مما يوقعهم في ورطة التشبيه، وله رضي الله عنه في هذا وجه وجيه، ونظر سديد. ويؤيده من السنة ما روى مسلم في صحيحه عن معاذ بن جبل رضي الله عنه أنه سأله صلى الله عليه وسلم عن حق الله على عباده وحق العباد عليه تعالى الحديث، وفيه ((أفلا أخبر الناس))؟ يعني العامة فقال صلى الله عليه وسلم ((إذا يتكلوا)) فقد منع صلى الله عليه وسلم ((العالم من تعليم بعض العلم، إذا لم يكن لمتعلم يحسن فهمه ويتأوله على غير وجهه، فانه حينئذ يكون ضلالا له، ووبالا عليه. ووقع نحو هذه القصة لأبي هريرة رضي الله عنه أخرجها البخاري رحمه الله تعالى بطولها. وكذلك قال الإمام الأجل أبو عبد الله الشافعي رضي الله عنه ((آمنت بما جاء عن الله على مراد الله. وبما جاء عن رسول الله صلى الله عليه وسلم على مراد رسول الله)) يعني رضي الله عنه لا على ما تفهم العامة من المعاني الحسية الجسمية. ونقل ابن الجوزي في كتابه ((دفع شبه التشبيه)) عن الإمام أحمد رضي الله عنه نحوا من هذا، فرد أبلغ الرد على المنتسبين إليه الناسبين له ما هو براء منه، ولهذه الفتة ولع شديد بافتراء الأباطيل ونسبتها إلى أكابر أئمة هذه الأمة، ولو استقريت القرون منذ نجمت هذه البدعة لرأيت في كل قرن إلى زمانك هذا من هذه الطائفة فلولا تشاغب وتموه وبأزائهم جيوشا من أهل "], [18, "السنة بحق تدافع وتبين، بين مناظر يجادل عن الحق في المجالس الخاصة والعامة، ومؤلف يزيل ظلمات شبههم بنور الحجج المعقولة المنقولة حتى تركوا من هذه المؤلفات القيمة لطالب الهدى ثروة لا تنفد، وكنوزا لا تبيد. على الأبد، ومن هذه الكنوز الفائقة وتلك الثروات العظيمة، كتاب الإمام الحافظ الثقة الحجة المبرز في علم الحديث رواية ودراية، علم الفقهاء أبي بكر أحمد بن الحسين ابن علي البيهقي المتوفى سنة ثمان وخمسين وأربعمائة. كثر في زمانه رضي الله عنه الخوض في أسماء الله تعالى وصفاته بما لا يليق بجنابه عز وجل، فألف كتابه المسمى ((بالأسماء والصفات)) قال الإمام تاج الدين السبكي: لا أعلم له في بابه نظيرا. وصدق رضي الله عنه فانه عمد فيه إلى جمع الأحاديث التي تعلقت بها المبتدعة من المشبهة والحشوية، فبين ما لا يصح الاحتجاج به منها بذكر ما فيه من علة، وأزال الاشكال عما صح من متشابهها، وضم إليها ما ناسبها من آيات الكتاب. وأضاف إلى ذلك ما قال أكابر العلماء ممن قبله. فجزاه الله عن دينه وأمة نبيه صلى الله عليه وسلم خير الجزاء، كأنه رضي الله عنه قصد بكتابه هذا غسل العار الذي ألحقه الحافظ ابن خزيمة بأهل الحديث، فانه ألف كتابا سماه ((كتاب التوحيد))، وليته اقتصر فيه على جمع الأحاديث المتشابهة، ولكنه فسرها بما لا يصح أن يعتقد في الله تعالى، ولا يقول به المحققون من سلف ولا خلف، وقد طعنه الإمام فخر الدين الرازي طعنة أردته قتيلا، حيث قال رضي الله عنه في تفسير قوله تعالى {لَيْسَ كَمِثْلِهِ شَيْءٌ} [الشورى: 11] واعلم أن محمد بن إسحاق بن خزيمة أورد استدلال أصحابنا بهذه الآية في الكتاب الذي سماه بالتوحيد، وهو في الحقيقة كتاب الشرك، واعترض عليه، وأنا أذكر حاصل كلامه بعد حذف التطويلات، لأنه كان رجلا مضطرب الكلام، قليل الفهم، ناقص العقل اه. ثم ساق كلامه وهو كلام لا يقوله مؤمن محقق نافذ البصيرة في المعرفة بربه، ولذلك ضربنا عن نقله ولئلا يتشوش به ضعيف، ثم قال الامام الفخر رضي الله عنه: وأقول هذا المسكين الجاهل إنما وقع "], [19, "في أمثال هذه الخرافات لأنه لم يعرف حقيقة المثلية وعلماء التوحيد حققوا الكلام في المثلية، إلى أن قال: وإن هذه الكلمات التي أوردها هذا الإنسان إنما أوردها لكونه كان بعيدا عن معرفة الحقائق، فجرى على منهج كلمات العوام، فاغتر بتلك الكلمات التي ذكرها، ونسأل الله حسن الخاتمة)) أهـ\rومن قرأ توحيد ابن خزيمة عذر هذا الإمام فيما قال، وقد أسلفنا لك أن الأمامة في الحفظ والعلم بالعلل في متون الأحاديث وأسانيدها لا تقتضي الامامة المطلقة في كل فن، وذلك ظاهر لا يحتاج إلى بيان، فلا ينبغي أن يقتدي به إلا فيما هو إمام فيه، ومن خالف هذه القاعدة لم يسلم له دينه في أصول ولا في فروع، فنصيحتي لك إذا أردت السلامة لنفسك أن تكون في عقائدك على ما دونه الامامان أبو منصور الماتريدي وأبو الحسن الأشعري، فانه هو ما يهدي إليه كتاب الله وسنة رسول الله صلى الله عليه وسلم، من غير ميل إلى جانب إفراط أو تفريط، وأن تكون في الفروع على مذهب أحد الأئمة الأربعة رضي الله عنهم، وأنت إذا انتصحت بهذه النصيحة ولم تحد عنها كنت على طريق الصحابة والتابعين لهم بإحسان، فان من سمينا لك من الأئمة هم سالكوها والناشرون لها، والذابون عنها والداعون إليها، ونسبة الاتباع إليهم إنما هو لذلك فقط. لا لأنهم مبتدعوها حاشهم من البدع، وكيف وهم الذين أطفأوا نيران البدع، وأحيوا نور السنن، ولولاهم وعلماء أتباعهم لكان الناس اليوم على غير ما جاء به المصطفى صلى الله عليه وسلم، فشكر الله سعيهم، وجعل محيانا ومماتنا على سبيلهم، إنه الجواد الكريم.\r(فصل: في بيان كتاب البيهقي)\r"]], "pg": [15, 19]}, "526.6": {"x": [[19, "قرأ علينا ولدنا النقي العالم العامل المحب للسنة نجم الدين ابن شيخنا شمس العارفين وقطب الواصلين، قدوتنا إلى الله تعالى، الشيخ محمد أمين، هذا الكتاب ((كتاب الحافظ البيهقي)) فإذا هو في بابه نادر المثال، رفيع الموضوع "], [20, "بل موضوعه أرفع المطالب وأسسناها، فانه في الأسماء العلية والصفات المقدسة الربانية، وفد زينه بالآيات والأحاديث المصطفوية، على صاحبها أفضل صلاة وأجل تحية، ونوره بكلمات المحققين من سلف هذه الأمة الصالح، وحملة السنة السنية، الذين هم على الصراط المستقيم، فرغيب في طبعه بهذه الديار المصرية، حبا في العلم، ونشرا للسنة، وإحياء لمذهب السلف الصالح، وليعلم من لا خيرة له بتاريخ البدع ومروجيها أن ما انتشر في زماننا من القول بالجهة والأعضاء والحركة في حق ربنا تبارك وتعالى، إنما هو قول سلف المبتدعة، ومن اغتر بزخرف قولهم من المحدثين الذين لم يبرعوا في معقول، ولم يقفوا عند منقول، نعوذ بالله من الفتن ما ظهر منها وما بطن، فحمدنا الله على هذا التوفيق، ورغب إلينا لفيف من أهل العلم أن نضع على هذا الكتاب تعليقات توضحه، فلم نره في حاجة كبيرة إلى ذلك، بعد الذي تفضل بوضعه عليه العلامة المدقق والفهامة المحقق، الأستاذ الكبير الشيخ محمد زاهد الكوثري ورأينا أن أولى ما نقدمه بين يدي هذا الكتاب، وأحرى ما تتوجه إليه العناية، هي رسالة نبين فيها وجه إطباق المحققين من سلف أهل السنة وخلفهم، على صرف آيات الاستواء على العرش والوجه والعين واليد وما شابهها من الآيات والأحاديث عن الظاهر المتبادر لأذهان العوام وعدهم ذلك من المتشابه بلا خلاف بين متقدميهم ومتأخريهم، في أن المعنى الظاهر الحسى الذي هو من لوازم الأجسام غير مراد لله ورسوله قطعا ولا شك أن هذا منهم رضي الله عنهم إجماع على التنزيه، غير أن أكثر المتكلمين لم يتكلموا في تعيين المراد، واكتفوا بتفويضه إلى الله ورسوله، وهل يسمى ذلك تأويلا أولا؟ رأيان للناظرين، والكثيرين ممن بعدهم تكلموا في تعيينه على ما تقتضيه اللغة التي نزل بها القرآن على ما سيأتيك تفصيله إن شاء الله تعالى.\rويتنجز القول في هذا المطلب الأعلى وما يتبعه في مقدمة مقصد وخاتمة فالمقدمة في أمور لا يستغنى طالب هذا المطلب الأعلى عن معرفتها قبل "], [21, "الاشتغال بتحصيله، والمقصد في الفرق بين الصفات المختصة بالخلق والصفات المختصة بالحق، على ما يرشد إليه الكتاب العزيز، ويهدي إليه القرآن الحكيم والعقل السليم، فان هذا القرآن يهدي للتي هي أقوم والخاتمة في بيان معنى الإيمان والكفر، وفيها يتبين لك أن التوسل والتشفع والاستغاثة بالنبيين عليهم الصلاة والسلام، والصالحين رضي الله عنهم، بعد وفاتهم، مع اعتقاد أنهم مفاتيح الرحمة وأسباب الخير، والفاتح لها بهم هو الله وحده، ليس شركا ولا كفرا، ولا حراما ولا مكروها، بل هو سبيل المؤمنين، وطريق عباد الله المرضيين. وسميناها ((فرقان القرآن بين صفات الخالق وصفات الاكوان)) والله نستعين على تيسير ما أردنا به النصح للامة، وإياه نسأل متوسلين إليه سبحانه بأكرم خلقه عليه، وأحبهم إليه، سيدنا ومولانا محمد نبي الرحمة وبجميع المرضيين عنده سبحانه، أن يجعل ذلك العمل خالصا لوجهه الكريم، وسببا للفوز برضاه الدائم العميم، ولا حول ولا قوة إلا بالله العزيز الحكيم.\rالمقدمة\r"]], "pg": [19, 21]}, "526.7": {"x": [[21, "وفيها فصول تلقى لك أضواء على هذا المقصد الأسنى الذي هو تمييز ما للخالق من الصفات، على ما يدل عليه كتاب الله تعالى، ويهدي إليه الفهم الصحيح فيه، والله نستعين على تنزيل هذه المعاني العليا إلى المستوى الذي لا يعلو على العامة ارتقاؤه، ولا يخفى على الخاصة ضياؤه\r(فصل: في أقسام الحكم العقلي)\r"]], "pg": [21, 21]}, "526.8": {"x": [[21, "ينقسم الشيء باعتبار قبوله للاتصاف بالوجود أو العدم إلى أقسام ثلاثة: ممتنع لذاته، وممكن لذاته، وواجب لذاته، ومن السهل عليك أن تفهم ذلك، فان اتصاف الولد بالوجود قبل أن يوجد أبوه ممتنع أو مستحيل أو غير جائز، كيفا"], [22, "شئت من هذه الألفاظ فقل. فالمعنى واحد. واتصافه بالوجود بعد وجود أبيه، وقبل أن يرزقه أبوه، ممكن، أو جائز أو غير ممتنع ولا واجب، وكذلك هو بعد أن يولد، إلا أنه قبل أن يولد ممكن لا يزال في العدم، وبعد أن يولد هو ممكن قد كساه الوهاب حلة الوجود، وجميع ما تراه أو تحس به من هذه الموجودات العلوية والسفلية هو من هذا القسم أي (الموجودات الممكنة) وأما واجب الوجود الذي لا ابتداء لوجوده ولا انتهاء له، ولا يقبل وجوده الزوال ولا الانتفاء بوجه، فلا يكون إلا واحدا وهو الله جل جلاله، على ذلك قامت البراهين، وامتلأ بها كتاب الله، كما أركزها في الفطر السليمة، وأقرها في العقول المستقيمة واهب الكائنات ذواتها وصفاتها وحاجاتها، تبارك وتعالى. إنك لا تنفك ترى أشخاصا من النبات والإنسان والحيوان توجد بعد أن لم تكن، وأشخاصا منها تنعدم بعد أن وجدت، فالحكم عليها بالإمكان لا يحتاج منك إلى تأمل، وهو ما يسميه أهل العلم بالبديهي، وأما ما شاهدت دوامه في العوالم العلوية والسفلية كالكواكب والجبال، فتستطيع أن تعرف نزولها عن ذروة الوجوب واستقرارها في حضيض الإمكان دائما أبدا، متى عرفت هذه النظرية الواضحة، وهي أن مادة هذه العوالم كلها يستحيل عليها أن تكون موجودة إلا وهي موصوفة بالبساطة، أو التركيب والمراد بالبساطة في هذا المقام عدم قبول الشيء للانقسام لصغر حجمه جد الصغر، وبالتركيب كونه بحيث يقبل الانقسام، سواء كانت أجزاؤه من عنصر واحد أو عناصر ومتصفة بالعلو المكاني كالكوكب أو التسفل كالأرض وبالطول والقصر وبالأضاءة والاظلام إلى غير ذلك من الصفات المتقابلة وكل صفة من هذه الصفات فهي معرضة لأن تزول وتحل محلها الصفة التي تقابلها، وما كان عرضة للزوال فهو ممكن، ومالا يتأتى وجوده إلا متصفا بالممكن فهو ممكن لا محالة، ومن ذا الذي يقول وهو من أهل العقول إن المادة لا تتبدل صفاتها؟ وهذه المعامل قائمة، فكفاك بقبول هذه الصفات للتبدل والتحول برهانا ساطعا على إمكان هذه الصفات، وما استحال "], [23, "وجوده بدون الممكن كان ممكنا بداهة، ومن أحكام الممكن أنه إذا وجد كان حادثا، أي موجودا بعد العدم، إذ لو لم يكن كذلك بل كان موجودا بلا ابتداء لوجوده لخرج عن دائرة الإمكان إلى الوجوب، كيف وقد فرضناه ممكنا، فكل ما تشخص وتعين من أفراد المادة فهو حادث بلا نزاع بين من يعتد به من كل من يحترم عقله، ويزن أفكاره بالميزان المنطقي الصحيح، وإذ قد بان لك أنك وما يدخل تحت حواسك منه ما هو ممكن بالبداهة وما هو ممكن بالنظر الصحيح، أمكنك أن تلمح نور وجود واجب الوجود جل علاه بالنظر الجلي، فان جميع الممكنات جملة وتفصيلا ليس وجودها من ذاتها، وإلا وجب لها الوجود، ولا من معدوم، فان المعدوم فاقد الوجود، وفاقد الشيء لا يعطيه بالضرورة، فلا بد أن يكون واهب الوجود لها موجودا سواها، والموجود الذي ليس ممكن إنما هو واجب الوجود، لا يشك في ذلك من أوتى حظا من الحكمة، ونال نصيبا من الفلسفة الصحيحة، ومن أجل ذلك قالت الرسل للأمم عليهم وعلى أتباعهم الصلاة والسلام (أفي الله شك فاطر السموات والأرض؟) وقال الخلاق العليم ينبه العقول إلى هذه القضية التي هي أوضح من الشمس، وهي أن ترجح وجود الممكن على عدمه بلا موجود واجب وجوده محال، قال تعالى {أَمْ خُلِقُوا مِنْ غَيْرِ شَيْءٍ أَمْ هُمُ الْخَالِقُونَ (35) أَمْ خَلَقُوا السَّمَاوَاتِ وَالْأَرْضَ بَلْ لَا يُوقِنُونَ} [الطور: 35، 36] فانظر إلى سياق القرآن هذا البرهان الساطع والدليل الناصع على هذا النظم العجيب، والأسلوب الآخذ بألباب أولى النهي، إلى جلية الحق، روى مسلم في صحيحه عن جبير بن مطعم أنه قد المدينة وهو مشرك فإذا رسول الله صلى الله عليه وسلم يقرأ في صلاة المغرب بسورة الطور قال فأصغيت إلى قراءته حتى إذا بلغ قوله تعالى (أم خلقوا) الخ، قال رضي الله عنه: كاد قلبي أن يطير، وأدخل الله على الإسلام، وأي أسلوب أعجب من هذا؟ فقد سيق هذا البرهان لا على الطريقة التي تدع لنفس السامع مجالا في التردد، ولكن على السبيل التي تقهر النفس على قبول الحق قهرا "], [24, "وتقسرها عن تلاعب الأوهام بها قسرا، فان الآية قد جعلت حدوث الحادثات ــ والحادث ممكن كما أسلفنا ــ بلا موجد يكون واجب الموجود من الأباطيل التي بطلانها في حيز الظاهر المكشوف الذي ينكر على من قال به إنكارا. فان (أم) في الآية الكريمة بمعنى بل، وهمزة الاستفهام، وهو هنا إنكاري بمعنى النفي. ولله الحجة البالغة على خلقه، فان الناس يعلمون أنهم ما كانوا شيئا مذكورا، ثم كانوا ووجود المعدوم بلا سبب موجود محال بداهة وكون المعدوم أوجد نفسه أظهر في الاستحالة وأبعد في الامتناع، وواضح أن من لا يملك وجود نفسه لا يستطيع أن يعطي الوجود لسواه، عسى أن يكون قد بان لك إن شاء الله أن جميع الممكنات الموجودة سواء كانت ذوات أو صفات فقيرة كل الفقر في جميع أطوارها، وكل تقلباتها، إلى من تعالى وجوده عن الإمكان، وجلت صفاته عن النقصان.\rولا يستخفنك أولئك الذين تعبدتهم المادة وأضاعت ظلمات الشهوات أفهامهم، فانكروا الملك القدوس واجب الموجود. فليسوا من العلم الصحيح بهذه النظرية في كثير ولا قليل. فانهم أخذوا على أنفسهم أنهم لا يؤمنون إلا مما به يحسون. وقصروا لفظ العلم على ما يدرك بالحواس، فأنى لهم وهذا شأنهم أن يظفروا بمعرفة من تعالى عن الحواس، وتقدس عن مشابهة المادة والماديات التي انقطعوا إليها، وما عرفوا إلا قليلا من ظواهرها، على اتساع معاملهم، وكثرة أبحاثهم. رأوا الكائنات المادية تجري على نظم محكمة، وقواعد مضبوطة يعبرون عنها بالنواميس. حتى إنك لتسمعهم يقولون: إن الطبيعة لا تلقى شيئا جزافا، فاستدلوا بهذا النظام العجيب المدهش لاساطيل المفكرين على إنكار واضعه جل جلاله: ولو كان الجزاف سائدا في الكون لكان للمنكر شيء من الشبهة، أما وهم المعترفون بالنواميس ودقتها، والنظم وإحكامها في الكون كله. من أصغر شيء وأحقره، إلى أكبر شيء وأعظمه، فقد اندحرت كل شبهة، وقام أسطع البراهين لا على وجود الخالق فحسب، بل على كمال رحمته وحكمته "], [25, "وعنايته، إلى غير ذلك من صفات مجده الأعلى، وكماله الأسنى، ولهذا تسمعه سبحانه يقول: {صُنْعَ اللَّهِ الَّذِي أَتْقَنَ كُلَّ شَيْءٍ} [النمل: 88] {الَّذِي أَحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ} [السجدة: 7] {مَا تَرَى فِي خَلْقِ الرَّحْمَنِ مِنْ تَفَاوُتٍ فَارْجِعِ الْبَصَرَ هَلْ تَرَى مِنْ فُطُورٍ} [الملك: 3] فوجود الممكنات ناطق بوجود واهبه، وإكمال وجودها وتوابعه صارخ بجلال كماله، وعظيم حكمته، ومناد بشدة ظهوره وسطوع نوره، حتى لهو عند أهل الأنظار السديدة، والأفكار الرشيدة، وأظهر من الشمس، وأبين من كل ما يحس، بل الكائنات كلها ظلمة وهو نورها، فإنها به كانت، وبه تبقى، فهو موجدها وقيومها، فإن وجود ذواتها وصفاتها لا يستفاد إلا منه وحده.\r(فصل في أن الأسباب المتوقفة بعضها على بعض)\r"]], "pg": [21, 25]}, "526.9": {"x": [[25, "فان كنت ممن يصارعه الشك وتغالبه الأوهام، من ناحية توقف بعض الممكنات على بعض، كتوقف الولد على الوالد، والنبات على البذر والحرث، والعناصر الخاصة، والبيئة المناسبة، وتوقف الأمطار على ما يصعد البخار من البحار، وما إلى ذلك مما تتوقف عليه الأمطار، وتوقف الكهرباء في إظهارها، والانتفاع بها على الأمور المبينة في علم الطبيعة، فتظن أن هذه الأمور المتوقف عليها هي أسباب عقلية لما بعدها، فاعلم أنك جفوت العلم ونبوت عن الفلسفة الصحيحة، ونكبت عن الجادة في فهم الحقائق على ما هي عليه؛ وتوضيح الأمر الذي يزول به الالتباس، وينقطع به عن الناظر الوسواس، أن تعلم أن المتوقف عليه على أقسام (فمنها) ما يكون من قبيل الشروط العقلية كوجود الموصوفات، يتوقف عليه وجود صفاتها القائمة بها (ومنها) ما هو من قبيل الشروط العادية، ككون المحس بالبصر على صفات خاصة ونسبة خاصة، من المبصر، يتوقف عليه الأبصار توقف المشروط على شرطه العادي (ومنها) ما يكون من قبيل المعد وهو ما يتوقف عليه وجود الشيء لكن ينعدم عند وجود الشيء، كالخطوة "], [26, "الأولى، فإن الخطوة الثانية يتوقف وجودها على وجود الأولى، وليست شرطا ولا سببا في وجود الثانية، فإن وجودها لا يكون إلا بعد عدم الأولى (ومنها) ما هو سبب في الوجود ومفيض له ولا يصلح الممكن كائنا ما كان لهذا الفيض وتلك السببية، فإنه لذاته لا يقتضي الوجود بل إذا أفيض عليه فهو لا يملكه لنفسه، فكيف يفيده غيره، بل لا يصلح لهذه السببية إلا واجب الوجود العلى الأعلى، تقدس وتعالى، فكل الممكنات التي يتوقف عليها كائن من الكائنات، فهي من قبيل الشروط أو المعدات، وليست من سببية الوجود في شيء ألبتة. فأتقن يا رعاك الله هذا المقام حق إتقانه، ولا يصدنك عن الامعان فيه كما ينبغي، من لا يصبر على تحقيق الحق؛ فيجانب الهدى ويسير وراء الهوى، وأنت لو دققت النظر لعرفت أنه ما أوقع الماديين في هذه الهوة السحيقة، والمهلكة العميقة التي هي إنكار رب العالمين، إلا اعتقادهم السببية العقلية للوجود فيما ليس بسبب، وإنما هو شرط أو معد، فنسبوا الأمر إلى غير أهله، ومنعوه أهله؛ وهو الحق تبارك وتعالى الدائم الوجود وفياض الجود وتوابعه على كل موجود. ولتقرير هذه الحقيقة العليا جاء في التنزيل (كل شيء هالك إلا وجهه) فالشيء في هذه الآية هو الموجود، وكل موجود سواه سبحانه فهو مملوك غير مالك، ولا لوجوده حال اتصافه به. فهو من حيث ذاته هالك بالفعل. والكلية في الآية على هذا التقرير لا يستثنى منها إلا ما استثنت الآية، وهو الحق جلت ذاته، وتعالت صفاته، ولك أن تقول في الآية: إن الهالك بمعنى القابل للهلاك وإن لم يقع هلاكه بالفعل، فتكون الآية مقررة لنفي وجوب الوجود عن جميع الكائنات: ماضيها وحاضرها وآتها، ومثبتة لا مكانها، فإن ما وجب وجوده لا يقبل الزوال كما مر، ولا يقبل الهلاك إلا الممكن، وعلى هذا التقرير فعموم الآية على ما هو عليه فيها، لا يخص منه إلا الواحد الوهاب، وما بقي منها أبدا كالجنة والنار وأصحابهما، فإنما بقاؤه لإرادة الخالق ذلك، وليس لأنه لا يقبل الهلاك. "], [27, "والكلام. في الآية الكريمة مسوق لإثبات وحدانيته في الألوهية على طريقة برهانية معجزة في إيجازها كعادة القرآن في شأنه كله، وبسط هذا المعنى الشريف أن يقال: كيف تدعون مع الله إلها آخر وتدعونه ــ أي تعبدونه ــ من دونه، والآله يجب له الكمال الأكمل، والكائنات كلها واقعة من النقص في الدرك الأسفل فما رأيتم هلاكه بالفعل فهو ظاهر النقصان، بديهي الإمكان، لا يحتاج في نفي الألوهية عنه إلى بيان، وكل ما تظنون دوامه وتتخيلون له عزة البقاء، فهو قابل للهلاك والفناء، فأين هو مما تدعون له؟ فهو بمعزل عن القدم، فإن الموجود الذي له القدم يستحيل عليه العدم فإنه لا يكون قديما إلا إذا كان واجب الوجود لذاته، وما للذات لا يزول، بل يمتنع زواله ويستحيل انتفاؤه، فإنه لازم من لوازم الماهية لذاتها وانتفاء لازم الماهية لذاتها يستلزم ألا تكون هذه الماهية هي نفسها، لأنها لو كانت هي نفسها لتبعها هذا اللازم، فلو صح انتفاؤه لصح أنها ليست هي إياها، وهذا معنى قولهم إن انتفاء لازم الماهية يؤدي إلى سلب الشيء عن نفسه، وكيف تسلب الذات عن ذاتها، هذا ما لا يعقل، ولهذا تسمعهم يقولون سلب الشيء عن نفسه محال بالبداهة، فكل شيء سواه هالك، والهالك لا يكون إلها، فلا إله إلا الله، فأحينا اللهم عليها وتوفنا عليها، واجعلها آخر صحائفنا بفضلك آمين ــ\rوبعد فلا تحسبن أيها الطالب للحقائق أن هذا من الشعر أو الخطابة، وإنما هي الحقيقة ناصعة، والحكمة مبرهنة، فإن من الممكن ما هو موجود بالبداهة كما سبق غير مرة، ووجود الممكن يعلن وجود الواجب قطعا، ولا يهولنك ما يموه به أولئك القائلون على العلم كذبا وزورا، إنه هداهم إلى إن المادة وحركتها لا ابتداء لهما، وبهما كان هذا الوجود كله الجاري على أتم نظام وحكمة.\rفأي علم هذا الذي يفترون عليه هذا الضلال المبين، أهو العلم التجربى الذي لا يعنون إلا إياه، ولا يدينون إلا له؟ فمتى شهدوا ذلك؟ وبأي تجربة وصلوا إلى هذا المعنى؟ وأين أعمارهم وأعمار الجاحدين من أسلافهم في جنب عمر الأرض "], [28, "التي هم عليها، فضلا عن هذه المجموعات الشمسية، والعوالم السماوية، فما ظنك بهذه اللانهائية التي يدعونها للمادة؟ أليس هذا هو الافتراء بعينه على هذا العلم المستغيث من ظلم المنتسبين إليه؟ بلى والله، واسمع القرآن كيف يقول {مَا أَشْهَدْتُهُمْ خَلْقَ السَّمَاوَاتِ وَالْأَرْضِ وَلَا خَلْقَ أَنْفُسِهِمْ} [الكهف: 51] أم هو العلم الذي استنبطته العقول من البراهين القاطعة؟ فليت شعرى أي عقول هذه وقد اتفقت كملة الأنظار الصحيحة منذ نشأتها إلى كهولتها على أن ما لا زمه العدم كاجتماع النقيضين فهو ممتنع الوجود لذاته، وأن ما لا يلزمه لذاته وجود ولا عدم، لا يرجح وجوده على عدمه إلا واجب الوجود لذاته، ولم يكن ينكر واجب الوجود تعالى فيما غير من الأزمنة البعيدة، إلا أراد معدودة من المندسين بين أهل العلم، كانوا سخرية أممهم، وضحكة من يسمع بهم من أهل الطبع السليم، والنظر المنطقي القويم، أما الآن فقد كثر هذا الصنف من أشباه الناس، وحازوا لقب الفلاسفة والباحثين والعلماء والدكاترة والأستاذين، فاغتربهم من انخدع بالألقاب فكفر تقليدا كما كفر أولئك جهالة وعنادا {وَمَنْ أَضَلُّ مِمَّنِ اتَّبَعَ هَوَاهُ بِغَيْرِ هُدًى مِنَ اللَّهِ} [القصص: 50] {وَمَنْ لَمْ يَجْعَلِ اللَّهُ لَهُ نُورًا فَمَا لَهُ مِنْ نُورٍ} [النور: 40]ــ وبعد ــ فالذي ينبغي أن يستقر عليه عقدك، ويحل المكان المكين من نفسك، هو أن المادة لا يلزمها لذاتها الا الإمكان لا وجود ولا عدم، ولا حركة ولا سكون، ولا بساطة ولا تركيب، وما يشاهد فيها من ذلك فليس هو لها من ذاتها؛ وإنما هو من فعل الذي أبدعها وأعطاها ما هي عليه من الصفات، جل وجوده وتعالى جوده، أعطا كل شيء خلقه ثم هدى، وليس عدم ومشاهد الشيء دليلا على عدمه، فضلا عن أن يجعل برهانا على امتناعه، وغاية ما يدعيه الباحث في المادة أنه لم يشاهد عدمها ولا سكون ما رآه منها بمنظاره، فليكن صادقا في هذه الدعوى، فأما أن يستدل بذلك على عدم جواز السكون أو العدم عليها فذلك ما لا يرضاه الانصاف، وما تلفظه الفلسفة الصحيحة، والبراهين القاطعة لفظ النواة، وما تكشف للباحثين من النواميس الكونية مما "], [29, "هدت إليه التجارب ودلت عليه الاختبارات، فلا نزاع فيه للمؤمنين المحققين، وهم يقولون به لا كما يقول أولئك العميان من أنها الفاعلة لهذا الوجود، بل على أنها من قبيل المعدات والشروط العادية، ومنها ما يكون من قبيل الشروط العقلية وللفاعل الحقيقي للوجود وتوابعه، إنما هو الله وحده لا شريك له، واجب الوجود وفياض الجود، سبحانه وتعالى عما يقول الجاهلون به علوا كبيرا، بل حقق بعض متأخريهم أن المادة تنعدم، وأنه ثبت ذلك لديه بتجارب له أجراها، ونحن في غني عن تصحيح هذا الرأي، فان قوة البرهان على إمكان ما سوى الخلاق العليم تغنى الحكيم عن تجربة هذا المجرب\rوربما تسامح بعض أهل العلم فسمى هذه النواميس أسبابا، ولا يعنى بها إلا ما بينا لك، وربما اغتر بعض المنسوبين إلى العلم بنسبة السببية إليها، فظن استحالة وجود الخوارق فأنكر كرامات الأولياء، وقد تجره العصبية لرأيه، أو الجهالة بمرتبة هذه النواميس، إلى محاولة إنكار كثير من معجزات الأنبياء عليهم جميعا وعلى آلهم الصلاة والسلام، ومن آثار هذه الغلطة ما اجترأ عليه بعض البارزين في أنظار العامة من أنه لا معجزة لرسول الله صلى الله عليه وعلى آله وسلم إلا القرآن، وقد يؤمنون ببعض تلك الآيات وينكرون انشقاق القمر ونحوه، ويتأولون كتاب الله بما يرده العلم الصحيح لدى أهل التحقيق، ويأبأه النقل المستفيض عن الثقات، بل المتواتر تواترا معنويا عند المتبحرين في العلم بطرق الأحاديث الشريفة، والسيرة النبوية المنيفة، على صاحبها وآله أزكى الصلاة والبركات: وقد أغنى سبحانه (وله الحمد كما هو أهله) عباده المستبصرين فخرق هذه النواميس المعروفة مرارا لا تحصى، فأيد الأنبياء بالآيات، وذكر كثيرا منها في كتابه المجيد، ولا سيما خاتم النبيين الذي لا نبي بعده صلى الله عليه وسلم، حتى قال الإمام أبو عبد الله الشافعي رضي الله عنه (ما أوتي نبي من الأنبياء آية إلا أوتي نبينا محمد صلى الله عليه وسلم مثلها أو أكبر منها) فقيل له فأين مثل إحياء الموتى لعيسى عليه "], [30, "الصلاة والسلام؟ فقال (حنين الجذع له صلى الله عليه وسلم، أكبر من ذلك فأن الميت كان له عهد بالحياة، فإذا أحيى فقد رجع إلى حاله الأولى أما الخشبة فهي جماد لا عهد لها بالحياة أصلا والحنين من فروع الحياة. روى هذا عنه أو ما في معناه الإمام الحافظ البيهقي رضي الله عنه. وأكرم سبحانه أولياءه بالكرامات التي نجل عن العد، وخلق عيسى من امرأة لم تخصب بيضتها بجرثومة ذكر، كما خلق آدم أبا البشر من غير ذكر وأنثى، بل من تراب خالطه ماء، أليس كل هذا يصيح بلسان فصبح في آذان أهل السمع الصحيح ألا إن ما عرفتم من النواميس وما لم تعرفوا إنما هو محكوم لبارئه لا حاكم عليه عز وجل وكيف يحكم الوضع على واضعه، وتقضى الصنعة على صانعها وهو الذي له القدرة التي لا تحد والإرادة النافذة التي لا يتعاصى عليها شيء في دائرة الإمكان التي لا يعلم مدى اتساعها إلا الفعال لما يريد.\rأيها الأخ المستبصر ليكن لك قلب أو ألق السمع وأنت شهيد إلى هذه المسألة كيف جلاها القرآن المجيد في أعذب لفظ وأروع أسلوب، وأوحز عبارة حيث يقول {إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ (82) فَسُبْحَانَ الَّذِي بِيَدِهِ مَلَكُوتُ كُلِّ شَيْءٍ} [يس: 82، 83] {إنَّمَا قَوْلُنَا لِشَيْءٍ إِذَا أَرَدْنَاهُ أَنْ نَقُولَ لَهُ كُنْ فَيَكُونُ} [النحل: 40] {سُبْحَانَهُ إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُ} [مريم: 35] {بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ وَإِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُ} [البقرة: 117] فانظر إلى لفظة إنما في هذه الآيات الأربع التي تلوناها وفي غيرها مما لم نذكره فإنها ترشدك إلى أن مدار الإيجاد للشيء على إرادته سبحانه له، وتكوينه تعالى إياه، فإذا الشيء كائن كما أراد وكون، لا على ما تعارف الباحثون من النواميس التي يحكمون باستحالة مخالفتها وأن يكون شيء بدونها.\r(فصل: في تحقيق معنى قوله تعالى: ولن تجد لسنة الله تبديلا)\r"]], "pg": [25, 30]}, "526.10": {"x": [[30, "ومن العجيب أن تسمع هذا الحكم في هذه الأزمان المظلمة من كثير من"], [31, "المنتسبين للعلم، فيلهجون بكلمة النواميس والسنن الكونية، وربما تلوا عليك قوله تعالى {وَلَنْ تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا} [الأحزاب: 62] ولو شاؤا لعلموا أن السنة الآلهية التي قضى سبحانه أنها لا تتبدل، إنما هي نصره لأنبيائه وأوليائه في الدنيا والآخرة على أعدائه المعاندين لهم، ولو قرأت ما قبل هذه الجملة الشريفة لصارحك بهذا المعنى وهي في عدة مواضع من كتاب الله، وكلها مسوقة لوعد رسول الله صلى الله عليه وسلم وأتباعه بالنصر المبين والعز المكين، ووعيد المعاندين بالخذلان المهين، والهزيمة المخزية على وفرة عددهم وكثرة عددهم، وصدق الله وعده ونصر عبده وأعز جنده وهزم الأحزاب وحده، فله الحمد كما ينبغي له. وأنت إذا أحكمت التدبر في هذا المقام أبصرت بوضوح أن السنة التي حكمت الآيات بأنها لا تبديل لها، إنما هي خرق النواميس المعتادة بين العامة، لأجل أولئك الخاصة، بالمعجزات الظاهرة والكرامات الباهرة. هذا النبي المصطفى عليه أفضل الصلاة والسلام أرسله مولاه وحيدا فريدا وأهل الأرض يومئذ العرب والعجم في المشارق والمغارب كلهم خصوم له، ولما جاء به، حريصون على إطفاء النور الذي جاء به بكل ما أوتوا من قوة، فهل من النواميس العادية والسنن المألوفة والقواعد المتعارفة بين العامة أن ينصر هذا الوحيد الفريد على ذوى الدول الكبرى والصغرى، هذا النصر الذي تحير فيه أساطين المتفلسفين، وجعلوا يختلقون في تعليله الأكاذيب، كلا ثم كلا، ما هي إلا السنة الألهية التي لن تجد لها تبديلا ــ اقرأ إن شئت أن تفهم {فَلَمَّا جَاءَهُمْ نَذِيرٌ مَا زَادَهُمْ إِلَّا نُفُورًا (42) اسْتِكْبَارًا فِي الْأَرْضِ وَمَكْرَ السَّيِّئِ وَلَا يَحِيقُ الْمَكْرُ السَّيِّئُ إِلَّا بِأَهْلِهِ فَهَلْ يَنْظُرُونَ إِلَّا سُنَّتَ الْأَوَّلِينَ فَلَنْ تَجِدَ لِسُنَّتِ اللَّهِ تَبْدِيلًا وَلَنْ تَجِدَ لِسُنَّتِ اللَّهِ تَحْوِيلًا} [فاطر: 42، 43] فهذه ونظائرها من الآيات الكريمة تنادي أساري النواميس العادية أن لله سنة غير ما ألفوا ممتازة بأنها لا ينالها التبديل كما ينال السنن التي عرفوا، وهي نصر المؤمنين الذين صدقوا وإن قلوا، وخذلان أعدائهم وإن كانوا أكثر من الرمل والحصى، ولقد كان أعداؤه "], [32, "عليه الصلاة والسلام يرمونه بالجنون حين يسمعونه يحدث أن الله ناصره على كسرى وقيصر، ومن دونهما، لأنهم لا يعقلون تلك السنة الآلهية التي لا تتبدل فالآيات دليل على خرق تلك النواميس المألوفة، فانظر كيف تجعل برهانا على عدمه والقلب إذا انتكس بزخرف هذه الحياة انعكس فيه المبنى فأخذ منه عكس المعنى {رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ} [آل عمران: 8]\rأراني قد أطلت عليك في هذا الفصل من هذا المختصر فمعذرة إليك أيها المستيقن، فإن الجهل بهذه المسألة شديد الخطر جدا، ها أنت ذا ترى ألوف الألوف تتلوها أمثالها من الأجيال المتعاقبة من أهل النصرانية المزيفة، والمسيحية المفتراة المصطنعة على المسيح على نبينا وعليه الصلاة والسلام، واليهود القائلين على مريم أمه بهتانا عظيما، ما أوقع هؤلاء وأولئك فيما وقعوا فيه إلا أنهم رأوه ولد من أم بلا أب، فقال اليهود ــ حماه الله مما قالوا: هو ابن زنية، وقال النصارى الجاهلون هو ابن الله. تعالى وتقدس عما يقول الجاهلون به علوا كبيرا، ولو وقر في صدورهم أن الله يخلق ما يشاء لا يقيده عز وجل ناموس عادي وقانون مادي، لما آمنوا بالباطل وكفروا بالحق، ولا وقعوا في هذه الفرى، وهل أنكر المنكرون ما جاء به النبيون من حشر الأجساد بأرواحها في النشأة الأخرى إلا لجهلهم أن هذه النواميس المعتادة طريق غير لازمة، وسنة غير ملتزمة يحرى الفعل الآلهي عليها وعلى ما شاء من سنن سواها، حسبما تقتضيه حكمته العليا وهو العلى الحكيم.\r(فصل: في أنه سبحانه هو فاعل للوجود)\r"]], "pg": [30, 32]}, "526.11": {"x": [[32, "ربما هجس بخاطرك هذا السؤال: إذا كان الخالق على كل شيء قديرا وكانت النواميس المتعارفة غير لازمة للتكوين. وأن تكوين أي كائن كان لا يتوقف في الحقيقة إلا على أن يريد ويفعل ما يريد، فإنه سبحانه هو وحده سبب الوجود والفاعل الحقيقي له، فما سر وضع هذه النواميس إذا؟ فاعلم أن جواب هذا السؤال يقذف "], [33, "بك في بحار أسرار القدر وهي عميقة مغرقة، والماهرون في الغوص والسباح إنما يفوزون منها بالدرر القريبة من السواحل، وهي وإن كانت كثيرة لا تفي بها العبارات، ولا تسعها الدفاتر، ولا تحويها إلا صدور الصدور من النبيين عليهم الصلاة والسلام، والفائزين بالقدح المعلى من أكابر العارفين رضي الله عنهم فهي قليلة بالإضافة إلى ما في علم الله تعالى ــ أخرج البخاري في صحيحه عنه عليه الصلاة والسلام في قصة موسى والخضر عليهما السلام أنه ((بينما هما على ظهر السفينة إذ بصرا بعصفور نزل إلى البحر فنقر بمنقاره نقرة أو نقرتين فقال الخضر لموسى هذا مثل ضربه الله لي ولك، ما أخذ علمي وعلمك من علم الله تعالى إلا كما أخذ هذا العصفور بمنقاره من البحر))\rوأين علمنا من علم أكابر العارفين رضي الله عنهم، بله النبيين عليهم السلام، ولكنا والفضل لله ولرسوله والعارفين من أتباعه عليه وعليهم الصلاة والسلام، نضع في يديك من مفاتيح هذه الكنوز والفتاح هو الله تعالى.\rفاعلم أن بعض ما يتوقف عليه الممكن قد يكون من الشروط العقلية، أو المعدات العقلية، ومثال الأول الموصوف مع الصفة، والثاني الخطوة الأولى مع الثانية، فاذا أريد إيجاد الألوان والحركات مثلا فلا بد من خلق المتلون والمتحرك قبلها، وكذا الكلام في الخطوة الثانية إذا أريد إيجادها فلا بد من إحداث الأولى قبلها، وليس ذلك لقصور في الفاعل جل وعلا بل لنقص في القابل، فإن وجود العرض بدون الجوهر مستحيل عقلا، فلا توجد حركة غير قائمة بمتحرك، ولا لون مستقلا عن متلون ولا علم غير قائم بعالم إلى سائر الصفات، فلا بد لها من الموصوفات، وتتنور كمال الفاعل مع نقص القابل بالعالم الكبير يلقى على صغار الطلبة من صغار العلوم لنقص في قابليتهم لا لقصور عالميته وتعليمه\rوكثيرا ما تكون الأمور المتوقف عليها من قبيل الشروط والمعدات العادية وهي جل ما يدرس في علم الطبيعة وعلم الكيمياء وأكثر ما يعتقد فيه العامة أنه "], [34, "أسباب للحادث، وأن الحادث يستحيل أن يوحد بدونه كالمشي على الماء والغوص فيه مدة طويلة، والطيران في الهواء بدون الآلة المعروفة وحدوث الأجنة بدون تلقيح، إلى غير ذلك، فكل ذلك في دائرة الممكن، غير أن العادة الإلهية جارية فيه على نواميس خاصة تعرف بالتجارب، وإنما كان ذلك كذلك في هذه النشأة الدنيوية ليكون مظهرا عظيما من مظاهر الجود الإلهي الذي لا حد له. وبيانه أنه إذا جعلت قوانين لاستخراج ما يحتاجه الإنسان من خزائن الغيب الإلهي، ومخازن القدرة الربانية وهداهم الفضل الصمداني بالتجارب إلى معرفتها، كان وضع تلك القوانين من العزيز الحكيم، وإجراء الأمر عليها في الأعم الأغلب من الجواد الكريم، بمنزلة وضع مفاتيح خزائن الكرم في يد المحتاجين فبربك عليك هل رأيت أكرم من غنى حميد يضع مفاتيح خزائن النفائس التي لا تحصى في أيدى الفقراء المحاويج؟ فما استفتحوا فتح لهم ومن لم يفعل فلا يلو من إلا نفسه، وليس ذلك إلا الرب الأكرم {يَاأَيُّهَا النَّاسُ أَنْتُمُ الْفُقَرَاءُ إِلَى اللَّهِ وَاللَّهُ هُوَ الْغَنِيُّ الْحَمِيدُ} [فاطر: 15] فما بينك وبين أن يخرج الله لك من خيرات أرضه إلا أن تتبع أصول فن الفلاحة الذي هدى الله إليه العباد بالتجارب، ثم كان بعد علما مدونا وما بينك وبين زوال ما نزل بك من الأمراض إلا أن تسلك ما وضع الحكيم العليم لأزالتها من الأدوية التي هدى العباد إليها بالتمرن، ثم كانت بعد ذلك علم الطب، وإذا شئت أن يهبك الله من الحيوانات التي عندك ما تحتاجه أو تتجمل باقتنائه سلكت الطريق التي وضعها الله لاستنتاج الحيوان، وكذلك إذا أردت الولد تزوجت وهلم في كل ما تريده وضعت لك الطرق إلى استفاضته من العزيز الوهاب، ولو أن الناس لم يجر الأمر معهم على ما وصفنا لما عرفوا كيف يستفتحون خزائن الجود، ويستمطرون سحائب الفضل، فالحمد لله الذي دل بإحسانه على إحسانه، فهذه واحدة أو مأنا إليها إيماء، وفي استقصائها عوض "], [35, "عريض لا يحتمله هذا الوجيز، وإليك أخرى وهو ربط هذه الكائنات بمضها ببعض من الكوكب الأعلى إلى المخلوقات الدنيا، ليكون من هذا الربط الدليل الأنور على وحدانية بارئها، وأنه أكبر من أن يكون له شريك. وشرح هذا على التفصيل يحوج إلى مجلد ضخم، ولا أكون مبالغا إذا قلت إلى مجلدات، والذي أستطيع أن أقوله لك هو أن هذا العالم من أفقه الأعلى إلى حضيضه الأدنى، على كثرة أنواعه، وخروج أفراد الأنواع عن عد العادين، قد وضع من الارتباط بحيث يكون كالجسم الواحد، لكل جزء من أجزائه وظيفة لها دخل في وظيفة المجموع كله، ولتقريب هذا عليك أقول: أنت ترى الأرض يخرج منها النبات وتختبئ في باطنها المعادن والمياه، ويعيش عليها الإنسان والحيوان، وتحمل البحار وتجري فيها الأنهار، فلو أن الشمس زالت من الوجود لذهب هذا الخير كله أوجله ولو أمعنت في التبصر لرأيت في مجموع هذه المخلوقات تعاونا عاما يناجيك بوحدة تنطق بأفصح لسان: ألا إني صنع لرب واحد، فتبحر في علم الكواكب وأوضاعها وفي علم أعضاء الإنسان ووظائفها وحاجتها إلى ما حولها، وفي علم الحيوان والنبات وعلم العناصر والكهرباء وانتفاع الكل بما في الكل ثم افتح صمع قلبك فستسمع هذا النداء بوحدانية خالق هذه الأشياء، وأنه لا يصلح للألوهية سواء ولا تليق هي إلا به جل علاه.\rودونك ثالثة وهي استشعار هذا النوع الإنساني المقصود من الخليقة كلها، وكيف لا وقد خلق له كل شيء {هُوَ الَّذِي خَلَقَ لَكُمْ مَا فِي الْأَرْضِ جَمِيعًا} [البقرة: 29] {وَسَخَّرَ لَكُمْ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ جَمِيعًا مِنْهُ} [الجاثية: 13] أي من إحسانه وجوده، استشعار هذا النوع بمزيد احتياجه إلى كل شيء مما حوله وما فوقه، وما تحته، وفاقة بعضه إلى بعض، فيرتقى من شعوره بحاجته إلى الكائنات إلى الإحساس بشدة فاقته إلى من أوجده وأوجدها، ومكنه فيها وله صخرها، فيتشرف بكمال التبتل إليه والانقياد لرسله، فيسمد بذلك سعادة الأبد، فإنه إذا لم يستشعر "], [36, "احتياجه كان كما قال جل قائلا {الْإِنْسَانَ لَيَطْغَى (6) أَنْ رَآهُ اسْتَغْنَى} [العلق: 6، 7] وما أروع ما قال القرآن الحكيم في هذا المعنى وما أبلغه وأثراه لمن أجال فيه فكره وأحسن تدبره، وذلك قوله تعالى {وَمِنْ كُلِّ شَيْءٍ خَلَقْنَا زَوْجَيْنِ لَعَلَّكُمْ تَذَكَّرُونَ} [الذاريات: 49] فانظر كيف حذف مفعول التذكر لأن المتذكرين مختلفون جد الاختلاف في استعداداتهم ومعارفهم ضيقا وسعة، وقلة وكثرة، فلا محالة يتفاوتون فيما يتذكرون فمن متذكر باحتياج كل من الزوجين إلى الآخر فاقة بعض الممكنات إلى بعض، فهي إلى الواجب الذي أوجدها أشد حاجة، وأعظم فقرا، ومن آخر يلمح النقص في كل شيء لحاجته إلى زوجه فيتذكر غنى الخالق المطلق وانفراده بالكمال الأتم فيبصر من خلال زوجية الأشياء جلال وحدانية رب الأرض والسماء، ومن ثالث ينظر إلى أن الشيء قد خلق له زوجه الذي يكمل به، فيتذكر كمال رحمة هذا المنعم، وإحسانه إلى كل شيء بكل شيء. إلى غير ذلك. وقد نبهناك بالقليل على الكثير، فاستزد بحثا يزدك الله علما، وليس ما كتب في تفسير الذكر الحكيم على كثرته بمستوف درر بحاره التي لا يعلم مداها إلا الذي أنزله، ولذلك روى عن أمير المؤمنين علي رضي الله عنه في وصف القرآن العظيم: هو الذي لا تنتهي عجائبه، ولا تشبع منه العلماء، ولا يخلق ــ أي لا يبلى ــ على كثرة الرد ــ أي التكرار له. والأثر أخرجه الترمذي وغيره، وقد روى مرفوعا وموقوفا والأصح وقفه ولما في ناموس التزاوج بين الأشياء من الأسرار والحكم التي عرفناك شيئا منها، مدح الله نفسه بخلق الأزواج كلها، مستهلا بالتسبيح حثا للعباد على استنباط ما أودع من كنوز الحكم في جميل صنعه، وأنيق ترتيبه، وبديع وضعه فقال تعالى: {سُبْحَانَ الَّذِي خَلَقَ الْأَزْوَاجَ كُلَّهَا مِمَّا تُنْبِتُ الْأَرْضُ وَمِنْ أَنْفُسِهِمْ وَمِمَّا لَا يَعْلَمُونَ} [يس: 36] وفي الآية الكريمة بدائع من آيات إعجاز القرآن فإن الناس ما كانا يعرفون التزاوج إلا في أنفسهم وفي الحيوان، وقليل من الأشجار، والآية الشريفة تبدأ بأن الأزواج قد خلقت في النبات "], [37, "كله كما خلقت الأزواج من أنفس الإنسان، ولم يعرف ذلك للباحثين إلا بعد تزول القرآن بقرون، فأصبح من المعروف الجلي أن في النبات كله الأناث والذكران، ولله ألطاف عجيبة في تلقيح بعضها ببعض بالرياح والحشرات وغيرها، تبارك من لا يحصى ثناؤه. ودلت الآية على أن الله قد جعل أزواجا مما لا يعلمه الناس حين ينزل القرآن، وقد علم الباحثون من أهل هذا العصر في علم الكهرباء أن فيها موجبا وسالبا بينهما ما بين النبات والحيوان من التزاوج والتجاذب، وعليه يتم استنتاج منافع هذه الكهرباء التي ملأ الله بها هذا العالم من الخير بما لا يحصى. ولهذا الكتاب في كل زمان آيات تتكشف على أهله، وكلما تقدم الإنسان في بحث الكائنات واستبطن خفاياها، قدم لهم القرآن عجائب آيات تلو آيات، تشرح قوله تعالى {أَنْزَلَهُ الَّذِي يَعْلَمُ السِّرَّ فِي السَّمَاوَاتِ وَالْأَرْضِ إِنَّهُ كَانَ غَفُورًا رَحِيمًا} [الفرقان: 6] وفي السفر الجليل الذي ألفه صاحب السعادة النطاسي البارع عبد العزيز باشا إسماعيل في معجزات القرآن الطبية أصدق شاهد على ما نقول، وكذلك ما كتبه سواء من إخوانه ويكتبونه في الصحائف اليومية والمجلات الأسبوعية، وغيرهم من المهرة في فنون أخرى وما يكون بعد ذلك مما لا يعلمه إلا الله هو من تحقيق قوله تعالى {سَنُرِيهِمْ آيَاتِنَا فِي الْآفَاقِ وَفِي أَنْفُسِهِمْ حَتَّى يَتَبَيَّنَ لَهُمْ أَنَّهُ الْحَقُّ} [فصلت: 53] فلله الحجة البالغة بهذا الكتاب العزيز الذي أنزله معجزة كبرى لنبيه المصطفى صلى الله عليه وسلم باقية ما بقيت الدنيا، تمضى الأعصر بعد الأعصر وهذه المعجزة باقية على جدتها، وفي الصحيح عنه عليه الصلاة والسلام ((ما من نبي إلا أوتى ما مثله آمن عليه البشر، وإنما كان الذي أوتيته وحيا أوحاه الله إلى فأرجو أن أكون أكثرهم تابعا يوم القيامة)) يعني عليه الصلاة والسلام ما من نبي إلا أعطاء الله من الآيات ما به تقوم الحجة على أمته، ويهدى الله به منهم من يشاء، كقلب العصاحية. وغيره لموسى، وكأبراء الأكمه، وإحياء الموتى لعيسى، وإنما كانت الآية التي خصصت بها من بينهم، هذا الكتاب المعجز بأسلوبه ونظمه وجمعه لعلوم الأولين "], [38, "والآخرين، وقصه من أنباء ما قد سبق، وإنبائه بأخبار ما بعده، إلى غير ذلك من وجوه إعجازه، فقد تكفل الله بحفظه، فهو باق على الدهر، يحاج كل جيل ويقارع كل قبيل، وليس حادثة ينقضي شخصها ويبقى ذكرها، فلهذا رجا عليه الصلاة والسلام أن يكون أكثر النبيين تابعا يوم القيامة لبقاء حجته الكبرى ماثلة في كل زمان يأتي بعده بعينها وشخصها، لا بذكرها وخبرها، فلا يزال في كل زمان يظهر لهذا القرآن آيات لم يشرق نورها إلا على أهله، وقد صنفت كتب كثيرة في بيان وجوه إعجاز القرآن، ومن أحدثها عهدا وأجمعها فائدة، وأجلها بيانا، وأوضحها برهانا كتاب إعجاز القرآن لدرة تاج الأدب، مصطفى صادق الرافعي، تغمده الله برحمته وأفاض عليه وابل إحسانه، وجزاه على ما قام به من هذه الخدمة الكبرى خير جزاء، وتالله ما بالغ سعد باشا زغلول رحمه الله تعالى إذ قال في تقريظ هذا الكتاب ((كأنه تنزيل من التنزيل، أو قبس من نور الذكر الحكيم)) فنصيحتي لكل مسلم أن يقرأ هذا الكتاب ويكرر القراءة، ويطيل فيه الأمعان والتأمل، وقد تفضل بطبعه ملك مصر الراحل فؤاد الأول أسبغ الله عليه رحمته، وقد أو شكت نسخ الطبعة الثالثة أن تنفد فنرجو أن يوفق الله لا عادة طبعه الملك المعظم قاروة الأول، أطال الله بقاءه في عافية، أسوة بوالده الماجد، وهو بحمد الله محب للخير مسارع إلى بذله، أدام الله توفيقه.\r(فصل: قد بأن أن البرهان القاطع ناطق بأن ما وجد ويوجد من الذوات والصفات لا يهبه الوجود وتوابعه إلا واجب الوجود)\r"]], "pg": [32, 38]}, "526.12": {"x": [[38, "قد بأن لك إن شاء الله مما مر بك في الفصول السابقة، أن البرهان القاطع ناطق بأن ما وجد ويوجد من الذوات والصفات لا يهبه الوجود وتوابعه إلا واجب الوجود لذاته، العلى بسلطانه على كل موجود، فجوده سبحانه هو السبب الحقيقي وهو جل وعلا الفاعل المتصرف والموجد، فكل شيء سواه أطلق عليه العلماء اسم السبب أو العلة فلا يريدون به إلا السنن التي جرت العادة الإلهية أن يخلق "], [39, "الفعل عقب حصولها، ولذلك تسمعهم يقولون إنها أسباب عادية. قال المولى سعد الدين التفتازاني في مباحث العلة آخر المقصد الثاني من المقاصد له رضي الله عنه ما نصه (تنبيه) لما كان الموجد عندنا هو الله تعالى وحده كان معنى العلة من الممكنات ما جرت العادة بخلق الشيء عقيبه. وقد ظهر لك أيضا أن لله تعالى أن يخرق هذه العوائد متى شاء فلا يأتي بالمسببات عقب تلك الأسباب كتخلف الأحراق عن النار كما فعله مع خليله إبراهيم على نبينا وعليه الصلاة والسلام {قُلْنَا يَانَارُ كُونِي بَرْدًا وَسَلَامًا عَلَى إِبْرَاهِيمَ (69) وَأَرَادُوا بِهِ كَيْدًا فَجَعَلْنَاهُمُ الْأَخْسَرِينَ} [الأنبياء: 69، 70] أو يأتي بالمسببات بدون هذه الأسباب المعتادة، كما خلق عيسى من مريم من غير أن يمسها بشر، فإنه الفعال لما يريد، يخلق ما يشاء سبحانه، وقد سلف لك أيضا أن جريان العادة الإلهية على هذا النحو المتعارف إنما هو لحكم بالغة اقتضاها جوده جل شأنه، وقد سبقت الإشارة إلى بعضها، فينبغي أن تستفيد من كل هذا أمورا ــ الأول ــ دوام استفتاحك لجوده بالأخذ في الأسباب التي جرت عادته أن يعطيك بعدها مسبباتها مع اعتماد قلبك عليه لا عليها فإن ترك تلك الأسباب حماقة منك، والاعتماد عليها جهالة منك بالمعطى الحقيقي، ولهذا تسمعهم يقولون: الأخذ بالأسباب لا ينافى التوكل، قال صلى الله عليه وسلم لمن سأله: أأعقل ناقتي أم أتوكل على الله؟ ((اعقلها وتوكل)) وظاهر عليه الصلاة والسلام في أحد بين درعين، واعتقل الرمح، وتقلد السيف، وأخذ الزاد وأمر بأخذه في الأسفار صلى الله عليه وسلم، وبذلك جاء كتاب الله وشرعت صلاة الخوف ــ الثاني ــ أن لا تيأس من فضله إذا تعسرت عليك هذه الأسباب، وأن تقبل عليه بكل قلبك فله تعالى بالمتوكلين عليه العاكفين ببابه من الالطاف ما لا يحصيه كتاب، ولا يحصره حساب ــ الثالث ــ أن لا تندم إذا أخذت في الأسباب ولم يحصل ما أردت بل املأ قلبك بأن اختياره لك في المنع خير لك من اختيارك في العطاء. وكل أمر من هذه الأمور الثلاثة يحتاج تمام بيانه إلى مؤلف مستقل، لكنا في هذه "], [40, "الرسالة إنما نشير إشارة ونلمع إلماعا، فعليك بكتب القوم.\rمطلب في إبطال الاعتذار بالقدر ــ وقد أوجز وأعجز رسول الله صلى الله عليه وسلم في بيان هذه المسألة حيث قال: ((المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف، وفي كل خير، احرص على ما ينفعك واستعن بالله ولا تعجز وإذا فاتك شيء فقل قدر الله وما شاء فعل، ولا تقل لو فإن لو تفتح عمل الشيطان)) أخرجه مسلم وغيره، وأخرجه البخاري في صحيحه مرفوعا: ((سددوا وقاربوا وأبشروا واعلموا أنه لن يدخل أحدا الجنة عمله قالوا ولا أنت يا رسول الله؟ قال: ولا أنا إلا أن يتغمدنى الله بفضل منه ورحمة)) ولما قيل له عليه الصلاة والسلام: أفلا نتكل على كتابنا وندع العمل؟ قال: ((لا، اعملوا فكل ميسر لما خلق له)) ورضي الله عن هؤلاء الأصحاب الكرام ما أغزرهم فقها وأعمقهم علما!! فقد قال قائلهم حين سمعوا هذا: ما كنا إذ سمعنا هذا الحديث بأشد اجتهادا منا قبل أن نسمعه. فهكذا يكون الفقه في الدين، فإن من علم أن أخذه في الطاعة ومواظبته عليها علامة أنه سبقت له من الله الحسنى لم يدخر وسعا في التمسك بها ولم يأل جهدا في البعد عما ينافيها، ومن تيقن أن أسباب الخيرات هي من القدر سارع إليها. وقد ثبت أن قائلا قال يا رسول الله أليس المرض من قدر الله؟ قال ((بلى)) قال ففيم الدواء؟ فقال عليه الصلاة والسلام ((الدواء من قدر الله)) فالكسل عما وضع الله من السنن احتجاجا بالقدر جهل بما يقتضيه اعتقاد القدر وفهمه كما ينبغي، والتهالك على الأسباب بدون اعتماد على خالقها وخالق مسبباتها مالك الأمر كله ضعف في اليقين، وتباعد عما يقتضيه العلم بجلال العزيز الحكيم ــ وبعد ــ فالمسألة طويلة الذيل بعيدة الغور، والذي أنصح به لكل مؤمن أن يعلم أن القدر سابق وأن ما كتب له أو عليه غير معلوم له، وأن أسباب الخير والشر في الدنيا والآخرة قد أرشده الله إليها وأعلمه بها على لسان الرسول الصادق المصدوق عليه الصلاة والسلام، وما وضعه في العقول، وأن الخير قضى بسببه والشر يجيء بطريقه، فليشمر في السعي في طرق الخير التي أمر بها، وليتباعد عن سبل "], [41, "الشر التي نهى عنها، معتمدا في إنجاح مساعيه كلها على فضل الله وجوده، وهو سبحانه لا يخيب أمل آمل، ولا يرد دعاء سائل، وإذا وفق لطاعة فليذكر نفسه بأن الفضل كله لله حتى يزيل نور هذا الإيمان ظلمات ما عسى أن تتدلس به النفس من مجب بعمل أو من به، وليكرر هذه الذكرى حتى يطفئ ماؤها العذب نيران هذه الرعونات النفسانية، وإذا وقعت منه معصية فليذكر قصوره وتقصيره، وليعترف لربه من صميم قلبه بأنه مسيء غالط، وليسارع إلى المتاب ولا يحتج لنفسه بما سبق من قدر ربه، فإن حسن الاعتذار للواحد الغفار، وسرعة المتاب من الاوزار هو سبيل المصطين الأخيار من النبيين والصديقين وأهل البصائر أجمعين. انظر إلى نبي الله أبي البشر آدم عليه الصلاة والسلام حين قال الله له ولزوجه (ألم أنهكما) هل احتجا لأنفسهما؟ حاشاهما بل قالا {رَبَّنَا ظَلَمْنَا أَنْفُسَنَا} [الأعراف: 23] الآية. وقال رسول الله نوح عليه الصلاة والسلام (رب اغفر لي ولوادي) وقال الخليل صلى الله عليه وسلم {وَالَّذِي أَطْمَعُ أَنْ يَغْفِرَ لِي خَطِيئَتِي يَوْمَ الدِّينِ} [الشعراء: 82] وقال الكليم {رَبِّ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي} [القصص: 16] وصح عن سيد المرسلين عليه وعلى آله الصلاة والسلام ((يا أيها الناس استغفروا لله وتوبوا إليه فو الله إني لأستغفر الله وأتوب إليه في اليوم سبعين ــ وفي رواية ــ أكثر من سبعين مرة)) وقال الصديق الأكبر أبو بكر رضي الله عنه يا رسول الله علمني دعاء أدعو به في صلاتي، فقال عليه الصلاة والسلام ((قل اللهم إني ظلمت نفسي ظلما كثيرا ولا يغفر الذنوب إلا أنت فاغفر لي مغفرة من عندك وارحمني إنك أنت الغفور الرحيم)) أخرجه البخاري. ومن الناس إلا هؤلاء السادة؟ ففهم للمؤمن خير أسوة. أما التمسح بالقدر عند المعصية فهو طريق إبليس اللعين ألا تراه قال {رَبِّ بِمَا أَغْوَيْتَنِي} [الحجر: 39] الآية.\rفان قلت: أليس قد احتج أبونا آدم بالقدر حين لامه الكليم كما أخرجه البخاري؟ قلنا: بلى ولكن كان ذلك منه عليه الصلاة والسلام في دار التشريف لا في دار التكليف وبعد صدق المتاب والاعتراف للملك الوهاب لامع الإصرار "], [42, "على مخالفة الواحد القهار، والأديب اللبيب يعطى كل مقام حقه. وللكلام بسط ليس هذا موضعه. ولا يظن ظان أن اعترافه بذنبه لمولاه وتوبته إليه مع سبق قدره سبحانه هو محض مجاملة منه لربه، وإنما هو الحق الذي يجب أن يعترف به لمولاه من صميم فؤاده، فإنه رفع المؤاخذة عن عبده حين يكون العبد لا دخل له في الذنب. كأن كان مجنونا أو مكرها، أو لا يزال في ضعف الصبا لم يبلغ الحنث ألا تراهم أجمعوا على أن شروط التكليف: البلوغ والعقل. وأن شرط المؤاخذة الاختيار، أما وقد أعطاه الشعور وخلق فيه الأرادة والقدرة، وأعطاه المكنة والاستطاعة، وعرفه كيف الاحتيال لدفع الشر والامتناع من الشيطان، فقصر فيما أمر فقد توجهت عليه المسئولية، وقد فتح له باب المتاب ووعده بالمغفرة عند الاستغفار، فإذا أطاع هواه ولم يفعل فلا يلو من إلا نفسه.\rــ فإن قلت ــ ألا جعل الكل موفقين؟ قلنا: ذلك فضل الله يؤتيه من يشاء، وإذا قلت في المخلوقين: ما على المحسنين من سبيل، أفلا يكون ذلك منك في خالقك أولى؟ وبك أحرى؟ ولله أسرار في تقسيم الخلق إلى ما انقسموا إليه من طائع وعاص، ومؤمن وكافر، وغنى وفقير، وصحيح ومريض، وعزيز وذليل، ورعاة ورعايا، إلى غير ذلك، لا يحيط بها إلا هو جل جلاله، ولو انكشف بعضها فضلا عن جميعها لعلم من كوشف أن الحق كله لله، وضل عنه كل ما يحتج به لنفسه، ولكن دون أسرار القدر حجب، فتب مستبصرا، وسلم لربك مخلصا، وخذ حذرك مما يغضبه، واتهم عقلك فيما يحاوله، فمقام الألوهية في اتساع العلم وعلو الحكمة، وكمال القدس، وإحاطة الرحمة، أجل من أن تحيط بمبادئ كماله العقول الكبرى وإن اتسعت، ولهذا اختصر لنا الطريق وقيل لنا (لا يسئل عما يفعل وهم يسئلون) ولا تسمح هذه العجالة بأكثر من ذلك،\r"], [43, "(فصل: في فضل الإيمان بالغيب وحكته، وعظم نقص من لم يتصف به)\r"]], "pg": [38, 43]}, "526.13": {"x": [[43, "اعلم أن السير وراء الوهم واتباع الوساوس مضلة عظيمة لهذا النوع البشرى وإنما سبيل النجاة من النقائص، والفوز بالكمالات في العلم والعمل هو إتيان البيوت من أبوابها واستفتاح الخرائن بالمفاتيح التي وضع الله لها. فعلم المادة والماديات يستفاد من الحواس والتجارب، وعلم ما وراء المادة وما علا عن خصائصها يستفاد بالبراهين العقلية الصحيحة المنطقية، والأدلة النقلية الثابتة عن المعصوم، ولكل حاسة من الحواس وظيفة في الأفادة لا تتعداها، فالألوان والأضواء والأشكال تعرف بحاسة البصر. والأصوات وصفاتها تدرك بحاسة السمع، وهكذا في سائر الحواس. فمن حاول أن يعرف اللون بالسمع أو الصوت بالبصر انقضى عمره ولم يعرف من ذلك شيئا. ومن طلب معرفة من تعالى عن أن يدرك بألطف الحواس فضلا عن كشيفها من طريق هذه الاحساسات، ولم يسلك طريق البرهان، ورفض الإيمان إلا بما يرى أو يلمس، فقد انحط عن درجة الإنسانية العليا، إلى دركة البهيمية السفلى، وفي هؤلاء يقول القرآن الحكيم {لَقَدْ خَلَقْنَا الْإِنْسَانَ فِي أَحْسَنِ تَقْوِيمٍ (4) ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ} [التين: 4، 5] فقول من يدعى الثقافة: أنا لا أصدق بالله وملائكته لأن هذا شيء ما رأيته، ولا يدخل تحت التجارب في المعامل، هو قول {كَسَرَابٍ بِقِيعَةٍ يَحْسَبُهُ الظَّمْآنُ مَاءً حَتَّى إِذَا جَاءَهُ لَمْ يَجِدْهُ شَيْئًا} [النور: 39] وليس يبتنى على حكمة، ولا يمت إلى فلسفة صحيحة، وإنما هو محض العناد للحقائق وصرف الجحود للحق تعمدا، وهو كقول من يقول: أنا لا أصدق بوجود الأصوات لأن عيسى لا تراها، ولا أو من بالألوان والاشكال لأن سمعي لا يحس بها، فمثل هذا القائل يعتبر في نظر العقلاء معتلا مختلا، والحكيم معه على إحدى سبيلين. إما أن يهمله إهمال العالم إلقاء الدرس على البهائم لأنها ليست بأهل أن تفهمه، أو يتنزل إلى محادثته لئلا يغتر به غيره من الذين لم يتلوثوا بجراثيم مرضه، فيقول له: ليس بالسمع تدرك الألوان ولا بالبصر تدرك الأصوات، حتى يكون ذلك دليلا على إنكارها، وكذلك "], [44, "الأمر تماما فيمن قال: لا أو من بالله لأنه لا تدركه حاسة من حواسنا، فيقال له إن ربك فوق محيط هذه المحسات كلها، وقد وهبك قوة أخرى هي الحاكمة على تلك المدركات، وهي العقل، وبها تعرف ما علا عن الحواس. وأنت لا تشك في أنك عاقل، فهل تدرك عقلك بأحدى هذه الحواس؟ كلا، وأنت تفرح وتحزن وتلتذ وتتألم، وتجوع وتعطش، أفتدرك هذه الصفات أو واحدة منها بهذه الحواس التي تأتى أن تؤمن بما لم تدركه بها؟ كلا ثم كلا، وكما أن قوة البصر عند الظلمة لا تدرك شيئا مما تقع عليه فإذا جاء الضياء أدركت، كذلك قوة العقل إذا تكاثرت عليها الشهوات والأوهام تعطلت عن أداء وظيفتها، فإذا استعملت مصباح البرهان واستضأت بضياء القرآن تكشف لك الحق جليا، وقام لك البرهان على الرحمن مقام العيان للأكوان، فآمنت بالغيب مستبصرا وانبثقت عن هذا الإيمان الأعمال الصالحة تترا، وكنت حينئذ قد جانبت الاعتساف، وحييت بروح الأنصاف، وتحليت بفصائل أفاضل نوعك، وصح لك أن تدخل في الذين استثناهم الله تعالى من الرد إلى أسفل سافلين حيث قال {إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ} [التين: 6] فالإيمان بالحق المقدس عن المادة وصفاتها انصياعا لما سطع من البرهان وإن كان تصديقا بما لم تره عين أو تلمسه يد ليس جريا وراء الأوهام ولا دخولا في عداد العوام بل هو فضيلة الحكيم المنصف وميزة الإنسان الذي تسنم ذروة الشرف، وخصيصة أهل الثقافة الحقة غير المزيفة، والخلو من هذا الإيمان عياذا بالله تعالى مراغمة للأدلة وانحرافا عن الحجج الحقة، ليس إلا انحدارا إلى منزلة الأنعام، وإطفاء لنور وظيفة القوة العاقلة، التي هي أكبر مميزات الإنسان، وانغماسا في حمأة الأوهام وخروجا عن حدود العلم الصحيح، وغرقا في الجهل الذي هو أقبح قبيح. ولقطع أعذار المتعللين ترى القرآن العظيم مملوءا بأسطع البراهين على ما يدعو إليه الخلق أجمعين فكان للعقول الكاملة بمنزلة النور للباصرة، وللمجموعة "], [45, "البشرية بمنزلة الأرواح للأجسام، ولهذا سماه الله نورا في قوله {فَآمِنُوا بِاللَّهِ وَرَسُولِهِ وَالنُّورِ الَّذِي أَنْزَلْنَا} [التغابن: 8] وصدق الله، فان هذا القرآن يخاطب منك عقلك ويستنهض فكرك، ولا يذكر الدعوى حتى يردفها بالبرهان الأعلى، وينوع الأدلة ويورد الحجج بالأساليب الرائعة، التي يخر المنطق الصحيح أمامها ساجدا إعظاما لشأنها، وإكبارا لأمرها، وسماه روحا في قوله سبحانه {وَكَذَلِكَ أَوْحَيْنَا إِلَيْكَ رُوحًا مِنْ أَمْرِنَا} [الشورى: 52] فان به الحياة السعيدة لهذا المجمع البشرى كله ما أخذوا بآدابه وتمسكوا بأهدابه. وللخبير المنصف على ذلك أصدق الشواهد إذا كان مطلعا على حال الأمة الإسلامية أيام اقتدائها بكتابها وتمسكها بدينها، ومن عجيب عناية هذا الكتاب العزيز بتثقيف العقول بالبرهان عقب البرهان، وإخراج الناس من حيز العامة إلى مقام الخاصة بالأتيان بالدليل بعد الدليل، والسير في طريق البرهنة، من عجيب عنايته بذلك أنه لم يكتف بسوق البراهين فيما هو من باب الإلهيات والنبوات، والبعث بعد الموت، بل ساق الدليل فيما هو من باب الآداب. انظر إلى قوله {وَلَا تَسْتَوِي الْحَسَنَةُ وَلَا السَّيِّئَةُ} [فصلت: 34] إلى قوله {فَإِذَا الَّذِي بَيْنَكَ وَبَيْنَهُ عَدَاوَةٌ كَأَنَّهُ وَلِيٌّ حَمِيمٌ} [فصلت: 34] وانظر إلى تعقيب ذلك بذكر دواء داء الغضب، وتحلية مر هذا الدواء بحلو وعده الصادق الجميل، حيث يقول {وَمَا يُلَقَّاهَا إِلَّا الَّذِينَ صَبَرُوا وَمَا يُلَقَّاهَا إِلَّا ذُو حَظٍّ عَظِيمٍ} [فصلت: 35] بل سلك طريق الاستدلال فيما أخبرهم به من كذب خلطائهم من أهل النفاق في الاعتذار حيث قال {وَلَوْ أَرَادُوا الْخُرُوجَ لَأَعَدُّوا لَهُ عُدَّةً} [التوبة: 46] ومن المعجز المدهش في أسلوب هذا الكتاب لمن أنعم فيه مستبصرا أنه يسوق غوامض المعاني الإلهية وعوالي الصفات الربانية وسواطع الأدلة الحكمية على طريق لا يمكن للبليغ مهما علا في البلاغة كعبه أن يسلكها فانها أسلوب ينتفع به العامة والخاصة، يأخذ منه العامة قسطا من العلم لا بأس به، ولا يشوش عليهم مداركهم. وينال منه الخاصة لب الحكمة، وخالص المعن العلى، وكذلك دأبه في علوم الكائنات التي مست "], [46, "حاجة البشر إلى بثها. وليس هذا المختصر بموضع تفصيل ذلك، وينير لك شيئا من ذلك ما كتبه الطبيب الشهير عبد العزيز باشا إسماعيل في مجلة الأزهر تحت عنوان (الإسلام والطب الحديث) وما كتبه الطبيب المعروف الحاج محمد وصفى في مجلة هدى الإسلام وغيرهما من الأفاضل الباحثين عن أسرار هذا الكتاب العزيز قديما وحديثا، ولهذا افتتح الله مدائح المتقين بوصفهم بالإيمان بالغيب، ولم يقبل الإيمان حين المكاشفة إذا بلغت الروح الحلقوم، وهجم العيان عليها، وحين تزول البأس بالمكذبين من المنذرين {ظَلَمَهُمُ اللَّهُ وَلَكِنْ كَانُوا أَنْفُسَهُمْ يَظْلِمُونَ} [النحل: 33] بل اتسعت العناية الألهية في هذا القرآن المجيد فجعل في براهينه لمن يريد أن يستبصر براهين تشبه براهين العلوم التجربية كعلم الطبيعة والكيمياء والكهرباء، تمام المشابهة. ومن درس تلك الكتب فهم ما أقول. ومن لم يقرأ فيها فإني أحدثه عنها.\rتجد الكتاب قبل أن يسوق لك النظرية الكلية يذكر لك الجزئيات التجربية لأول من تكشفت عليه مساتير هذا العلم فمن بعدهم، فيقول وضع العالم فلان السائل الفل\rإني في جهاز شكله كذا، وصب عليه من الحمض الفلاني فصار كذا، فينتج من ذلك نظرية كذا ثم جاء بعده فلان ففعل كذا وهلم. وحاصل ذلك الرجوع بطالب العلم إلى التجارب المشاهدة، واستخلاص النتائج منها قواعد كلية، وربما أتى صاحب الكتاب بالنظرية فأتبعها بالتمرينات الجزئية، وعزاها إلى مجربها. وكذلك أنزل هذا القرآن على خاتم النبيين عليه وعلى آله أفضل الصلاة والسلام إلى هذه الأمة الأخيرة، وق خلت من قلبها أمم، وأرسلت إليهم أنبياء، وقد خلت لله فيهم سنن؛ فإذا أنت ألقيت السمع وأنت شهيد إلى هذا الكتاب المجيد، وجدته يأتيك بالعلوم العليا ويدعمها بالبراهين الآخذة بلب كل حكيم، ويردف ذلك بقصص الأمم الماضية، وشرح السنن الخالية التي كانت منه مع المكذبين والمصدقين، التي شوهدت ثم حفظها التاريخ وشاع خبرها "], [47, "عند المخاطبين أو أهل العلم من جيرانهم، ويعد أو يوعد، ويبشر أو ينذر، ثم يتبع ذلك بالجزئية التي شاهدتها الأمة أيام التنزيل، أليس هذا هو الذي يسمونه اليوم بالطرق الحديثة، والبراهين العلمية، سلكه القرآن قبل أن توجد هذه الأسماء وواضعوها؟ اقرأ إن شئت {قُلْ لِلَّذِينَ كَفَرُوا سَتُغْلَبُونَ} [آل عمران: 12] الآية، ثم اتل تاليتها فإذا هي تقول {قَدْ كَانَ لَكُمْ آيَةٌ فِي فِئَتَيْنِ الْتَقَتَا} [آل عمران: 13] يعني المسلمين الكافرين في غزاة بدر وقد شاهدها المخاطبون، نصر المؤمنون غير ذوى عدد ولا عدد على الكثرة ذات العدد والعدد الكثيرة وهم لا يعرفون لذلك سببا إلا نصر الله وتأييده، ولذلك واجههم بقوله {وَاللَّهُ يُؤَيِّدُ بِنَصْرِهِ مَنْ يَشَاءُ إِنَّ فِي ذَلِكَ لَعِبْرَةً لِأُولِي الْأَبْصَارِ} [آل عمران: 13] واقرأ قوله تعالى {وَعَدَكُمُ اللَّهُ مَغَانِمَ كَثِيرَةً تَأْخُذُونَهَا فَعَجَّلَ لَكُمْ هَذِهِ} [الفتح: 20] أي مصالحة الحديبية {كَفَّ أَيْدِيَ النَّاسِ عَنْكُمْ وَلِتَكُونَ آيَةً لِلْمُؤْمِنِينَ} [الفتح: 20] ومن هذا القبيل قوله تعالى {وَلَقَدْ نَصَرَكُمُ اللَّهُ بِبَدْرٍ وَأَنْتُمْ أَذِلَّةٌ} [آل عمران: 123] (ولقد نصركم الله في مواطن كثيرة ويوم حنين) {هُوَ الَّذِي أَخْرَجَ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ مِنْ دِيَارِهِمْ} [الحشر: 2] إلى قوله {فَاعْتَبِرُوا يَاأُولِي الْأَبْصَارِ} [الحشر: 2] وأما قص أخبار الأولين بعد ذكر البراهين المنطقية أو قبلها أو أثناءها فهو في القرآن كثير جدا مجملا تارة ومفصلا أخرى، على حسب ما تقتضيه مقامات الخطاب، فانظر في سورة الأعراف كيف أقام البرهان على وحدانيته وكمال قدرته في قوله: {اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ} [الأعراف: 54] الآيات إلى قوله: {كَذَلِكَ نُصَرِّفُ الْآيَاتِ لِقَوْمٍ يَشْكُرُونَ} [الأعراف: 58] ثم أتبع ذلك بسننه الجزئية التي شوهدت وشاع خبرها عند أهل العلم من أهل الكتاب وكثير من العرب فقال تعالى: {لَقَدْ أَرْسَلْنَا نُوحًا إِلَى قَوْمِهِ} [الأعراف: 59] القصة إلى آخرها {وَإِلَى عَادٍ أَخَاهُمْ هُودًا} [هود: 50] {وَإِلَى ثَمُودَ أَخَاهُمْ صَالِحًا} [هود: 61] إلى آخره {وَلُوطًا إِذْ قَالَ لِقَوْمِهِ} [الأعراف: 80] الآيات {وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا} [الأعراف: 85] إلى أن قال {تِلْكَ الْقُرَى نَقُصُّ عَلَيْكَ مِنْ أَنْبَائِهَا} [الأعراف: 101] مشيرا إلى أن القرى معروفة لهم، ثم ساق قصة موسى وفرعون وبني إسرائيل وما فيها من العبر. وقال في "], [48, "سورة الحجر بعد ما ساق الأدلة الكونية {وَنَبِّئْهُمْ عَنْ ضَيْفِ إِبْرَاهِيمَ} [الحجر: 51] إلى أن ذكر ما أجراه من النقم على المكذبين من قوم لوط وأصحاب الأيكة، حتى قال {وَإِنَّهُمَا لَبِإِمَامٍ مُبِينٍ} [الحجر: 79] أي طريق مقصود مسلوك بين عند المخاطبين. وقال في سورة أخرى في آخر ذكر قوم لوط {وَإِنَّكُمْ لَتَمُرُّونَ عَلَيْهِمْ مُصْبِحِينَ (137) وَبِاللَّيْلِ أَفَلَا تَعْقِلُونَ} [الصافات: 137، 138] وقال في سورة العنكبوت في تلك القرى التي أخر بها الله بذنوب أهلها وعنادهم للحق الذي جاءت به رسله {وَلَقَدْ تَرَكْنَا مِنْهَا آيَةً بَيِّنَةً لِقَوْمٍ يَعْقِلُونَ} [العنكبوت: 35] وكذلك الأمر في سورة يونس وسورة هود عليهما السلام بدأ الأولى بسواطع البراهين على وحدانيته في الألوهية ورسالة رسوله وما اتصل بذلك وبشر وأنذر، ثم أردف هذا كله بقوله {وَاتْلُ عَلَيْهِمْ نَبَأَ نُوحٍ} [يونس: 71] ومضى في قصص القصص، وكذلك في السورة الثانية سرد الأدلة الكلية ثم أتبعها بالحوادث الجزئية.\rومن هداية القرآن البديعة أنه لم يذكر قصص الأمم النائية الواقعة في المجاهيل ورسلهم حتى لا يكون حوالة على مجهول مطلق للمخاطبين، بل ذكر خبر آباء البشر آدم وإدريس ونوح، وخبر أبي من بعده من النبيين إبراهيم وقريبه لوط والمرسلين إلى العرب. وبني عمهم من بني إسرائيل، ليكون العلم المتوارث بهم ولو إجمالا قائما مقام المشاهدة، ولم يهمل الإشارة إلى من لم يذكرهم من الرسل، ألا تراه يقول: {وَلَقَدْ أَرْسَلْنَا رُسُلًا مِنْ قَبْلِكَ مِنْهُمْ مَنْ قَصَصْنَا عَلَيْكَ وَمِنْهُمْ مَنْ لَمْ نَقْصُصْ عَلَيْكَ} [غافر: 78] ولا سبيل إلى استقصاء شواهد ذلك في هذا المؤلف الوجيز ــ\rوالخلاصة أن من صدق في طلب الحق وجد في هذا القرآن المجيد بغيته من أي فريق كان، من فريق التعويل على البرهان الكلى، أو من قبيل الذين لا يعولون إلا على الجزئيات التي شوهدت، أو الصنف الذين تكفيهم الموعظة ولهذا أقسم الله به فقال (والقرآن الحكيم) ولفت أنظار عباده إلى ما فيه من "], [49, "الأوصاف العليا، والمعاني الرفيعة، والمتع العقلية المتنوعة، فقال: {يَاأَيُّهَا النَّاسُ قَدْ جَاءَتْكُمْ مَوْعِظَةٌ مِنْ رَبِّكُمْ وَشِفَاءٌ لِمَا فِي الصُّدُورِ وَهُدًى وَرَحْمَةٌ لِلْمُؤْمِنِينَ} [يونس: 57].\r(تنوير في تفسير إقتربت الساعة)\r"]], "pg": [43, 49]}, "526.14": {"x": [[49, "إليك سورة كريمة من سور هذا الكتاب العزيز ليس فيها إلا هذا الصنف من البراهين الحسية والأدلة التي شوهدت حقائقها في العوالم الخارجية وهي التي يطلق عليها الكيماويون اليوم الأدلة العلمية، وهي سورة القمر، ابتدأها الله تعالى بآية سماوية كبرى، لا يحوم حول سناها الوضاء غبش من شك، ولا غلس من شبهة، قد رآها المخاطبون بأعينهم، وشاهدوا ضياءها بأنفسهم، في مجمع ينتظم أكابر المعاندين الجاحدين، وخلص المؤمنين المنصفين، وهي انشقاق القمر في ليلة أضحيان.\rأخرج البخاري ومسلم في صحيحيهما وغيرهما من المحدثين عن عدة من أصحاب رسول الله صلى الله عليه وسلم ((أن كفار أهل مكة سألوا رسول الله صلى الله عليه وسلم أن يريهم آية، وأن تكون هذه الآية انشقاق القمر، فدعا ربه فانشق القمر فلقتين وهم ينظرون، فقال صلى الله عليه وسلم: أيها الناس اشهدوا)) ثم عاد كما كان بعد ما اتضحت آية القمر وضوح الشمس. {فَأَمَّا الَّذِينَ آمَنُوا فَزَادَتْهُمْ إِيمَانًا وَهُمْ يَسْتَبْشِرُونَ (124) وَأَمَّا الَّذِينَ فِي قُلُوبِهِمْ مَرَضٌ فَزَادَتْهُمْ رِجْسًا إِلَى رِجْسِهِمْ} [التوبة: 124، 125] فقال قائلون منهم إن محمدا سحر أعيننا، وقال آخرون لئن استطاع محمد أن يسحر مجلسنا فلن يستطيع أن يسحر المارة من أهل الآفاق خارج مكة فارقبوهم فسلوهم. فتحروا فسألوا المارة في تلك الساعة أرأوا في القمر شيئا وهم يمشون على نوره؟ فاتفقت كلمة الكل أنهم رأوا القمر قد انشق بفرقتين، ثم عاد كما كان، فقال الذين لجوا في عتو ونفور: ما حكى الله في قوله {اقْتَرَبَتِ السَّاعَةُ وَانْشَقَّ الْقَمَرُ (1) وَإِنْ يَرَوْا آيَةً يُعْرِضُوا وَيَقُولُوا سِحْرٌ مُسْتَمِرٌّ} [القمر: 1، 2] فلم ينكروها ولكن تأولوها بما لا يقبله منصف ولا يرتضيه إلا صاحب هوى، ولذلك أردفه بقوله سبحانه\r{وَكَذَّبُوا وَاتَّبَعُوا أَهْوَاءَهُمْ} [القمر: 3] "], [50, "وإنكار الآية الساطعة إن دل على شيء فليس يدل إلا على فساد في نفسية المنكر، برذيلة هوى غطت فضيلة الانصاف. قال الإمام الفقيه المحدث ابن عبد البر ((قد روى هذا الحديث ــ يعني حديث انشقاق القمر بدعائه صلى الله عليه وسلم حين سألوه إياه ــ جماعة كثيرة من الصحابة. وروى ذلك عنهم أمثالهم من التابعين، ثم نقله عنهم الجم الغفير إلى أن انتهى إلينا)). اهـ\rولا يرتاب منصف أن هذه الآية الكبرى لا يكاد يعد لها شيء من آيات النبيين عليهم الصلاة السلام، وربما أعمى الهوى ــ والهوى يعمى ويصم ــ المغرقين في التعصب للباطل فشكك فقال: لو حدثت لشاهدها جميع أهل الأرض ولدونتها تواريخ أهل الغرب إلى أمثال هذه الهذيانات التي تندفع عن العاقل بأدنى تأمل، فأن أطوال البلاد مختلفة، بل الصحو والغيم في البلاد ذات الطول الواحد بل في البلد الواحد مختلف جد الاختلاف، وأهل المراصد إنما يرقبون ما تهدى إليه القواعد العامة الفلكية. أما آية إلهية خارجة عن النواميس المألوفة والضوابط المعروفة، فأنه لن يشهدها إلا طالبوها غالبا. وكم من كسوف ليلى أو طلوع لكوكب مذنب يحدث ولا يدري به إلا القليل من أهل ناحيته، وربما لم يشعر به إلا من عرف القواعد من القاعدة نفسها لا من مشاهدته\rإن آيات ربنا بينات. ... لا يمارى فيهن إلا الكفور\rومن الناس من قل علمه بتفسير كتاب الله فتأول (وانشق) على معنى سينشق، وهو تأويل إن أفاد فليس يفيد إلا جهل قائله بالسنة الصحيحة، بل المستفيضة التي كادت تبلغ حد التواتر، بل قال بعض العلماء بتواترها تواترا معنويا، وغفلته عن سياق الآيات الكريمة كما بين ذلك حذاق المفسرين رضي الله عنهم. ولست أظنك تأبه بقول من يقول طعنا على هذه الآية الكبرى: إن ذلك يخالف نواميس الكون؛ بعد الذي بيناه في الفصول السابقة مفصلا في أمر هذه النواميس. ثم انطلقت السورة الكريمة تسرد من هذه البراهين السابقة من الله "], [51, "تعالى التي أحست وشوهدت في الماضين، وقد حفظها العلم ووعاها التاريخ، تفصيلا عند علماء أهل الكتاب، وإجمالا عند سواهم، فذكرت خمس قصص على أبدع هداية وأروع دلالة، ثم التفتت فقالت لهذه الأمة (أكفاركم خير من أولئكم) ثم أردفت ذلك بوعيد مستقبل قريب تحققت مشاهدتهم له فيما بعد تزول السورة الكريمة، وهو في قوله تعالى {سَيُهْزَمُ الْجَمْعُ وَيُوَلُّونَ الدُّبُرَ} [القمر: 45] فتحقق في غزاة بدر والحمد لله على سطوع حجته، ونسأله الهدى لسلوك محجته وحسن الخاتمة.\rوهذه أخرى من كرائم سور هذا الكتاب الكريم تنحو هذا النحو، وهي سورة الشعراء، فكما يقص صاحب الكيمياء مشاهدات السابقين في هذا العلم واحدا بعد واحد؛ ليسرى على ضوء أبحاثهم، قص تعالى وله المثل الأعلى في هذه السورة سبع قصص لسبعة أنبياء عظام، أرسلوا إلى أمم ضخام، فكانت العاقبة لمن صدق المرسلين، وكانت الخيبة للمعاندين، ثم قال بعد كل هذا {وَإِنَّهُ لَتَنْزِيلُ رَبِّ الْعَالَمِينَ (192) نَزَلَ بِهِ الرُّوحُ الْأَمِينُ} [الشعراء: 192، 193] الآيتين. ثم لم يدعها بلا دليل بل استدل على أنه تنزيل منه سبحانه، وليس من عند هذا الداعي الأمين، يقوله تعالى {أَوَلَمْ يَكُنْ لَهُمْ آيَةً أَنْ يَعْلَمَهُ عُلَمَاءُ بَنِي إِسْرَائِيلَ} [الشعراء: 197] ومن الظاهر المكشوف لأعدائه المعاصرين له، وأحبائه ومن بعدهم من العارفين بتاريخه، أنه لم يخالطهم وكان أميا لم يتل قبل القرآن من كتاب ولا خطه بيمينه، فصلى الله وبارك على هذا النبي، ما أسطع ضياء شمس رسالته. وجل هذا القرآن المجيد ما أوضح وأكثر أدلته. ولنقسر القلم عن السير فميادين هذا القرآن فسيحة وروائعه تحفى الأقلام دون استقصائها، ولنرتق بك إلى المقصد من هذا المؤلف ففيما مضى من هذه المقدمات ما يجعل الكلام معك فيه واضحا بينا إن شاء الله، فلتكن منك على بال. "], [52, "(المقصد في الصفات المختصة بالخلق والصفات المختصة بالحق "]], "pg": [49, 52]}, "526.15": {"x": [[52, "على ما يهدى إليه القرآن الحكيم ويشهد به العقل السليم).\rتمهيد في أن العلم بما في هذا المقصد أعز العلوم وأسناها\r"]], "pg": [52, 52]}, "526.16": {"x": [[52, "اعلم علمك الله العلم النافع أن العلم بما في هذا المقصد أعز العلوم وأسناها وأن مسائله أنفس المطالب وأرقاها، والجهل بها شديد الخطر عظيم الخطب فإنه يفضى بصاحبه إما إلى كفر تكون نهايته الوقوع في عذاب الله بلا نهاية، وإما إلى بدعة شنعاء تنزل بصاحبها عن أوج درجات العلماء بالله إلى حضيض دركات المتخبطين في ظلمات الأوهام، وهل نبت الاشراك بالله تعالى في هذه الإنسانية إلا من بذور الجهالة بهذه المطالب العليا؟ وهل انشعب القول باتصاف الله تعالى بالولادة تارة واتخاذ الولد أخرى إلا من التلوث بجراثيم هذه العقائد المزيفة؟ وهل تفرع القول بحمل الآيات المتشابهة والأحاديث النبوية المشكلة على المعنى الظاهري الذي تفهمه الجهلة إلا من عدم الإحاطة بأصول هذا العلم الأممي المنبثة في هذا القرآن المجيد، والمغروسة في الفطر التي لم تصب يمرض التقليد، الشيوخ الهوى الناكبين عن طريق الهدى المتكلمين فيما لم يحيطوا بعلمه، فتأولوه على غير وجهه، وأخذوا يسترون جهالاتهم عن أتباعهم من العامة بذم علم الكلام والمتكلمين من أهل السنة، شكر الله تعالى سعيهم، واستراحوا إلى ما نقل عن السلف الأولين كالشافعي وأحمد وأضرابهما من ذم الكلام وأهله، ومن لي بأن يعرف هؤلاء وأشياعهم أن الكلام كان يطلق في تلك العهود السابقة على ما يأتي به أهل الأهواء من الطعن في القدر وإنكار الشفاعة في عصاة الموحدين، وخلق الجنة والنار، والصراط والميزان، والحوض وأخذ الكتب بالإيمان أو الشمائل، وغفران الله ما دون الشرك لمن يشاء، وكالحوض في صفات الله وجعلها كصفات"], [53, "البشر، فوصفوه بالمكان والجهة والنزول والصعود المتعارفين للأجسام، إلى أشباه ذلك من بدع المعتزلة والكرامية وغيرهما، وأول من صنف في الكلام من أهل الأهواء واصل بن عطاء شيخ المعتزلة، وتابعه على ذلك أكابر شيعته، ومن أجل هذا اشتد النكير من أئمة أهل السنة على الكلام والخائضين في الكلام، والقارئين في كتب أهله، وهم يريدون ما أتى به أهل الأهواء على اختلاف نحلهم في مجالسهم ومصنفاتهم. ولما اشتد ساعد البدع وانتشر ضررها في الناس بمشاغبة دعاتهم وانتشار مؤلفاتهم الموبوءة بين العامة، اضطر أهل الحق للكلام في رد هذه البدع بعقد مجالس المناظرة معهم والتصنيفات الجامعة لما بينه القرآن من أصول الدين، وأوضحته السنة، وقررته العقول المستنيرة، كشفا لعوار تلك البدع، وإزاحة للظلم التي لبس بها أهل الهوى عن وجه الهدى الذي جاء به الكتاب العزيز. وصار الكلام بعد ذلك يطلق إطلاقا آخر ويراد به معنى سوى المعنى الأول الذي أنكرته الأئمة. هذا الأطلاق الثاني هو إطلاقه على ما جاء به المحققون من أكابر أهل السنة من الحجج الدامغة لأباطيل الكفار، وشبه المبتدعة من أهل الإسلام، وأصبح علم الكلام لا يراد به إلا هذا، وكثرت فيه التصانيف من المتقدمين والمتأخرين، فانهز أهل الأهواء جهل العامة بالفرق بين هذين الاطلاقين ونقلوا لهم كلمات الأئمة في ذم الكلام وأهله، ليصدوهم عن كتب أهل الحق النافية للتجسيم ولوازمه عن رب العزة، كما يقتضيه كتاب الله سبحانه كما سنفصله في هذا المقصد إن شاء الله. وليس ببدع ما يسلكه مبتدعة عصرنا من ذلك، بل هي طريقة مسلوكة قديما لأسلافهم الأولين، ودونك ما قال في هذا المقام إمام أئمة أهل السنة ومقدم الجماعة علما وحالا وقالا، والمجمع على مكانته العليا في الفضل من الموافق والمخالف، الأستاذ الأجل أبو القاسم عبد الكريم بن هوازن القشيري صاحب الرسالة التي سارت بين أهل الفضل مسير الشمس، وأزالت عن طريق أهل الحق كل لبس، في رسالته التي بعث بها إلى علماء المشارق والمغارب المسماة "], [54, "((شكاية أهل السنة بحكاية ما نالهم من المحنة)) قال فيها رضي الله عنه بعد أوراق ما نصه ((فان قالوا إن الاشتغال بعلم الكلام بدعة ومخالفة لطريق السلف (قيل) وأخذ في الجواب إلى أن قال: الاسترواح إلى مثل هذا الكلام صفة الحشوية الذين لا تحصيل لهم، وكيف يظن بسلف الأمة أنهم لم يسلكوا سبيل النظر، وأنهم رضوا بالتقليد؟ حاش لله أن يكون ذلك وصفهم. ولقد كان السلف من الصحابة رضي الله عنهم مشتغلين بما عرفوا من الحق، وسمعوا من الرسول صلى الله عليه وسلم من أوصاف المعبود، وتأملوه من الأدلة المنصوبة في القرآن وأخبار الرسول صلى الله عليه وسلم في مسائل التوحيد. وكذلك التابعون وأتباع التابعين لقرب عهدهم من الرسول صلى الله عليه وسلم، فلما ظهر أهل الأهواء وكثر أهل البدع من الخوارج والجهمية والمعتزلة والقدرية وأوردوا الشبه، انتدب أئمة أهل السنة لمخالفتهم والانتصار للمسلمين بمباينة طريقتهم، فلما أشفقوا على القلوب أن تخامرها شبههم، شرعوا في الرد عليهم، وكشف فسقهم، وأجابوهم عن أسئلتهم، وحاموا عن دين الله بإيضاح الحجج، ولما قال الله تعالى {وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ} [النحل: 125] تأدبوا بآدابه، ولم يقولوا في مسائل التوحيد إلا بما نبههم الله سبحانه عليه في محكم التنزيل. والعجب ممن يقول ليس في القرآن علم الكلام، والآيات التي في الأحكام الشرعية العملية معروفة معدودة، والآيات التي في الأحكام الاعتقادية ودلائلها تجدها تزيد على ذلك العدد وتربي بكثير، وفي الجملة لا يجحد علم الكلام إلا أحد رجلين: جاهل ركن إلى التقليد وشق عليه سلوك أهل التحصيل، وخلا عن طريق أهل النظر، والناس أعداء ما جهلوا، فلما انتهى عن التحقيق بهذا العلم نهى الناس ليضل غيره كما ضل. أو رجل يعتقد مذاهب فاسدة فينطوي على بدع خفية يلبس على الناس عوار مذهبه ويعمى عليهم فضائح طويته وعقيدته، ويعلم أن أهل التحصيل من أهل النظر هم الذين يهتكون الستر عن بدعهم، ويظهرون للناس قبح مقالتهم، والقلاب ــ يعني مزيف النقود لا يحب من يميز "], [55, "النقود. والخلل فيما في يده من النقود الفاسدة لا في الصراف ذي التميز والبصيرة، وقد قال الله تعالى {هَلْ يَسْتَوِي الَّذِينَ يَعْلَمُونَ وَالَّذِينَ لَا يَعْلَمُونَ} [الزمر: 9] انتهى ما أردنا نقله من هذه الرسالة القيمة لهذا الحبر الجليل، وقد نقلها كلها التاج رضي الله عنه في الجزء الثاني من طبقاته، وأولها من صفحة خمس وسبعين ومائتين من النسخة المطبوعة بمصر لأول مرة، وكفاك بقول هذا الإمام الحجة دليلا على ما أسلفنا. نعم إن كثيرا من فضلاء أهل هذا الفن قد اضطرهم لجاج خصوم السنة ودعاة البدعة، إلى التوسع في البحث فدخلوا في متاهات ليس الجمهور في حاجة إلى التورط في دخولها. وفيما دل عليه كتاب الله غنية أي غنية، وبيان هو خير بيان، ولذلك لا نقذف بك إلى هذه اللجح، بل نسلك بك الجادة التي اختطها للناس هذا الكتاب العزيز، ونريك كيف أبان القرآن صفات المخلوقات التي لا يصح أن يتصف بها العزيز الحكيم، وأوضح الصفات المختصة بالحق ولا يجوز أن تكون من أوصاف المخلوقات، فأنه كما هو قرآن جمع لهذه الأمة علوم الأولين والآخرين، هو فرقان فرق بين الهدى والضلال، وبين الرشد والغي، بين ما ينبغي للرب وما هو وصف العبد، فالحمد لله الذي أنزله قرآنا عربيا تبيانا لكل شيء، لا بد للناس منه في اعتقاداتهم وأعمالهم أحوج ما كانوا إليه، فأنهم كانوا من قبل نزوله في ضلال مبين، طالت عليهم الفترة من الرسل فساد الفساد وعم الجهل، وبدل علماء السوء من أهل التوراة والإنجيل دين الله الذي أنزله إليهم، وتحكموا في عقول العامة حتى حجروا عليهم التفكير فيما يلقون إليهم. وأوهموهم أن الدين فوق العقل، ولم يستطع علماء الآخرة منهم أن يجاهروا بالحق الذي يعلمونه. هذه حال أهل الكتابين، فما ظنك بالعرب والفرس وأهل الهند والصين، أخذت منهم الوثنية كل مأخذ، وسلك بهم الهوى من الضلال كل مسلك، فما هو إلا أن فتح الكريم الوهاب أبواب رحمته الكبرى فبعث هذا النبي الأمي بهذا الكتاب العربي هدى لناس وبينات من الهدى والفرقان، وهو كما أخرج الترمذي من "], [56, "حديث أمير المؤمنين علي رضي الله عنه في وصف القرآن العظيم قاله: ((فيه نبأ ما كان قبلكم وخبر ما بعدكم، وحكم ما بينكم، هو الفصل "]], "pg": [52, 56]}, "526.17": {"x": [[56, "ليس بالهزل، من تركه من جبار قصمه الله، ومن ابتغى الهدى في غيره أضله الله، وهو حبل الله المتين، وهو الذكر الحكيم، وهو الصراط المستقيم، هو الذي لا تزيغ به الأهواء ــ أي لا تنحرف الأهواء عن الحق ما دامت تصاحبه ــ ولا تلتبس به الألسنة ــ أي لا يشتبه على الألسنة ــ بغيره لقوة ظهوره وشدة يمزه عن كلام الناس بنظمه وأسلوبه وحفظ الله إياه ولا يشبع منه العلماء ولا يخلق على كثرة الرد ولا تنقضي عجائبه)) الحديث، وقوله فيه يخلق بضم اللام وفتحها مع فتح الياء أو بضم الياء مع كسر اللام من أخلق وكله بمعنى يبلى كما سبقت الإشارة إليه في المقدمة.\r(فصل)\rاعلم أن الحكمة التي هي بمعناها الصحيح وهي الحق المحض ولب العلم الخالص والتي الاحراف عنها أو التحريف فيها خروج عن الجادة ودخول في الباطل. الحكمة التي هذا وصفها هي ما جاء به القرآن المجيد، ونطق به الخبر الصحيح، عن سيد المرسلين صلى الله عليه وسلم، وهي أن لهذا العالم كله عاليه وسافله، شاهده وغائبه. لطيفه وكشيفه. ربا واحدا لا شريك له وإلها فردا لا نظير له، وهو الأول لا ابتداء لوجوده الأعلى، وسائر كمالاته العليا ولا انتهاء. المقدس عن البساطة والتركب المنزه عن الأعضاء والأجزاء، المتعالى عن الحدوث والامكان ولوازمهما، المبرأ عن الاحتياجات، الغنى كل الغنى عما سواه، الحي بذاته لا بروح تحله ولا بسبب يقتضيها، المحيي لما شاء كما يشاء، النافذ الإرادة، التام القدرة على ما يريد. لا مانع لما أعطى ولا معطي لما منع، علم كل شيء قبل أن يكون شيء، علما أزليا كسائر صفاته المقدسة. وليس علمه عن كسب ولا تجربة وهو السميع البصير، جل سمعه عن الحاجة إلى الأعصاب والاصمخة والآذان، وتعالى بصره عن الحدقة والاجفان "], [57, "أنزل منه كتبه على رسله فضلا منه ورحمة، كان ولم يكن شيء غيره، ثم فطر هذه الكائنات منا منه بها عليها. وأبدعها على صفات تدل عقلاءها على أنها حادثة ممكنة، وترشدهم إلى انفراد مبدعهم بالكمال الأعلى، فكان من علي اقتداره أن جعل الحجة منهم عليهم، والدلالة عليه سبحانه فيهم لازمة لهم، وخلق العقول وألهمها التفكر فيما لديها وما بين يديها، وأكمل حجته وأبان محجته بإرسال المرسلين وختمهم عليهم الصلاة والسلام بأوضحهم بيانا وأفصحهم لسانا وأجمعهم كتابا وأظهرهم صوابا نبينا محمد صلى الله عليه وسلم فبلغت حجته سبحانه غايتها، وظهر برهانه أظهر من كل ظهور لا سيما بهذا الكتاب المبين، فإنه يأمر العقول بالنظر، ويهيب بالأفكار أن تتحرك ويصيح بالجامدين على التقليد بآبائهم فيما ورثوا من الجهل أن يستبصروا فيقول {أَفَلَمْ يَرَوْا إِلَى مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ مِنَ السَّمَاءِ وَالْأَرْضِ} [سبأ: 9] ويستلفت إلى ما هو أقرب من السماء والأرض وهو الأنفس فيقول: {أَوَلَمْ يَتَفَكَّرُوا فِي أَنْفُسِهِمْ} [الروم: 8] ويزيد في البيان فيقول: {إِنَّ فِي السَّمَاوَاتِ وَالْأَرْضِ لَآيَاتٍ لِلْمُؤْمِنِينَ (3) وَفِي خَلْقِكُمْ وَمَا يَبُثُّ مِنْ دَابَّةٍ آيَاتٌ لِقَوْمٍ يُوقِنُونَ (4) وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ وَمَا أَنْزَلَ اللَّهُ مِنَ السَّمَاءِ مِنْ رِزْقٍ فَأَحْيَا بِهِ الْأَرْضَ بَعْدَ مَوْتِهَا وَتَصْرِيفِ الرِّيَاحِ آيَاتٌ لِقَوْمٍ يَعْقِلُونَ} [الجاثية: 3 - 5] يعني أنه سبحانه قد جعل فيما ذكر أمارات واضحة ودلائل ناطقة بحاجتها إلى الخالق الحكيم، وانفراد هذا الخالق بالكمال الأتم فلا يصح أن يعبد سواه، ولا يرجى الخير إلا منه، ولا يدفع الضر إلا هو: فان الآيات جمع آية وهي العلامة والأمارة والدليل، وقد جعلها من الظهور بحيث لا يمنع من فهمها إلا انصراف العقل عن النظر إليها، وتلوث النفس بجراثيم التشكك فيها الذي لا مبرر له، والعناد بغيا وتكبرا، وهذا هو السر في قوله تعالى (للمؤمنين ــ لقوم يوقنون ــ لقوم يعقلون) فالمعنى أن من أراد أن يؤمن بهذا الهدى وطلب اليقين بهذا الحق، وأعطى العقل حظه من النظر الصحيح، وجد في السموات والأرض وما ذكر في الآيتين ما يبلغه ما يريد، ويدله على أن هذه الكائنات "], [58, "محدثة مخلوقة، وأن المنفرد بخلقها والمستحق لعبوديتها هو ذلك الرب الواحد المجيد. ــ ويا سبحان الله ما أعجب إرشاد هذا القرآن!! يرى التفاوت بين العقول فمنها القوى على الجولان في ملكوت السموات والأرض، القادر بإذن الله على استخراج ما لا يحصى من درر آيات الله من بحار هذا الملكوت فيطلق له النظر في الآيات إطلاقا كما في الآيات التي تلوناها. ومنها المتوسط ودون المتوسط فيضع في يده من تلك الآيات ما يكون له صراطا مستقيما إلى المطلب.\rفانظر معي ــ بصرك الله ــ إلى صرائح هذه الآيات التي أتلوها عليك {وَلَقَدْ جَعَلْنَا فِي السَّمَاءِ بُرُوجًا وَزَيَّنَّاهَا لِلنَّاظِرِينَ} [الحجر: 16] والبروج: الكواكب العظام {وَالْأَرْضَ مَدَدْنَاهَا وَأَلْقَيْنَا فِيهَا رَوَاسِيَ وَأَنْبَتْنَا فِيهَا مِنْ كُلِّ شَيْءٍ مَوْزُونٍ} [الحجر: 19] فتأمل في قوله ((مددناها)) فهذا المد فيها مع كونها كرة من أبدع ما يدل على حكمة من وضعها لمعيشة هذه الكائنات عليها، وتبصر جد التبصر في قوله في النبات {مِنْ كُلِّ شَيْءٍ مَوْزُونٍ} [الحجر: 19] ولن تستطيع أن تفهمه حق فهمه حتى تتبحر في علم المملكة النباتية وتقرأ ما كتب في النبات وأجزائه ومقادير العناصر التي تنساق إليه على ما يناسب كل نوع منه. وللفاضل الشيخ طنطاوي جوهري في تفسير هذه الآية وأشباهها من تفسيره المطبوع يد طولي في بيان بعض هذه الأسرار التي لا يحيط بتمامها إلا الخلاق العليم. فارجع إليه إن أحببت اقتباس هذه الفوائد الشريفة. ثم قال تعالى: {وَإِنْ مِنْ شَيْءٍ إِلَّا عِنْدَنَا خَزَائِنُهُ وَمَا نُنَزِّلُهُ إِلَّا بِقَدَرٍ مَعْلُومٍ} [الحجر: 21] فأقسم بالذي أنزلها إن المجلدات الكثيرة الضخمة لن تفي بتفسير هذه الآية على التفصيل، بل ولا بعشر معشارها، فإنه شرح المكونات كلها وبيان الحكم التي لا تحصى في تخصيصها بما هي عليه من صفاتها ومقاديرها، وأوقاتها وأشكالها وألوانها وإضاءة المضيء منها، وغير ذلك مما لا يضبطه العد ــ والمعنى الإجمالي لهذا الكلام العزيز أن الوزن بميزان الحكمة ليس قاصرا على النبات فحسب، وليس ما في الكون كله هو كل ما في قدرتنا، بل ما من شيء في الكون إلا "], [59, "ونحن قادرون على جعله أضعافا مضاعفة، غير أن عنايتنا اقتضت أن لا تبرز من علي جودنا إلى فضاء هذا الوجود إلا ما تحده الحكمة ويقتضيه علمنا الأعلى، ورحمتنا التي لا تحد. قال الإمام المحقق ناصر الدين البيضاوي في تفسيرها ((وما من شيء إلا ونحن قادرون على إيجاده وتكوينه أضعاف ما وجد منه، فضرب الخزائن مثلا لاقتداره، أو شبه مقدوراته بالأشياء المخزونة التي لا يحوج إخراجها إلى كلفة واجتهاد ((وما ننزله)) من يفاع القدرة ((إلا بقدر معلوم)) حدته الحكمة وتعلقت به المشيئة، فإن تخصيص بعضها بالإيجاد في بعض الأوقات مشتملا على بعض الصفات والحالات، لا بدله من مخصص حكيم)) انتهت عبارته رضي الله عنه ــ واليفاع ــ بفتح الياء المثناة من تحت والفاء المخففة: المرتفع وأشار به إلى أن التنزيل هنا ليس من باب المكان كما يخطر للواهمين وإنما هو من علو مقام المعطى جلا جلاله.\r(فصل في أن كل مقدر بقدر ومحدود بحدود، فهو حادث)\r"]], "pg": [56, 59]}, "526.18": {"x": [[59, "ثم الآية المكريمة بعد هذا تعطيك مسألة من علم التوحيد، بل مسائل هي من أهم مسائله وهي أن كل مقدر ومحدود بحدود، فهو حادث ممكن، لا بد له في وجوده واختصاصه بقدره الذي هو عليه من فاعل موجود واجب، أعطاه وجوده وخصصه بالقدر الذي هو عليه، وما من شيء في العالم إلا وهو ذو قدر معين في ذاته ومكانه وزمانه وصفاته، من صغر وكبر، وطول وقصر، وخفة وثقل، ونور وظلمة، وارتفاع وانخفاض، ولطافة وكثافة، وسيلان وجمود، وحرارة وبرودة، وحركة وسكون، وما يستتبع هذا من أشكال وألوان، وطعوم وروائح، وصعود ونزول، وأمكنة وجهات، وقرب وبعد، إلى سائر خصائص المادة مما لم نذكره وبين في علم خصائص المادة، فكل ذلك تنطق الآية الكريمة بأنه مختص بالمخلوقات يتعالى عن الاتصاف بشيء منه ربها وخالقها، فإن "], [60, "كل ذي قدر فهو مخلوق، إذ الخلق يدور في اللغة على معنى التقدير أو الإيجاد على قدر معين، ولذلك يقول تعالى: {اللَّهُ خَالِقُ كُلِّ شَيْءٍ} [الرعد: 16] ومعناه أن كل شيء فله قدر مخصوص كما ترون، وذو القدر المخصوص ينادي على نفسه بأنه حادث ممكن مخلوق لا بد له من خالق فأنا خالقه لا خالق له سواي، فالقرآن ينادى بأن الجسمية، ولوازمها هي من دلائل الحدوث ولوازم الإمكان، وهذا هو بعينه ما قرره علماء المعقول، وفضلاء أهل علم الكلام، بل كل ذي قدر ولو صغر جدا بحيث لا يبلغ أن يكون جسما، فهو داخل فيما حكمت عليه الآية أنه مخلوق للقادر الحكيم. ولم يكتف القرآن حتى صرح بهذه اللوازم تفصيلا لمن تدبره مستدلا بها لعباده فقال: {وَالسَّمَاءَ رَفَعَهَا} [الرحمن: 7] {وَالْأَرْضَ وَضَعَهَا} [الرحمن: 10] فهذا بين لك أن الارتفاع والانضاع الحسيين كما يشاهد في السماء والأرض هما من صفات الحادثات الممكنات لا بدلهما من فاعل وأنه فاعل ذلك فهو الرافع الخافض، وما هو من دلائل الحدوث يستحيل أن يكون وصفا للواجب المتعالي. وكذلك قال سبحانه {اللَّهُ الَّذِي رَفَعَ السَّمَاوَاتِ} [الرعد: 2] {وَهُوَ الَّذِي مَدَّ الْأَرْضَ} [الرعد: 3] أي خفضها وجعلها بحيث تصلح للمشي في مناكبها قال {وَجَعَلَ فِيهَا رَوَاسِيَ وَأَنْهَارًا وَمِنْ كُلِّ الثَّمَرَاتِ جَعَلَ فِيهَا زَوْجَيْنِ اثْنَيْنِ} [الرعد: 3] ثم ذكر انقسام الأرض إلى أجزاء مختلفة واتصاف ثمار الجنات والزروع بتفاضل بعضها على بعض في الأكل، وأنه هو فاعل ذلك ومجزئه ومقسمه، كما أشار في آية أخرى إلى أنه مجزئ جسم الإنسان إلى أجزاء، وجاعل لكل منها وظيفة، فقال {أَلَمْ نَجْعَلْ لَهُ عَيْنَيْنِ (8) وَلِسَانًا وَشَفَتَيْنِ} [البلد: 8، 9] واحتج على الإنسان بوجوده على القدر المخصوص وتجزئته إلى الأجزاء المسماة المعدولة عما يجوز عليها من الصفات إلى ما هي عليه من الحسن والنظام وتركبه. فقال: {يَاأَيُّهَا الْإِنْسَانُ مَا غَرَّكَ بِرَبِّكَ الْكَرِيمِ (6) الَّذِي خَلَقَكَ فَسَوَّاكَ فَعَدَلَكَ (7) فِي أَيِّ صُورَةٍ مَا شَاءَ رَكَّبَكَ} [الانفطار: 6 - 8] فالعقول تفهم ببداهتها أن الانقسام إلى الأجزاء لا سيما إذا كانت مسواة، والتركب من الجوارح والأعضاء لا بد له من موجد مقسم مركب، ولذلك "], [61, "احتج الله به على ابن آدم، ومحال أن يحتج الله على الحدوث بوصف ثم يكون هذا الوصف في ذاته عز وجل، فمن قال بتركب ذات الله من الأجزاء وحمل اليدين والعين والأعين والوجه واليمين الواردة في كتاب الله في وصف الله والقدمين والساق في الحديث على الأعضاء والأجزاء، وحمل العلو الوارد في وصفه تعالى على العلو الحسى المكاني، والنزول على مثل ذلك، وأن ذلك مقتضى الكتاب والسنة، وأنه بذلك يكون سلفيا، فما فهم الكتاب ولا السنة ولا تابع السلف الصالح، فهذا كتاب الله يرد عليه أبلغ رد، وما أبدع ما قال ناصر الدين القاضي البيضاوي في تفسير قوله تعالى: {وَجَعَلُوا لَهُ مِنْ عِبَادِهِ جُزْءًا} [الزخرف: 15] ونصه بعد ما ساق الجملة الشريفة ((متصل بقوله (ولئن سألتهم) أي وقد جعلوا له بعد ذلك الاعتراف من عباده ولدا فقالوا: الملائكة بنات الله، لعله سماه جزءا كما سمى بعضا، لأنه بضعة من الوالد، دلالة على استحالته على الواحد الحق في ذاته)) اهـ، فإنه تعالى لو جاز عليه الانقسام أو صح عليه الصغر أو الامتداد لكان مقدرا، وقد علمت أن كتابه سبحانه ينادي بأن كل مقدر حادث مخلوق، فيكون ممكنا، والممكن يستحيل أن يكون خالقا وموجدا، وقد ثبت أنه الخلاق فيجب أن يكون متصفا بوجوب الوجود وتوابع هذا الوجود الواجب من الكمالات العليا، فوجب أن يكون منزها عن التركب وقبول الانقسام، وكل ما هو من خصائص المادة والأجسام، بذلك نطق كتاب الله لقوم يسمعون، ونادت بهذا آياته من ألقى إليها السمع وهو شهيد. وعلى ذلك أطبق أهل السنة الذين لم يصابوا بما أصيب به أهل الهوى من مرض التشبيه والتجسيم الذي أصيب به اليهود من قبلهم، ووقع فيه النصارى من بعدهم. والعجب أنك ترى إمام المدافعين عن بيضة أهل التشبيه وشيخ إسلام أهل التجسيم ممن سبقه من الكرامية وجهلة المحدثين الذين يحفظون وليس لهم فقه فيما يحفظون، أحمد بن عبد الحليم المعروف بابن تيمية، يرمي إمام الحرمين وحجة الإسلام الغزالي بأنهما أشد كفرا من اليهود "], [62, "والنصارى، في كتابه الموافقة المطبوع على هامش منهاجه، لقولهما بالتنزيه، وهما لم ينفردا به، بل هو قول المحققين من علماء الملة الإسلامية من الصحابة فمن بعدهم إلى زمانه ــ وكانت وفاته في القرن الثامن ــ وإلى زماننا، وإلى أن يأتي أمر الله. فقد صح عنه عليه الصلاة والسلام ((لن تزال طائفة من هذه الأمة ظاهرين على الحق لا يضرهم من خالفهم أو خذلهم حتى يأتي أمر الله)) وفي بعض ألفاظ هذا الحديث ((أنهم السواد الأعظم من أمته)) وسيأتي لنا كلام في خطر الاغترار بهذا الرجل ومصنفاته وشيعته، ورأى المحققين من الجهابذة فيه وفيهم فانتظر.\r(فصل في أن بين المقدرات من الجواهر وبين المكان والجهة لزوما بينا)\r"]], "pg": [59, 62]}, "526.19": {"x": [[62, "واعلم أن بين المقدرات من الجواهر التي هي الأجسام فما دونها وبين المكان والجهة لزوما بينا، وهو ما لا يحتاج عند العقلاء إلى دليل، فإن المكان هو الموضع الذي يكون فيه الجوهر على قدره، والجهة هي ذلك المكان، لكن يقيد نسبته إلى جزء خاص من شيء آخر، فكل جهة مكان ولا عكس، فالفراغ الذي أنت فيه هو مكانك، وباعتبار محاذاته لرأس شخص آخر هو جهة تسمى فوقا، وباعتبار محا ذاته لرجله تسمى تحتا، أو لوجهه أو ظهره أو أقوى يديه أو أضعفهما تسمى أماما وخلفا ويمينا وشمالا. والجوهر هو مقدر لا بد أن يأخذ قدرا من الفراغ على قدره صغيرا كان أو كبيرا، فأنت ترى من البين الجلي أن بينهما تلازما أي تلازم، والقول بأحد المتلازمين قول بالآخر، وبنفي أحدهما نفى للآخر. وقد عرفت أن القرآن يستدل في صراحة بتقدر الأشياء على حدوثها ومخلوقيتها، فمن السهل عليك أن تعرف أن القرآن قد قرر بذلك تعالى الحق في ذاته عن أن تكون مقدرة أو ذات امتداد، أو يجوز عليها الانقسام أو متصفة بكبر أو صغر كما هو للماديات، وذلك قول يهيب بأهل الفقه في كتابه أن يعتقدوا تنزهه عز وجل عن الجهة والمكان، ومن قال غير هذا فقد غلب عليه الوهم وفاته الفهم، فان نسب إلى "], [63, "الكتاب العزيز القول بالجهة والمكان في حق ربنا عز وجل، أو إلى السنة المطهرة فقد افترى على كتاب الله وكذب على سنة رسول الله صلى الله عليه وسلم، وأتى من ناحية جهله وقلة تفقهه في دلائل الكتاب العزيز، ونزعه عرق العجمة إلى مشابهة اليهود في القول بالتجسيم والجهة في حق الله تعالى عما يقولون. أو غلبته العصبية لهوى فيه أو فيمن قلدهم من أشياخ البدعة. فإن كان داعية إلى القول بذلك يعقد له الدروس ويصنف فيه الكتب وينادي به على المنابر فهو الذي أصيب بالجهل المركب وهو من أول الداخلين في قوله تعالى {فَأَمَّا الَّذِينَ فِي قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ مَا تَشَابَهَ مِنْهُ ابْتِغَاءَ الْفِتْنَةِ وَابْتِغَاءَ تَأْوِيلِهِ} [آل عمران: 7]. قال ترجمان السلف وشيخ المفسرين الإمام الحجة ابن جرير الطبري في تفسير هذه الآية: ((يعني بقوله جل ثناؤه فيتبعون ما تشابه ما تشابهت ألفاظه وتصرفت معانيه بوجوه التأويلات ليحققوا بادعائهم الأباطيل من التأويلات في ذلك ما هم عليه من الضلالة والزيغ عن محجة الحق، تلبيسا منهم بذلك على من ضعفت معرفته بوجوه تأويل ذلك وتصاريف معانيه)) ثم ساق بسنده عن ابن عباس من طريق على بن أبي طلحة عنه ــ وهو أصح الأسانيد فيما يروى عن ابن عباس في التفسير ــ قال فيتبعون ما تشابه منه فيحملون المحكم على المتشابه والمتشابه على المحكم ويلبسون فلبس الله عليهم)). ثم ذكر بسنده عن محمد بن جعفر بن الزبير وعن مجاهد نحوه ثم قال: واختلف أهل التأويل فيمن عنى بهذه الآية، فقال بعضهم عنى به الوفد من نصارى ذران الذين قدموا على رسول الله صلى الله عليه وسلم فحاجوه بما حاجوه به وخاصموه بأن قالوا ألست تزعم أن عيسى روح الله وكلمته؟ وتأولوا في ذلك ما يقولون فيه من الكفر، ثم ساق بالسند عن الربيع هذا القول، وحكى عن بعضهم أن المعنى اليهود الذين سألوا عن الحروف المقطعة أوائل السور، وساق قصتهم في ذلك. ثم قال: وقال آخرون بل عنى الله عز وجل بذلك كل مبتدع في دينه بدعة مخالفة لما ابتعث رسوله محمدا صلى الله عليه وسلم بتأويل يتأوله من بعض أي القرآن المحتملة التأويلات، وإن "], [64, "كان الله قد أحكم بيان ذلك إما في كتابه وإما على لسان رسوله. ثم ساق بسند صحيح عن قتادة في قوله {فَأَمَّا الَّذِينَ فِي قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ مَا تَشَابَهَ مِنْهُ ابْتِغَاءَ الْفِتْنَةِ} [آل عمران: 7] وكان قتادة إذا قرأ هذه الآية {فَأَمَّا الَّذِينَ فِي قُلُوبِهِمْ زَيْغٌ} [آل عمران: 7] قال إن لم يكونوا الحرورية والسبئية، فلا أدري من هم، ولعمرى لقد كان في أهل بدر والحديبية الذين شهدوا مع رسول الله صلى الله عليه وسلم بيعة الرضوان من المهاجرين والأنصار خبر لمن استخبر وعبرة لمن استعبر، لمن كان يعقل أو يبصر أن الخوارج خرجوا وأصحاب رسول الله صلى الله عليه وسلم يومئذ كثير بالمدينة والشام والعراق، وأزواجه يومئذ أحياء، والله إن خرج منهم ذكر ولا أنثى حروريا قط، ولا رضوا الذي هم عليه ولا مالؤوهم فيه، بل كانوا يحدثون بعيب رسول الله صلى الله عليه وسلم إياهم ونعته الذي نعتهم به، وكانوا يبغضونهم بقلوبهم، ويعادونهم بألسنتهم، وتشتد والله عليهم أيديهم إذا لقوهم، ولعمرى لو كان أمر الخوارج هدى لاجتمع، ولكنه كان ضلالا فتفرق، وكذلك الأمر إذا كان من عند غير الله وجدت فيه اختلافا كثيرا فقد ألاصوا ــ أي أرادوه وحاولوا رواجه ــ هذا الأمر منذ زمان طويل فهل أفلحوا فيه يوما أو نجحوا؟ يا سبحان الله!! كيف لا يعتبر آخر هؤلاء القوم بأولهم؟ لو كانوا على هدى لأظهره الله وأفلحه ونصره، ولكنهم كانوا على باطل أكذبه الله وأدحضه، تمهم كما رأيتهم كلما خرج لهم قرن أدحض الله حجتهم. وأكذب أحدوثتهم، وأهراق دماءهم، وإن كتموا كان قرحا في قلوبهم، وغما عليهم، وإن أظهروه أهراق الله دماءهم، ذا كم والله دين سوء فاجتنبوه، والله إن اليهودية لبدعة، وإن النصرانية لبدعة، وإن الحرورية لبدعة، وإن السبئية لبدعة ما نزل بهن كتاب ولا سنهن نبي)). ثم ذكر في الفتنة قولين في قوله تعالى (ابتغاء الفتنة) أهي الشرك أم الشبهات؟ ثم قال: وأولى القولين في ذلك بالصواب قول من قال معناه إرادة الشبهات واللبس، فمعنى الكلام إذا فأما الذين في قلوبهم ميل "], [65, "عن الحق وحيف عنه فيتبعون من أي الكتاب ما تشابهت ألفاظه، واحتمل صرفه في وجوه التأويلات باحتماله المعاني المختلفة إرادة اللبس على نفسه، وعلى غيره احتجاجا به على باطله الذي مال إليه قلبه دون الحق الذي أبانه الله فأوضحه بالمحكمات من أي كتابه وهذه الآية وإن كانت نزلت فيمن ذكرنا أنها نزلت فيه من أهل الشرك، فانه معنى بها كل مبتدع في دين الله بدعة فمال قلبه إليها تأويلا منه لبعض متشابه أي القرآن، ثم حاج به وجادل به أهل الحق وعدل عن الواضح من أدلة آية المحكمات إرادة منه بذلك اللبس عل أهل الحق من المؤمنين، وطلبا لعلم تأويل ما تشابه عليه من ذلك، كائنا من كان، وأي أصناف البدعة كان من أهل النصرانية كان أو اليهودية أو المجوسية أو كان سبئيا أو حروريا أو قدريا أو جهميا)) أهـ أقول: فهؤلاء وأشباههم من الذين ينعين على الأمة أن تحذرهم خصوصا من لم يتبحر في علم العقائد فإنه يلتبس عليه الأمر فيعتقد العقائد البدعية وهو يرى أنها صميم السنة، ومن أجل هذا جاء في الصحيح عن رسول الله صلى الله عليه وسلم أنه تلا قوله تعالى {هُوَ الَّذِي أَنْزَلَ عَلَيْكَ الْكِتَابَ مِنْهُ آيَاتٌ مُحْكَمَاتٌ} [آل عمران: 7] الآية ثم قال عليه الصلاة والسلام ((إذا رأيتم الذين يتبعون ما تشابه منه فأولئك الذين سماهم الله فاحذروهم)) أخرجه الشيخان. هذا وإني أعود فأكرر لك النصيحة مخلصا والله على ما أقول شهيد فأقول: إن القرآن المجيد لم يدع للمتأمل فيه مجالا للشك في أن ما كان من الصفات لازما من لوازم الجوهر صغيرا كان أو كبيرا هو من دلائل الحدوث، والحدوث يستلزم الاكمان، وقد سبق لك البرهان في المقدمة على ذلك، ألا ترى الله سبحانه وتعالى يقول {وَخَلَقَ كُلَّ شَيْءٍ فَقَدَّرَهُ تَقْدِيرًا} [الفرقان: 2] {قَدْ جَعَلَ اللَّهُ لِكُلِّ شَيْءٍ قَدْرًا} [الطلاق: 3] {الَّذِي خَلَقَ فَسَوَّى} [الأعلى: 2] فكون الشيء على قدر مخصوص يستلزم بوضوح أن له مقدرا قدره، فبين القرآن أن مقدر المقدرات إنما هو الله وحده، وما من شيء من هذه الكائنات إلا له قدر مخصوص، وكذلك دل مولانا عز وجل عباده على الحدوث بالحركات واختلافها، والأجزاء للشيء"], [67, "الحنابلة ببغداد وابن رئيسها ((أنكر أحمد على من قال بالجسم، وقال إن الأسماء مأخوذة من الشريعة واللغة، وأهل اللغة وضعوا هذا الاسم على ذي طول وعرض وسمك وتركيب وصورة وتأليف، والله سبحانه خارج عن ذلك كله، فلم يجز أن يسمى جسما لخروجه عن معنى الجسمية، ولم يجيء في الشريعة ذلك فبطل)) اهـ بحروفه. ونقل الحافظ ابن الجوزي عن الإمام أحمد نحو ذلك في كتابه ((دفع شبه التشبيه)) وأنت خبير بأن نفى الجسمية نفى للجهة والمكان فإنهما لا زمان لها لذاتها لزوما مساويا، وإذا ثبت اللازم المساوي ثبت ملزومه. لا يشك في ذلك من يعرف معنى اللازم المساوي، فهو بمنزلة الحدوث للإمكان والانقسام بمتساويين للزوج.\r(فصل في نقول مهمة عن أكابر السلف تجلى لك الأمر)\r"]], "pg": [62, 67]}, "526.20": {"x": [[67, "فمنهم الإمام أبو جعفر محمد بن جرير الطبري المتوفى سنة تسع وثلاثمائة، تصرح عبارته في الجزء الأول من تاريخه بأن الجسمية تستلزم الحدوث، وأن خالق المخلوقات يتعالى عنها. وننقل لك هنا عبارته وإن خرج بعضها عن غرض هذا الفصل لحسنها ونفاستها. قال رضي الله عنه ما نصه: (القول في الدلالة على أن الله عز وجل هو القديم الأول قبل كل شيء وأنه هو المحدث كل شيء بقدرته تعالى ذكره) فمن الدلالة على ذلك أنه لا شيء في العالم مشاهد إلا جسم أو قائم بجسم وأنه لا جسم إلا مفترق أو مجتمع، وأنه لا مفترق منه إلا وهو موهوم فيه الاجتماع والاتلاف إلى غيره من أشكاله، ولا مجتمع منه إلا وهو موهوم فيه الافتراق، وأنه متى عدم أحدهما عدم الآخر معه، وأنه إذا اجتمع الجزء ان منه بعد الافتراق فمعلوم أن اجتماعهما حادث فيهما بعد أن لم يكن، وأن الافتراق إذا حدث فيهما بعد الاجتماع فمعلوم أن الافتراق فيهما حادث بعد أن لم يكن، وإذا كان الأمر فيما في العالم من شيء كذلك، وكان حكم ما لم يشاهد وما هو من جنس"], [68, "وتغاير أصنافها فقال سبحانه {فَلَا أُقْسِمُ بِالْخُنَّسِ (15) الْجَوَارِ الْكُنَّسِ} [التكوير: 15، 16] أي الكواكب المتحركة في أفلاكها على أبدع نظام. ولفت العباد إلى رجوعها إليهم بعد المغيب وجريها في أفلاكها إلى أن تغيب عن العيون، يقال خنس الكوكب إذا رجع وكنس إذا استتر، وإنما أقسم بها تنوبها لعباده بشأنها من جهة ما فيها من الحركة الدالة على حدوثها وإمكانها، فإن الحركة ليست لها لذاتها، فلا بد لها إذا من واجب قهرها على ما أراد، وخص بالذكر خنوسها وكنوسها لأنهما أظهر عند الكل في إبعادها عما ادعاه لها الجاهلون من مرتبة الألوهية، وإقام الله تعالى ببعض خلقه هو ضرب من ضروب الاستدلال البديع الذي يسلكه القرآن كقوله {وَالذَّارِيَاتِ ذَرْوًا (1) فَالْحَامِلَاتِ وِقْرًا} [الذاريات: 1، 2] إلى قوله {إِنَّمَا تُوعَدُونَ لَصَادِقٌ} [الذاريات: 5] ولفت للانظار إلى ما في تلك المخلوقات من العبر والدلائل على الحدوث. وقال تعالى {وَاللَّهُ خَلَقَ كُلَّ دَابَّةٍ مِنْ مَاءٍ فَمِنْهُمْ مَنْ يَمْشِي عَلَى بَطْنِهِ وَمِنْهُمْ مَنْ يَمْشِي عَلَى رِجْلَيْنِ وَمِنْهُمْ مَنْ يَمْشِي عَلَى أَرْبَعٍ يَخْلُقُ اللَّهُ مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ} [النور: 45] فهذا تصريح بأن الحركات والأجزاء من قسم الممكنات، والواجب يتعالى عنه، وكذلك قال {وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ} [غافر: 64] وقال {هُوَ الَّذِي يُصَوِّرُكُمْ فِي الْأَرْحَامِ كَيْفَ يَشَاءُ} [آل عمران: 6] وذلك صريح في حدوث الصور المادية وإمكانها، وما كان من باب الإمكان فالاتصاف به مستحيل على الرحمن.\rوقد اتفقت عقول المحققين من الأولين والآخرين والسلف والخلف على أن ما اتصف بصغر أو كبر فهو حادث ممكن، وكذلك اتفقت على أن الصورة والاتصاف بالأجزاء من سمات الحدوث، ولم نر أحدا احترأ على إنكار ذلك وبالغ فيه سوى ابن تيمية، وهو قول إن دل على شيء فليس يدل إلا على إصابة صاحبه بهوى خرج به عن المعقول والمنقول. واستمع إلى ما نقله الحافظ البيهقي عن الإمام أحمد الذي ينسب إليه هذا الرجل ومن على شاكلته كل شنيعة، في الكتاب الذي ألفه في مناقب الإمام أحمد عن الإمام أبي الفضل التميمي، رئيس "], [69, "ما شاهدنا في معنى جسم أو قائم بجسم، وكان ما لم يخل من المحدث لا شك أنه محدث بتأليف مؤلف له، إن كان مجتمعا، وتفريق مفرق له إن كان مفترقا، وكان معلوما بذلك أن جامع ذلك إن كان مجتمعا، ومفرقه إن كان مفترقا، من لا يشبهه ولا يجوز عليه الاجتماع والافتراق، وهو الواحد القادر الجامع بين المختلفات، الذي لا يشبهه شيء وهو على كل شيء قدير. فتبين بما وصفنا أن بارئ الأشياء ومحدثها كان قبل كل شيء، وأن الليل والنهار والزمان والساعات محدثات، وأن محدثها الذي يدبرها ويصرفها قبلها أن كان من المحال أن يكون شيء يحدث شيئا إلا ومحدثه قبله. وإن في قوله تعالى ذكره {أَفَلَا يَنْظُرُونَ إِلَى الْإِبِلِ كَيْفَ خُلِقَتْ (17) وَإِلَى السَّمَاءِ كَيْفَ رُفِعَتْ (18) وَإِلَى الْجِبَالِ كَيْفَ نُصِبَتْ (19) وَإِلَى الْأَرْضِ كَيْفَ سُطِحَتْ} [الغاشية: 17 - 20] لأبلغ الحجج، ودل الدلائل لمن فكر بعقل واعتبر بفهم على قدم بارئها وحدوثها. وكل ما جانسها؛ وأن لها خالقا لا يشبهها، وذلك أن كل ما ذكر ربنا تبارك وتعالى في هذه الآيات من الجبال والأرض والإبل فان ابن آدم يعالجه ويدبره بتحويل وتصريف، وحفر ونحت وهدم، غير ممتنع عليه شيء من ذلك، ثم إن ابن آدم مع ذلك غير قادر على إيجاد شيء من ذلك من غير أصل. فمعلوم أن العاجز عن إيجاد ذلك لم يحدث نفسه، وأن الذي هو غير ممتنع ممن أراد تصريفه وتقليبه لم يوجده من هو مثله، ولا هو أوجد نفسه، وأن الذي أنشأه وأوجد عينه هو الذي لا يعجزه شيء أراده، ولا يمتنع عليه إحداث شيء شاء إحداثه. وهو الله الواحد القهار. فإن قال قائل فما تنكر أن تكون الأشياء التي ذكرت من فعل قديمين؟ قيل أنكرنا ذلك لوجودنا اتصال التدبير وتمام الخلق، فقلنا لو كان المدبر اثنين لم يخل من اتفاق أو اختلاف، فإن كانا متفقين فمعناهما واحد، وإنما جعل الواحد اثنين من قال بالاثنين. وإن كانا مختلفين كان محالا وجود الخلق على التمام والتدبير على الاتصال، لأن المختلفين فعل كل واحد منهما خلاف فعل صاحبه، بأن أحدهما إذا أحيى أمات الآخر، وإذا أوجد أحدهما "], [70, "أفنى الآخر، فكان محالا وجود شيء من الخلق على ما وجد عليه من التمام والاتصال. وفي قول الله عز وجل ذكره {وْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللَّهُ لَفَسَدَتَا فَسُبْحَانَ اللَّهِ رَبِّ الْعَرْشِ عَمَّا يَصِفُونَ} [الأنبياء: 22] وقوله عز وجل {مَا اتَّخَذَ اللَّهُ مِنْ وَلَدٍ وَمَا كَانَ مَعَهُ مِنْ إِلَهٍ إِذًا لَذَهَبَ كُلُّ إِلَهٍ بِمَا خَلَقَ وَلَعَلَا بَعْضُهُمْ عَلَى بَعْضٍ سُبْحَانَ اللَّهِ عَمَّا يَصِفُونَ (91) عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَتَعَالَى عَمَّا يُشْرِكُونَ} [المؤمنون: 91، 92] أبلغ حجة وأوجز بيان وأدل دليل على بطول ما قال المبطلون من أهل الشرك بالله، وذلك أن السموات والأرض لو كان فيهما آلهة غير الله لم يخل أمرهما مما وصفت من اتفاق واختلاف وفي القول باتفاقهما فساد القول بالتثنية، وإقرار بالتوحيد، وإحالة في الكلام بأن قائله سمى الواحد اثنين. وفي القول باختلافهما القول بفساد السموات والأرض كما قال ربنا عز وجل {لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللَّهُ لَفَسَدَتَا} [الأنبياء: 22] لأن أحدهما كان إذا أحدث شيئا وخلقه كان من شأن الآخر إعدامه وإبطاله. وذلك أن كل مختلفين فأفعالهما مختلفة، كالنار التي تسخن والثلج الذي يبرد ما أسخنته النار: وأخرى أن ذلك لو كان كما قال المشركون بالله لم يخل كل واحد من الاثنين اللذين أثبتوهما قديمين من أن يكونا قويين أو عاجزين، فإن كانا عاجزين فالعاجز مقهور وغير كائن إلها، وإن كانا قويين فإن كل واحد منهما بعجزه عن صاحبه عاجز، والعاجز لا يكون إلها، فإن كان كل واحد منهما قويا على صاحبه فهو بقوة صاحبه عليه عاجز، تعالى ذكره عما يشرك المشركون. فتبين إذا أن القديم بارئ الأشياء وصانعها هو الواحد الذي كان قبل كل شيء، وهو الكائن بعد كل شيء، والأول قبل كل شيء، والآخر بعد كل شيء، وأنه كان ولا وقت ولا زمان ولا ليل ولا نهار، ولا ظلمة ولا نور إلا نور وجهه الكريم، ولا سماء ولا أرض، ولا شمس ولا قمر ولا نجوم، وأن كل شيء سواه محدث مدبر مصنوع انفرد بخلق جميعه بغيره شريك ولا معين، ولا ظهير، سبحانه من قادر قاهر)) انتهى.\rوهو كما ترى صريح فيما قلنا لمن تأمله، وهذا إمام العارفين الثقة الحجة أبو "], [71, "القاسم القشيري ينقل في كتابه الرسالة عن جعفر الصادق الإمام الأجل وعن أكابر المتقدمين من العلماء العاملين، والصوفية الواصلين، أهل المكاشفات الصادقة، قولهم بنفي الجهة والمكان والجسمية وسائر ما يستلزمها أو تستلزمه عن الحق العلى تبارك وتعالى، لأن ذلك كله من سمات الحدوث، وخصائص الممكنات.\r(زيادة تبصير وتنوير)\r"]], "pg": [67, 71]}, "526.21": {"x": [[71, "وأنت إذا أنعمت التفقه فيما احتج به الله في كتابه المبين، وحكاه فيه عن المرسلين إجمالا وتفصيلا، وجدت ذلك لائحا واضحا. فانظر إلى قوله في أم القرآن (رب العالمين) أي موجد كل ما سواه، ومدرجه في الكمال شيئا بعد شيء، كيف عبر عن هذه الأشياء بكلمة العالمين، وهي جمع عالم، وهو في هذه اللغة الفصحى التي اختارها الله لهذا الكتاب المبين: ما به يعلم غيره وجعلت فيه العلامة ونصب دليلا عليه. فكأنه يقول سبحانه: لي الثناء الجميل لا يستحقه سواي لأني أنا المنعم على كل شيء مما ترون وما لا ترون بوجوده وسائر كمالاته وقد جعلت فيه العلامات والدلائل على حدوثه وقدمي وفنائه وبقائي، واحتياجه وإمكانه وغناي ووجوب وجودي وكمال جودي. وهذه الأمارات فيه ظاهرة بحيث تصلح للاحتجاج بها على جميع العقلاء إذا نظروا منصفين. وفكروا غير معاندين. وما هذه الآيات البينات التي يكون الكل سواء في تعرفها إلا جعل كل شيء منها على قدر مخصوص، وحد معين في حجمه وأجزائه، وشكله ولونه ومكانه وزمانه وأوصافه التابعة لذلك، فكل ذلك شهود منها عليها للناظرين بأنها حادثة ممكنة بأحداث واحد حكيم، ومقدرة بتقدير العزيز العليم، ومفاض عليها الخير من الجواد الكريم، وكذلك قال تعالى {الْحَمْدُ لِلَّهِ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَجَعَلَ الظُّلُمَاتِ وَالنُّورَ} [الأنعام: 1] فقد جعلت الآية الكريمة كون السموات والأرض والظلمات والنور من المحدثات المجعولات مما لا يخفى على من نظر فيه "], [72, "ولذلك لم تمن ببيانه وإنما عنيت ببيان أن الخالق له هو الله وحده، وأن الكافرين المعاندين يعدلون به غيره، أي يجعلونه مساويا له في بعض الصفات التي لا تنبغي إلا له عز وجل، ولذلك عقب الجملة السابقة بقوله سبحانه {ثُمَّ الَّذِينَ كَفَرُوا بِرَبِّهِمْ يَعْدِلُونَ} [الأنعام: 1] وعلى هذا المنوال قوله تعالى لرسوله {قُلْ أَغَيْرَ اللَّهِ أَتَّخِذُ وَلِيًّا فَاطِرِ السَّمَاوَاتِ وَالْأَرْضِ} [الأنعام: 14] والولي هنا بمعنى المعبود، وقول الخليل عليه الصلاة والسلام {إنِّي وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَاوَاتِ وَالْأَرْضَ} [الأنعام: 79] وهو منه عليه الصلاة والسلام إشارة واضحة إلى أن ما في هذه العوالم من الجسمية والتركب من الأجزاء واختلاف المقادير والأمكنة قاض عليها بأنها مفطورة مخلوقة عاجزة مستفيدة وجودها وتوابعه، وشاهد لفاطرها ومبدعها بالوحدانية في وجوب الوجود وكمال الجود على كل موجود، ومن هذا القبيل قول الكليم عليه السلام لفرعون والملأ حوله حين تعنت فقال {وَمَا رَبُّ الْعَالَمِينَ (23) قَالَ رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِنْ كُنْتُمْ مُوقِنِينَ} [الشعراء: 23، 24] وإنما عددناه متعنتا لأن في قوله وأخيه عليهما السلام إنا رسول رب العالمين الحجة الكافية والبرهان الشافي، فإن معناه إنا رسول رب هذه الأشياء التي جعلت فيها العلامات الظاهرة والسمات الواضحة، والدلالات البينة على نقصها وعجزها وحدوثها وفاقتها وشدة افتقارها في وجودها وما يتبعه إلى رب توحد في ملكوته وتقدس عن مشابهتها في سمات الحدوث ودلائل العجز، فلا يكون جسما ولا جسمانيا، ومن ذلك النحو قوله عليه السلام حين قال فرعون من ربكما يا موسى {رَبُّنَا الَّذِي أَعْطَى كُلَّ شَيْءٍ خَلْقَهُ ثُمَّ هَدَى} [طه: 50] وقول الرسل للمشركين (أفي الله شك فاطر السموات والأرض) أفلا يكون كل هذا وهو بعض ما في الكتاب العزيز في هذا الموضوع قرائن مانعة من حمل ما ورد في الكتاب والسنة من الوجه ونحوه والعلو والنزول وشبههما على المعاني الحسية الجسمانية، وصارفة له إلى ما يليق بذاته سبحانه مما يتعالى عن مشابهة الأجسام والجسمانيات، ومنادية بأعلى صوت على من حملها على الظواهر الحسية التي تتبادر للجاهلين من العامة بقلة تفقهه في كتاب الله "], [73, "وانحرافه عن الجادة التي سلكها علماء المعقول والفقهاء في المنقول\rبلى والذي أنزل في كتابه العلم وخص العلماء المرضيين لديه بالفهم جل ثناؤه، وهكذا اتفق سلف هذه الأمة الصالح وخلفها الموفق على صرف هذه المتشابهات عن هذه الظواهر المادية، لا خلاف في ذلك بين أوائلهم وأواخرهم رضي الله عنهم، وسموا من فسرها بتلك الظواهر بالمجسمة والحشوية إيماء منهم رضي الله عنهم إلى أن ما أتى به هؤلاء من التفسير من اللغو الذي لا يلتفت إليه، والحشو الذي لا يعول أهل العلم بالكتاب والسنة عليه، وسنلم بهذا الموضوع في الفصل الأخير من هذا المقصد إن شاء الله تعالى فانتظر\r(تتمة تشمل على نص سؤال الى شيخ الإسلام سليم البشري في رجل يعتقد الفوقية المحدودة)\r"]], "pg": [71, 73]}, "526.22": {"x": [[73, "ونختم هذا الفصل بذكر فتوى في هذا الموضوع صدرت من شيخ الإسلام بحق ورأس المحققين الاعلام أستاذ الأساتذة الشيخ سليم البشري تغمده الله برحمته وأعلى في الفراديس درجاته. ونص السؤال والجواب نقلا عن كتاب شمس الحقيقة والهداية في الفراديس درجاته. ونص السؤال والجواب نقلا عن كتاب شمس الحقيقة والهداية في الرد على أهل الضلالة والغواية: للعلامة المحقق والنقي الموفق الشيخ أحمد بن العلامة الكبير الشيخ علي بدر شيخ معهد بلصفورة وهو رافع السؤال إلى شيخ الإسلام رضي الله عنهما. قال: ((ما قولكم دام فضلكم في رجل من أهل العلم هنا الذين يوصفون بالتفقه في الدين تظاهر باعتقاد ثبوت جهة الفوقية لله سبحانه وتعالى، ويدعى أن ذلك مذهب السلف، وتبعه على ذلك البعض القليل من الناس، وجمهور أهل العلم ينكرون عليه. والسبب في تظاهره بهذا المعتقد ــ كما عرض على هو بنفسه ذلك ــ عثوره على كتاب لبعض علماء الهند نقل فيه صاحبه كلاما كثيرا عن ابن تيمية في إثبات الجهة للباري سبحانه وتعالى، وليكن معلوما أنه يعتقد الفوقية الذاتية له جل ذكره، يعني أن ذاته سبحانه فوق العرش ــ يعني ما قابل التحت ــ مع التنزيه، ويخطئ أبا البركات الدردير رضي "], [74, "الله عنه في قوله في خريدته\rمنزه عن الحلول والجهة. والاتصال الانفصال والسفه\rيخطئه في موضعين من البيت قوله والجهة وقوله والانفصال. والشيخ اللقاني في قوله\rويستحيل ضد ذي الصفات. في حقه كالكون في الجهات\rوبالجملة هو مخطئ لكل من يقول بنفي الجهة مهما كان قدره، ويستدل أيضا بنص كتاب آخر غير الكتاب المتقدم ذكره، وهو تفسير الشيخ الالوسي المسمى بروح المعاني، عند قوله تعالى {وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ} [الأنعام: 18] مع أن المطلع على عبارة الآلوسى يجده في آخر عبارته ذكر ما يؤخذ منه أنه غير جازم بذلك. ويستدل على ذلك بمثل قوله تعالى {وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ} [الأنعام: 18] {يَخَافُونَ رَبَّهُمْ مِنْ فَوْقِهِمْ} [النحل: 50] {إِلَيْهِ يَصْعَدُ الْكَلِمُ الطَّيِّبُ} [فاطر: 10] وبقوله صلى الله عليه وسلم للجارية التي أراد سيدها عتقها ((أين الله؟ فقالت في السماء)) مع ما هو معلوم لفضيلتكم من أنها كانت خرساء وأشارت إلى السماء كما هو منصوص في بعض مؤلفات حجة الإسلام الغزالي رضي الله عنه، وقد تعرض لذلك السيد محمد مرتضى في شرحه للأحياء. ويستدل أيضا بقوله صلى الله عليه وسلم في حجة الوداع ((اللهم اشهد)) وأشار بأصبعه إلى السماء، ويورد على من ينازعه في ذلك سؤال الكرامية المشهور وهو قولهم إن نفيه عن الجهات الست إخبار عن عدمه. ولا يخفى على فضيلتكم أن الكلام في مسألة الجهة شهير، إلا أنه من المعلوم أن قول فضيلتكم سيما في مثل هذا الأمر هو الفصل، وأرجو أن يكون عليه إمضاؤكم بخطكم والختم ولا مؤاخذة، لازلتم محفوظين والمذهب أهل السنة والجماعة ناصرين آمين)). وقوله الكرامية: نسبة إلى محمد بن كرام. كشداد كما في القاموس\rوهذا نص جوابه حفظه الله: إلى حضرة الفاضل العلامة الشيخ أحمد علي بدر خادم العلم الشريف ببلصفورة: "], [75, "قد أوسلتم بتاريخ 22 محرم سن 1325 هـ مكتوبا مصحوبا بسؤال عن حكم من يعتقد ثبوت الجهة له تعالى، فحررنا لكم الجواب الآتي وفيه الكفاية لمن اتبع الحق وأنصف، جزاكم الله عن المسلمين خيرا ((اعلم أيدك الله بتوفيقه رسلك بنا وبك سواء طريقه، أن مذهب الفرقة الناجية وما عليه أجمع السنيون أن الله تعالى منزه عن مشابهة الحوادث مخالف لها في جميع سمات الحدوث ومن ذلك تنزهه عن الجهة والمكان كما دلت على ذلك البراهين القطعية، فان كونه في جهة يستلزم قدم الجهة أو المكان وهما من العالم، وهو ما سوى الله تعالى وقد قام البرهان القاطع على حدوث كل ما سوى الله تعالى بأجماع من أثبت الجهة ومن نفاها، ولأن المتمكن يستحيل وجود ذاته بدون المكان مع أن المكان يمكن وجوده بدون المتمكن لجواز الخلاء، فيلزم إمكان الواجب وجوب الممكن وكلاهما باطل، ولأنه لو تحيز لمكان جوهرا لاستحالة كونه عرضا، ولو كان جوهرا فاما أن ينقسم وإما أن لا ينقسم، وكلاهما باطل، فان غير المنقسم هو الجزء الذي لا يتجزأ وهو أحقر الأشياء، تعالى الله عن ذلك علوا كبيرا. والمنقسم جسم وهو مركب والتركيب ينافي الوجوب الذاتي، فيكون المركب ممكنا يحتاج إلى علة مؤثرة، وقد ثبت بالبرهان القاطع أنه تعالى واجب الوجود لذاته، غنى عن كل ما سواه، مفتقر إليه كل ما عداه، سبحانه ليس كمثله شيء وهو السميع البصير ....... هذا وقد خذل الله أقواما أغواهم الشيطان وأزلهم اتبعوا أهواءهم وتمسكوا بما لا يجدي فاعتقدوا ثبوت الجهة تعالى الله عن ذلك علوا كبيرا، واتفقوا على أنها جهة فوق إلا أنهم افترقوا فمنهم من اعتقد أنه جسم مماس للسطح الأعلى من العرش وبه قال الكرامية واليهود، وهؤلاء لا نزاع في كفرهم، ومنهم من أثبت الجهة مع التنزيه، وأن كونه فيها ليس ككون الأجسام وهؤلاء ضلال فساق في عقيدتهم، وإطلاقهم على الله ما لم يأذن به الشارع، ولا مرية أن فاسق العقيدة أقبح وأشنع من فاسق الجارحة بكثير سيما من كان داعية أو مقتدى به. وممن نسب إليه القول "], [76, "بالجهة من المتأخرين أحمد بن عبد الحليم بن عبد السلام بن تيمية الحراني الحنبلي الدمشقي من علماء القرن الثامن، في ضمن أمور نسبت إليه خالف الأجماع فيها عملا برأيه وشنع عليه معاصروه بل البعض منهم كفروه، ولقى من الذل والهوان ما لقي، وقد انتدب بعض تلامذته للذب عنه وتبرئته مما نسب إليه وساق له عبارات أوضح معناها، وأبان غلط الناس في فهم مراده، واستشهد بعبارات له أخرى صريحة في دفع التهمة عنه، وأنه لم يخرج عما عليه الأجماع، وذلك هو المظنون بالرجل لجلالة قدره ورسوخ قدمه، وما تمسك به المخالفون القائلون بالجهة أمور واهية وهمية، لا تصلح أدلة عقلية ولا نقلية، قد أبطلها العلماء بما لا مزيد عليه، وما تمسكوا به ظواهر آيات وأحاديث موهمة كقوله تعالى {الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى} [طه: 5] وقوله {إِلَيْهِ يَصْعَدُ الْكَلِمُ الطَّيِّبُ} [فاطر: 10] وقوله {تَعْرُجُ الْمَلَائِكَةُ وَالرُّوحُ إِلَيْهِ} [المعارج: 4] وقوله {أَأَمِنْتُمْ مَنْ فِي السَّمَاءِ أَنْ يَخْسِفَ بِكُمُ الْأَرْضَ} [الملك: 16] وقوله {وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِه} [الأنعام: 18] وكحيث ((إنه تعالى ينزل إلى سماء الدنيا كل ليلة)) وفي رواية ((في كل ليلة جمعة فيقول هل من تائب فأتوب عليه؟ هل من مستغفر فأغفر له؟)) وكقوله للجارية الخرساء ((أين الله فأشارت إلى السماء)) حيث سأل بأين التي للمكان ولم ينكر عليها الإشارة إلى السماء، بل قال إنها مؤمنة ومثل هذه يجاب عنها بأنها ظواهر ظنية لا تعارض الأدلة القطعية اليقينية الدالة على انتفاء المكان والجهة، فيجب تأويلها وحملها على محامل صحيحة لا تأباها الدلائل والنصوص الشرعية، إما تأويلا إجماليا بلا تعيين للمراد منها كما هو مذهب السلف، وإما تأويلا تفصيليا بتعيين محاملها وما يراد منها كما هو رأى الخلف، كقولهم إن الاستواء بمعنى الاستيلاء كما في قول القائل:\rقد استوى بشر على العراق. من غير سيف ودم مهراق\rوصعود الكلم الطيب إليه قبوله إياه ورضاه به، لأن الكلم عرض يستحيل صعوده، وقوله: من في السماء: أي أمره وسلطانه أو ملك من ملائكته موكل "], [77, "بالعذاب. وعروج الملائكة والروح إليه صعودهم إلى مكان يتقرب إليه فيه. وقوله: فوق عباده أي بالقدرة والغلبة فإن كل من قهر غيره وغلبه فهو فوقه أي عال عليه بالقهر والغلبة، كما يقال أمر فلان فوق أمر فلان، أي أنه أقدر منه وأغلب. ونزوله إلى السماء محمول على لطفه ورحمته وعدم المعاملة بما يستدعيه علو رتبته وعظم شأنه على سبيل التمثيل، وخص الليل لأنه مظنة الخلوة والخضوع وحضور القلب. وسؤاله للجارية (بأين) استكشاف لما يظن بها اعتقاده من أينية المعبود كما يعتقده الوثنيون، فلما أشارت إلى السماء فهم أنها أرادت خالق السماء فاستبان أنها ليست وثنية، وحكم بأيمانها. وقد بسط العلماء في مطولاتهم تأويل كل ما ورد من أمثال ذلك، عملا بالقطعي وحملا للظني عليه، فجزاهم الله عن الدين وأهله خير الجزاء. ومن العجيب أن يدع مسلم قول جماعة المسلمين وأئمتهم ويتمشدق بترهات المبتدعين وضلالتهم. أما سمع قول الله تعالى {وَيَتَّبِعْ غَيْرَ سَبِيلِ الْمُؤْمِنِينَ نُوَلِّهِ مَا تَوَلَّى وَنُصْلِهِ جَهَنَّمَ وَسَاءَتْ مَصِيرًا} [النساء: 115] فليتب إلى الله تعالى من تلطخ بشيء من هذه القاذورات ولا يتبع خطوات الشيطان فإنه يأمر بالفحشاء والمنكر، ولا يحملنه العناد على التمادي والأصرار عليه فإن الرجوع إلى الصواب عين الصواب والتمادي على الباطل يفضى إلى أشد العذاب {مَنْ يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَنْ يُضْلِلْ فَلَنْ تَجِدَ لَهُ وَلِيًّا مُرْشِدًا} [الكهف: 17] نسأل الله تعالى أن يهدينا جميعا سواء السبيل وهو حسبنا ونعم الوكيل، وصلى الله تعالى وسلم على سيدنا محمد وصحبه أجمعين ومن تبعهم بإحسان إلى يوم الدين.\rأملاه الفقير إليه سبحانه (سليم البشرى) خادم العلم والسادة المالكية بالأزهر عفى عنه آمين آمين.\rوقول الشيخ رضي الله عنه ((وذلك هو المظنون بالرجل لجلالة قدره ورسوخ قدمه)) هو حسن ظن من الشيخ حمله عليه قول هذا التلميذ: والذي يطيل النظر في كتبه وكتب تلميذه ابن القيم ــ كما فعلنا نحن ــ لا يرتاب في قوله بالتجسيم والجهة "], [78, "والتشبيه ولكنه يتبرأ من اسمه)) ويقول بالتنزيه لكنه إنما يقول بلفظه ويتباعد عن القول بمعناه. وليس أحد أعرف بهذا الرجل من علماء عصره، ولا سيما الورع الحجة المحقق الإمام شيخ الإسلام التقي علي بن عبد الكافي وقد كان له معاصرا ورد عليه في حياته وبعد وفاته بعدة مصنفات. ودونك عبارة شيخ الإسلام التقي في هذا المبتدع الغوى في خطبة كتابه ((الدرة المضية في الرد على ابن تيمية)) في قوله بعدم وقوع الطلاق المعلق على وجه اليمين، وأنه خرق الإجماع بهذا القول، وكذب على الصحابة والتابعين ومن بعدهم. قال رفع الله درجته في المهديين ما لفظه ((أما بعد فإنه لما أحدث ابن تيمية ما أحدث في أصول العقائد، ونقض من دعائم الإسلام الأركان والمعاقد، بعد أن كان مستترا بتبعية الكتاب والسنة، مظهرا أنه داع إلى الحق هاد إلى الجنة، فخرج عن الاتباع إلى الابتداع وشذ عن جماعة المسلمين بمخالفة الاجماع. وقال بما يقتضي الجسمية والتركيب في الذات المقدسة، وأن الافتقار إلى الجزء ليس بمحال، وقال بحلول الحوادث بذات الله تعالى، وأن القرآن محدث تكلم الله به بعد أن لم يكن، وأنه يتكلم ويسكت، ويحدث في ذاته الارادات بحسب المخلوقات، وتعدى في ذلك إلى استلزام قدم العالم، والتزمه بالقول بأنه لا أول للمخلوقات فقال بحوادث لا أول لها، فأثبت الصفة القديمة حادثة، والمخلوق الحادث قديما، ولم يجمع أحد هذين القولين في ملة من الملل، ولا نحلة من النحل، فلم يدخل في فرقة من الفرق الثلاثة والسبعين التي افترقت عليها الأمة، ولا وقفت به مع أمة من الأمم همة. وكل ذلك وإن كان كفرا شنيعا مما تقل جملته بالنسبة إلى ما أحدث في الفروع)) اهـ وهي رسالة نفيسة أجاد فيها رضي الله عنه الرد عليه وبيان الحق في المسألة وقد طبعت بدمشق. وفي التحقيق الدقيق الذي قام به العلامة الكوثري في كتابه تكملة الرد على نونية ابن القيم المطبوع مع السيف الصقيل ما يغنينا عن الإطالة في شرح حال هذا الرجل وشيعته. أجارنا الله وسائر المسلمين من اتباع الهوى، "], [79, "وثبتنا على الهدى بجاه نبيه نبي الرحمة عليه وعلى آله أفضل الصلوات وأنمى البركات.\r(فصل في أن صفات المحدثات على قسمين)\r"]], "pg": [73, 79]}, "526.23": {"x": [[79, "ومجمل القول في هذا الباب أن صفات المحدثات على قسمين: القسم الأول ما يدل على الحدوث والإمكان والافتقار والاحتياج من حيث ذاته وماهيته أو ملزوماته أو لوازمه المساوية كالكون في الجهة والمكان، وكالصغر والكبر والجسمية وقبول الانقسام. فهذا مختص بالكائنات لا يجوز أن يتصف الخالق منه بشيء ثم منه ما يكون القول به في الله كفرا إجماعا، ككونه والدا أو مولودا أو ذا صاحبة أو له شريك ونحو ذلك من كل ما النقص فيه ظاهر جلي، ومنه ما اختلف في كفر القائل به ككونه تعالى في جهة الفوق ينزل ويصعد، إلى أشباه هذا مما يحتاج إلى فضل تأمل: على أقوال ليس هذا محل بسطها، أرجحها أن ذلك ضلال وبدعة وفسق شنيع، أشد من فسق الجوارح بكثير، وقد يعذر العامي في الجهل ببعض ذلك، وأما من ارتفعت درجته عن العامية فلا يعذر وإنما يعزر، فإن كان داعية إلى رأيه كان الذنب أعظم والأمر أخطر ــ عياذا بالله من ذلك ــ والقسم الثاني: ما لا يدل على ما سبق من حيث ذاته بل من حيث نقصه عن الدرجة العليا في كماله كالوجود والحياة والعلم والإرادة والقدرة وأشباهها من كل صفة هي من حيث ذاتها كمال. فهذا القسم هو للحق تعالى بالأصالة على أكمل درجاته وأبعدها عن شوب النقص، وأرفعها عن الإمكان ولوازمه، واجب بوجوب موصوفه تبارك وتعالى قديم بقدمه باق ببقائه، أما ما للخلق منه فهو له بالعرض حادث فيه بإحداث الحق ممكن غير واجب، على درجة نازلة لائقة بحال الممكن، بحيث لا نسبة بين ما اتصف به الممكن منه وما اتصف به الحق جل وعز، وأين وجود ممكن حادث قابل للزوال غير مملوك للمتصف به حين اتصافه به من الوجود الواجب الأزلي الأبدي الذي يجل عن الابتداء والانتهاء، ويرتفع عن قبول الانتفاء؟ وأين ما للكائنات من العلم الحادث المخلوق القليل الضئيل من علم الحق الواجب المحيط "], [80, "الأكمل؟ وهكذا سائر الصفات التي هي من هذا القسم فانتفت المشابهة بين وجودنا ووجوه، وحيتنا حياته، وعلمنا وعلمه، إلى سائر هذا النحو من هذه الصفات، وكذلك قال المحققون: إنه لا مشابهة بين هذا النوع من الصفات للممكن وبين الكمالات التي للغني الحميد الواجب ذاتا وصفات، إلا في مجرد الاسم ولا اشتراك إلا في اللفظ فقط. وبهذا يبين لك معنى قوله تعالى في صفة ذاته العلية وكمالاته المقدسة {لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ} [الشورى: 11] (هو الحى) {وَهُوَ اللَّطِيفُ الْخَبِيرُ} [الأنعام: 103] {إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ} [الأنفال: 61] {وَهُوَ الْعَلِيمُ الْقَدِيرُ} [الروم: 54] {لَا يَعْلَمُ مَنْ فِي السَّمَاوَاتِ وَالْأَرْضِ الْغَيْبَ إِلَّا اللَّهُ} [النمل: 65] إلى أمثال هذه الآيات الشريفة من كل ما دل على انحصار هذه الصفات فيه عز وجل، وقصرها عليه. ولبعد ما بين حقائق هذه الصفات في الممكن وحقيقتها في الواجب، قال بعض الفضلاء إن إطلاق الوجود والحياة والعلم ونحوها على ما للممكن ما هو إلا بالمجاز.\r{مطلب في بيان وحدة الوجود}\r"]], "pg": [79, 80]}, "526.24": {"x": [[80, "ولذلك أيضا قال كثير من صفوة العارفين بوحدة الوجود، والكمالات الراجعة إلى جهات الوجود، كالحياة والعلم، لا على المعنى الذي تفهمه الزنادقة، ويدعو إليه الإباحيون، بل على معنى أن وجود الممكن وحياته وعلمه إلى آخره، بالإضافة إلى وجود الحق وحياته وعلمه، وسائر كمالاته يكاد يبلغ حد العدم. والتعريج في تفسير الوحدة على غير هذا دخول في مسالك ضيقة، وسلوك في مضايق تفضي إلى أخطار تحل من أصيب بها دار البوار، نسأل الله السلام. وأرجو بعد هذا البيان لهذين القسمين أن تكون قد تكشفت لك تلك المغالطة التي كثيرا ما توجد في كتب الحشوية، ويفوه بها بعضهم الآن في مناظرة أهل السنة، وأن يكون قد افتضح لك أمرها وبان عوارها، وهو قولهم إن الوجه والعينين واليدين والقدمين والساق صفات كما أن الحياة والعلم والإرادة والقدرة صفات، وقد"], [81, "قلتم بها في ذات الله، فلماذا لا تقولون بتلك الصفات الوجه وما ذكر معه؟ {أَفَتُؤْمِنُونَ بِبَعْضِ الْكِتَابِ وَتَكْفُرُونَ بِبَعْضٍ} [البقرة: 85]؟ فكما قلتم له علم لا كالعلوم، وقدرة لا كالقدر، فقولوا له وجه لا كالوجوه، ويد لا كالأيدي، ورجل لا كالأرجل وساق لا كالسوق، ويتوسعون في ترويج هذا الكلام بما شاء لهم الهوى وأشربوا في قلوبهم من التجسيم والتشبيه، حتى انخدع بهذا الكلام من أهل الفضل من تروج عليه الحيل، ويغره الزخرف من القول، ويزيد في رواج هذا الزخرف أن هذه العبارة (له وجه لا كالوجوه) توجد من بعض الأكابر المنزهين للحق عن الأجزاء والجسمية كما هو الحق، وهي من الحشوية مغالطة مفضوحة وباطل مكشوف للناقد البصير، فإن الوجه والعين واليد والرجل والساق أجزاء وأبعاض وأعضاء لما هي فيه من الذوات، لا معان وأوصاف تقوم بموصوفاتها، فأين هي مما ألحقوها به من الحياة والعلم والإرادة والقدرة؟ وهل هذا إلا كتشبيه العالم بالعلم والأبيض بالبياض؟ وهل تسميتهم لها بالصفات إلا ستر لموقفهم من التشبيه بما لا يسترهم عن ذوي الأنظار النافذة. وتحجب عن سهام النقدة من أهل السنة الراسخين في علم الكتاب العزيز بنسج العنكبوت، وهو كما علمت لا ينفعهم ولا يدفع عنهم منها شيئا، فإن تهرب منهم متهرب ــ وكثيرا ما يفعلون ــ فقال: إنا لا نريد بالوجه وأخواته ما هو أجزاء وأبعاض، بل نريد ما هو صفات حقيقة كالعظمة والملك والبصر والقدرة ونحوها ولكنا لا نعين المراد، قلنا: مرحبا بالراجعين إلى الحق، وبشرى بالرجوع إلى صميم الإسلام ولب العلم، والسلفية الحقة، ولا نزاع بيننا وبينكم فقد انصرفتم عن الحشوية، ولكنهم والأسف مل فؤاد ناعليهم، على ذلك لا يثبتون، وما أسرع ما تراهم إلى القول بالتجزئة والتشبيه يرجعون، فنعوذ بالله تعالى من الفتن ما ظهر منها وما بطن.\r(تنبيه مهم: في بيان عبارات بعض السلف إنما نؤمن بأن له وجها لا كالوجوه)\r"]], "pg": [80, 81]}, "526.25": {"x": [[81, "إذا سمعت في عبارات بعض السلف إنما نؤمن بأن له وجها لا كالوجوه ويدا لا كالأيدي فلا تظن أنهم أرادوا أن ذاته العلية منقسمة إلى أجزاء وأبعاض. فجزء منها يد وجزء منها وجه غير أنه لا يشابه الأيدي والوجوه التي للخلق حاشاهم من ذلك، وما هذا إلا التشبيه بعينه، وإنما أرادوا بذلك أن لفظ الوجه واليد قد استعمل في معنى من المعاني، وصفة من الصفات التي تليق بالذات العلية كالعظمة والقدرة، غير أنهم يتورعون عن تعيين تلك الصفة تهيبا من التهجم على ذلك المقام الاقدس، وانهز المجسمة والمشبهة مثل هذه العبارة فغرروا بها العوام، وخدعوا بها الأغمار من الناس، وحملوها على الأجزاء فوقعوا في حقيقة التجسيم والتشبيه، وتبرؤوا من اسمه، وليس يخفى نقدهم المزيف على صيارفة العلماء، وجهابذة الحكماء، ويدلك على إرادة السلف ما قلنا ما نقله الذهبي نفسه في كتابه الذي سماه ((العلو)) عن الإمام مالك وشيخه ربيعة ونظرائهما قالوا حين سئلوا عن قوله تعالى {الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى} [طه: 5] كيف استوى؟ (والكيف غير معقول) وكذلك نقل الذهبي بالسند في هذا الكتاب عن أبي عبد الله الحاكم وأبي زرعة اتفاق جميع فقهاء الأمصار من أهل تلك الأعصار أنهم يؤمنون بهذه الصفات من غير كيف، فانظر كيف نفوا الكيف مجمعين وهو صريح في أنها ليست أجزاء ولا جسمانية فإن الاستواء الجسماني والوجه الجسماني وما إليه لا بد لها من الكيف قطعا، إذ هو لازم من لوازم ذاتها لذاتها، ونفى لازم الماهية لذاتها يستلزم نفيها عند جميع المنصفين من العقلاء الذين لم يصابوا بالأهواء وانظر كيف سموها صفات ولم يسموها أبعاضا وأجزاء.\rوالخلاعة أنه يندفع عنك أيها الطالب لمعرفة مذهب السلف الصالح الوهم بأمرين، إجماعهم على نفي الكيف، بل تصريحهم بأن الكيف غير معقول. والتسمية لها بالصفات، والعجب أن الذهبي ينقل ما هو حجة عليه، يظن أنه حجة له، وكذلك يفعل ابن تيمية على ذكائه ويزيد على ذلك كأسلافه نقل الطامات عن الأئمة بأسانيد فيها القائلون بالجسمية والدعاة إليها. وما أبدع "]], "pg": [81, 81]}, "526.26": {"x": [[82, "ما قال الإمام المحدث جمال الدين أبو الفرج عبد الرحمن بن الجوزي الحنبلي المتوفى سنة سبع وتسعين وخمسمائة في كتابه الذي صنفه في الرد على جهلة الحنابلة المسمى (دفع شبه التشبيه) حيث قال: ((وقد وقع غلط المصنفين الذين ذكرتهم في سبعة أوجه)) وعدها إلى أن قال ((والسابع أنهم حملوا الأحاديث على مقتضى الحس، فقالوا ينزل بذاته؛ وينتقل ويتحول، ثم قالوا لا كما يعقل فغالطوا من يسمع، وكابروا الحس والعقل، فحملوا الأحاديث على الحسيات فرأيت الرد عليهم لازما لئلا ينسب الإمام أحمد رحمه الله إلى ذلك)) اهـ والمصنفون الذين ذكرهم هم الحسن بن حامد وتلميذه أبو يعلى محمد المشهور بابن الفراء، وهو غير الحافظ أبي يعلى أحمد بن علي الموصلي صاحب المسند، وأبو الحسن علي الزاغوني وهو من شيوخ المصنف، وقد قال فيهم قبل ما نقلناه عنه بورقتين ((إنهم صنفوا كتبا شانوا بها المذهب)) ــ يعني مذهب الإمام أحمد ــ ورأيتهم قد نزلوا إلى مرتبة العوام فحملوا الصفات على مقتضى الحس)) إلى أن قال ((ثم إنهم يرضون العوام بقولهم لا كما يعقل)) إلى أن قال ((ولم يلتفتوا إلى النصوص الصارفة عن الظواهر إلى المعاني الواجبة لله تعالى)) الخ. وهو كتاب لا يستغنى عنه من ابتلى بصحبة مبتدعة عصرنا من هذا الصنف بصرهم الله. وقد مر لك في هذه الرسالة من تلك النصوص الشريفة الصارفة عن الظواهر الحسية إلى المعاني اللائقة بالذات العلية ما فيه المقنع إن شاء الله\r(فصل فيما يختص به عز وجل\rمن الصفات الواجبة له على ما يدل عليه القرآن العظيم ويشهد به كل ذي عقل سليم)\rقد سبق القول أن ما عداه عز وجل منه ما هو ممكن بالبداهة، ومنه ما هو ممكن بالنظر الصحيح، ودللناك على براهين العقل والنقل على ذلك من القرآن المجيد، "], [83, "وأن ما اختصت به من الصفات ينادي بحدوثها، وحدوثها يدل دلالة لا لبس فيها على إمكانها، وأن الممكن لا يترجح وجوده على عدمه، ولا يبرز من العدم إلى الوجود إلا بمن علا عن دوائر الإمكان، وثبت له وجوب الوجود ولوازم ذلك الوجود الواجب، وتقرر أن وجود الممكن مرآة للواجب جل شأنه، فأول ما يتراءى لك في مرايا الممكنات من صفاته عز وجل هو وجوب وجوده. والقرآن الكريم قد أفاد هذه الصفة العلية له عز وجل في مواضع كثيرة جدا بأساليب رائعة متنوعة، وعبارات تمر إلى القلوب من الآذان بلا استئذان، فمن ذلك قوله عز وجل {كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ} [القصص: 88] وقد سبق في المقدمة بيانه مستوفى، ومن ذلك قوله عز وجل {هُوَ الْأَوَّلُ وَالْآخِرُ} [الحديد: 3] وهي جملة معرفة الطرفين، فهي تفيد أن الأول هو لا سواه، وأن الآخر هو لا غيره، ولا ذلك كذلك إلا إذا كان الوجود لازما له بلا ابتداء ولا انتهاء، وذلك هو معنى وجوب الوجود. ومن ذلك قوله تعالى {اللَّهُ خَالِقُ كُلِّ شَيْءٍ} [الرعد: 16] والخالقية للأشياء لا تكون إلا وصفا لمن وجب وجوده، فإن الممكن لا يملك لنفسه فضلا عن غيره ضرا ولا نفعا، ولا موتا ولا حياة ولا نشورا. ومن ذلك قوله تعالى وهو أظهر وأبهر وأجمع المعالي الكمالات الربانية، ونفى سمات الحدوث والإمكان عنه {إِنَّ اللَّهَ هُوَ الْغَنِيُّ الْحَمِيدُ} [لقمان: 26] وقد زاده تأكيدا حيث قال في آية أخرى {وَإِنَّ اللَّهَ لَهُوَ الْغَنِيُّ الْحَمِيدُ} [الحج: 64] فجعل الفقر لكل ما عداه، والغنى كله في أعلى درجاته له دون ما سواه، تلك كملة أجمع كل العقلاء عليها وإن تقاصر بعضهم عن العلم بكثير مما انطوت عليه، فضلوا وأضلوا، فإنها تدل بأجلى بيان على وجوب وجوده تعالى ولوازم هذا الوجود من القدم والبقاء ونفى سمات الحدوث من الصغر والكبر والكون في الجهة والمكان إلى آخر ما عددنا في الفصول السابقة، فإن للواجب أحكاما لا تنفك عنه من حيث هو واجب. فمنها القدم والبقاء فإنهما لو انتفيا أو أحدهما لكان هذا الموجود ممكنا، فإن ما ليس بقديم هو الحادث، وقد سبق لك مرارا "], [84, "أن الحادث لا يكون إلا ممكنا، وكذلك ما يقبل الفناء، فإن وجوده لا يكون لازما من لوازم ذاته لذاته، فيكون ممكنا لا محالة، وقد ثبت للحق وجوب الوجود فوجب له القدم والبقاء، ومن أحكام الواجب الوحدة في ذاته بمعنى نفي التركب عنه، ونفي الامتداد وقبول الانقسام، فإنه لو تركب تعالى لكان في حاجة إلى الأجزاء التي يتركب منها، وإلى من يركبه، وذلك من سمات الحدوث، والحدوث فرع عن الإمكان. وقد دل الكتاب العزيز والعقل الصحيح على أنه واجب الوجود، ولا يكون الحق تعالى صغيرا ولا كبيرا كبر الأجسام، ولا يجوز عليه الامتداد ولا قبول الانقسام، ولا الجسمية ولا شيء مما يستلزمها من المقادير والجهات والأمكنة، وإلا لتطرقت الحاجة إليه، وكيف وهو الغني الحميد على الإطلاق. وهذه الكلمة الشريفة ليس فيها ذلك فقط بل فيها أن له الحياة والعلم والإرادة والقدرة والسمع والبصر والكلام في أكمل مراتبها وهي المرتبة اللائقة بوجوب وجوده عز وجل. ووجوب الوجود يستدعي وحدانيته عز وجل في الألوهية وخصائصها. ودونك آيتين كريمتين تجمع إحداهما صفات الجلال، والأخرى صفات الكمال التي يجب إثباتها لذي الجلال والإكرام. فأولاهما قوله تعالى: {لَيْسَ كَمِثْلِهِ شَيْءٌ} [الشورى: 11] والأخرى قوله عز وجل {وَلَهُ الْمَثَلُ الْأَعْلَى فِي السَّمَاوَاتِ وَالْأَرْضِ وَهُوَ الْعَزِيزُ الْحَكِيمُ} [الروم: 27]) فقوله تعالى: {لَيْسَ كَمِثْلِهِ شَيْءٌ} [الشورى: 11] نفت أن يكون له شبيه على أبلغ وجه بطريق الكناية، فإن معناها المراد: ليس كهو شيء، وليس معناها أن له مثلا ولا يشبه المثل شيء فهذا ما تأباء اللغة كل الإباء. فإن العرب تقول: مثلك لا يبخل ومثلك من يجود، وهي تريد نفي البخل عن المخاطب، وإثبات الجود له، ومن لم يتضلع من علم العربية وأصرار بلاغتها ضل في فهم الكتاب العزيز ضلالا بعيدا. وهو يحسب أنه على هدى مستقيم.\rوقوله جل شأنه: ((وله المثل الأعلى)) دل على أنه المتصف بكل كمال يليق بقدس ذاته وجلالة صفاته، والمثل هنا بمعنى الوصف العجيب الشأن، وقد وصف "], [85, "بالأعلى وهو من علو الرتبة، وقدم فيه الخبر للإشارة إلى الاختصاص، وتمم الكلام بقوله في السموات والأرض، لإيضاح أن اختصاصه بذلك أمر ظاهر في العوالم كلها، نادى به لسان حالها، ونطق به مؤمنوا أهلها. وغير خفي أن هذه العبارة التي لا يفي التعبير ببيان منتهى جزالتها وارتفاع بلاغتها، تدل ذا اللب على اتصافه تعالى بالوجود الواجب ولوازمه من انتفاء الأولية والتعالي عن النهاية، والتقدس عن سمات الحدوث ولوازم الإمكان: من الحدود والمقادير والأمكنة والجهات والانفراد بما ذكر، وبالحياة المستغنية عن النفس ــ بسكون الفاء ــ والنفس بفتحها، والعلم الأكمل المحيط، والإرادة النافذة، والقدرة التامة المقدسة عن الحاجة إلى الآلات، والحكمة الشاملة والسمع والبصر الكلام المتعاليات عن الجوارح والقيود التي تكون في المحدثات الخ، ما فصله علماء التوحيد في المطولات. شكر الله سعيهم. وبهذا كله تعلم وفقك الله أن ما اتفق عليه أهل الحق مما أشرنا إليه في هذه الرسالة من وجوب تنزهه سبحانه عن أضداد تلك الكمالات العليا، ووجوب اتصافه بما دخل من الصفات في المثل الأعلى، هو ما ينطق به القرآن الحكيم لمن أوتى الفهم فيه من أهل العلم، فلا يهولنك ما تسمع من تهويش مبتدعة العصر تبعا لأسلافهم، بتسمية المنزهين للحق عن الجهة والمكان معطلة وجهمية، وتلقيب القائلين ببدعتهم بالموحدين والمثبتين، كما لقب المعتزلة أنفسهم بالعدلية، ولقبوا أهل السنة المحققين المؤمنين بالقدر بضد ذلك اللقب، فلا يصرفنك النبز بالألقاب إلى الانحراف عن الحق الصراح الذي أرشد إليه كتاب الله وأوضحه أتم إيضاح.\r(فصل في الوحدانية وأن دليل القرآن عليها برهاني لا خطابي)\r"]], "pg": [82, 85]}, "526.27": {"x": [[85, "اعلم أن التوحيد الذي جاءت به المرسلون وبينه خاتمهم عليه وعليهم الصلاة والسلام أتم بيان، ونطق به القرآن وبرهن عليه أسطع برهان، هو أنه تعالى واحد "], [86, "في ذاته واحد في صفاته، ولا خالق سواه ولا يستحق العبادة إلا هو، والكلمة الطيبة لا إله إلا الله تتضمن أقسام التوحيد كلها. وقد أحسن البيهقي بيان ذلك في كتابه الأسماء والصفات. أما وحدانيته في ذاته سبحانه فمعناها أن ذاته العلية لا تتركب من أجزاء مادية ولا عقلية، ولا من أصول غير مادية، فلا تحوم حول حماها المقادير والمساحات والأشكال ونحوها، وقد برهنه القرآن ببيان أن له سبحانه الغني الأكمل ووجوب الوجود. والتركب في الذات واتصافها بالمقدار ولوازمه يستلزمان الحاجة إلى الغير والافتقار إلى السوى، وينافيان وجوب الوجود، ويقتضيان الاتصاف بالإمكان، تعالى الله عن ذلك كله، فهو واجب الوجود، وهو الأول والآخر وهو الغني الحميد، وقد مر مفصلا في الفصل الأول من هذا المقصد وفيما قبله من المقدمة. وأما أنه واحد في الصفات فهو أنه سبحانه لا ثاني له في وجوب الوجود وما يستلزمه من الكمالات العليا اللائقة بمرتبة وجوده الأعلى: من الحياة والعلم والإرادة والقدرة وسائر ما مر من الصفات، وبينه بعض الأفاضل كما في شرح الداواني للعضدية، وحواشيه، بأن كون الشيء منفردا في نوع من الأنواع بحيث لا يوازيه فرد من أفراد ذلك النوع فيه، قاض بكونه أكمل في ذلك النوع بالنسبة إلى سائر الأفراد: المعدوم المطلق في العدم والموجود المطلق في الوجود، والعالم المطلق في العلم، وهكذا، فكون الشيء منفردا في أمر أكمل وأولى بذلك الشيء، فكون الواجب منفردا في مرتبة الوجود أو شيء من متعلقاتها، أكمل له من أن يشاركه غيره في تلك المرتبة، والواجب يجب أن يكون في أعلى مراتب الكمال لاستغنائه الغنى المطلق، فيجب أن يكون منفردا في جميع الكمالات، فيكون واحد كل نوع من الوجود ولوازمه من سائر الكمالات، فلا يكون له مشارك في وجوب الوجود ولوازمه، فهو واحد والكل دونه. اهـ. وكأن هذا البرهان الشريف مقتبس مما أشار إليه القرآن الكريم بقوله {لَيْسَ كَمِثْلِهِ شَيْءٌ} [الشورى: 11] وقوله {وَلَهُ الْمَثَلُ الْأَعْلَى فِي السَّمَاوَاتِ وَالْأَرْضِ "], [87, "وَهُوَ الْعَزِيزُ الْحَكِيمُ} [الروم: 27] وقد مر شرحهما قريبا،\rوإذ قد ثبتت وحدانيته فيما ذكر لزم أنه لا خالق سواه ولا رب غيره، لما مر أن الإيجاد والإحداث يستحيل أن يكونا من الممكن فتعين أن يكونا من الواجب الذي لا شريك له في وجوب الوجود وتوابعه.\r\r(مطلب في بيان أن توحيد الربوبية وتوحيد الألوهية متلازمان لا ينفك أحدهما عن صاحبه)\r"]], "pg": [85, 87]}, "526.28": {"x": [[87, "وإذا بان أنه لا خالق سواه ثبت قطعا أنه لا يستحق العبادة غيره، فإن توحيد الربوبية وتوحيد الألوهية ــ أي استحقاق العبادة ــ متلازمان عرفا وشرعا، فالقول بأحدهما قول بالآخر، والإشراك في أحدهما إشراك في الآخر، فمن اعتقد أنه لا رب ولا خالق إلا الله، لم ير مستحقا للعبادة إلا هو، ومن اعتقد أنه لا يستحق العبادة غيره كان ذلك بناء منه على أنه لا رب إلا هو، ومن أشرك مع الله غيره في العبادة كان لا محالة قائلا بربوبية هذا الغير، هذا ما لا يعرف في الناس سواه، فأن ما لا تعتقد له ربوبية استحال أن يتخذ معبودا، ولهذا تجد الأنبياء عليهم الصلاة والسلام ومن أرسلهم جل جلاله يكتفون في الدعوة إلى التوحيد بأحدهما ويضعون كلا منهما موضع الآخر، اكتفاء بشدة التلازم بينهما في العقول، وأن القول بتوحيد الربوبية هو إقرار بتوحيد الألوهية وبالعكس وإليك البيان من القرآن والسنة: أخذ ربك من بني آدم من ظهورهم ذريتهم وأشهدهم على أنفسهم، فماذا كانت صيغة العهد بنص القرآن؟ هكذا (ألست بربكم) ولم يقل بإلهكم، وجعله سبحانه حجة على من أشركوا به في العبادة حيث قال {تَقُولُوا يَوْمَ الْقِيَامَةِ إِنَّا كُنَّا عَنْ هَذَا غَافِلِينَ (172) أَوْ تَقُولُوا إِنَّمَا أَشْرَكَ آبَاؤُنَا مِنْ قَبْلُ} [الأعراف: 172، 173] الآية. أليس هذا صريحا في أن أخذ العهد بتوحيد الربوبية هو أخذ للعهد بتوحيد العبادة؟ هذا ما لا خلاف فيه بين العلماء من زمن الصحابة"], [88, "إلى عهدنا هذا، بله رجلا كان في القرن الثامن الهجري وشايعه من انخدع بآرائه، ماذا قال نبي الله نوح لقومه الوثنيين؟ فقلت استغفروا ربكم، وأقام لهم البرهان على توحيد الربوبية، لما تقرر في عقول الناس أنها لا تعبد غير الله إلا إذا أشركت هذا الغير في الربوبية، فإذا انمحى عنها هذا الإشراك تبعه التوحيد في العبودية. ماذا قال إبراهيم لذلك الذي حاجه في ربه؟ قال ربي الذي يحيي ويميت، وقال عليه السلام لقومه تنزلا معهم ليهديهم إلى الحق: هذا ربي، هذا ربي، ولم يقل إلهي، وكان نهاية الحجة أن قال {إِنِّي وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَاوَاتِ وَالْأَرْضَ} [الأنعام: 79] وما هذا إلا توحيد الربوبية المستلزم في كل عقل إذا سلمه توحيد الألوهية. وقال الخليل عليه السلام أيضا لعباد الأصنام: {بَلْ رَبُّكُمْ رَبُّ السَّمَاوَاتِ وَالْأَرْضِ الَّذِي فَطَرَهُنَّ} [الأنبياء: 56] الآية. أليس هذا إضرابا إبطاليا لما اعتقدوه من ربوبية الأصنام؟ وأقام الدليل الحسي عليه السلام على عجز الأصنام بتكسيره إياها بيانا لعابديها أنها لو كانت أربابا كما اعتقدوا لاستطاعت الدفع عن نفسها، فإذا بطلت ربوبيتها زالت عن المخاطبين عبادتها، وذلك جلي لا يخفى والمناقشة فيه مكابرة. وقال موسى وهارون عليهما السلام: إنا رسول رب العالمين. ولما سألهما قال رب السموات والأرض وما بينهما ربكم ورب آبائكم الأولين رب المشرق والمغرب وما بينهما إن كنتم تعقلون. وقال فرعون مرة: ما علمت لكم من إله غيري، وقال أخرى: أنا ربكم الأعلى، ويقول الله لعيسى بن مريم: أأنت قلت للناس اتخذوني وأمي إلهين من دون الله؟ فيقول بعد كلام حكاه عنه التنزيل ما قلت لهم إلا ما أمرتني به أن اعبدوا الله ربي وربكم. فلو كان توحيد الربوبية لا يستلزم عندهم توحيد الألوهية كما زعم الخراصون لتوجه على المسيح عليه السلام أن يقال له: ما أديت رسالتنا فإنا إنما أرسلناك بتوحيد الألوهية، ولم تكلفك ببيان توحيد الربوبية لأنهم مقرون به، ولكنا نرى الله تعالى قد قبل منه هذه الحجة أفلا يكون في ذلك على ما نقول أبين حجة وعنه عليه السلام "], [89, "في موضع آخر من الكتاب العزيز: وإن الله ربي وربكم فاعبدوه. بفاء التفريع والترتب المفيدة للاستلزام، ويقول القرآن فيما أمر به الرسول الأعظم تارة: قل أغير الله أتخذ وليا؟ أي معبودا، وأخرى. قل أغير الله أبغي ربا وهو رب كل شيء؟ وحديث المسألة في القبر الذي يكاد يبلغ حد التواتر المعنوي مشهور، وفيه أن الملكين يقولان للميت: من ربك؟ ولا يقولان من إلهك؟ فإذا أجابهما: (الله ربي)) اكتفيا منه في التوحيد بهذا الجواب، ولم يقولا له هذا توحيد الربوبية وهو لا ينجيك، فأول ما خاطب الله الأرواح قال ألست بربكم واكتفى منهم بالإقرار بوحدانيته في الربوبية، وأول ما تسأل الموتى في قبورها من ربك؟ واكتفى منهم بالإقرار بأنه ربهم، أفبعد هذا يتشكك متشكك؟ ولكن الله يهدي لنوره من يشاء\rوكذلك رتب القرآن اللوازم الفاسدة على نفي الوحدانية في الألوهية بيانا منه تعالى أن الشركة في الألوهية تستلزم الشركة في الربوبية عند المشركين لا محالة، تعالى الله أن يكون له شريك، فانظر ماذا قال سبحانه {وَمَا كَانَ مَعَهُ مِنْ إِلَهٍ إِذًا لَذَهَبَ كُلُّ إِلَهٍ بِمَا خَلَقَ وَلَعَلَا بَعْضُهُمْ عَلَى بَعْضٍ سُبْحَانَ اللَّهِ عَمَّا يَصِفُونَ} [المؤمنون: 91] ومعناه عند أولي النهى: أنه لو كان معه إله لكان ربا وخالقا، ولو كان معه ذلك لذهب الخ وإنما يكون الدليل تاما إذا صحت الملازمة وكانت مسلمة عند المخاطبين، ويأبى الله أن تكون حجته إلا تامة (وتمت كملة ربك صدقا وعدلا) ومعنى هذا أن القرآن يقرر أن من أشرك في استحقاق العبادة كان مشركا لا محالة في الربوبية وكذلك قال تعالى {لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللَّهُ لَفَسَدَتَا} [الأنبياء: 22] ولم يقل أرباب لتلازم الربوبية والألوهية نفيا وإثباتا وتقرير هذا البرهان الشريف: أنه لو كان معه شريك في الألوهية لكان شريكا في كونه ربا وخالقا، ولو كان كذلك لكان شريكا له في وجوب الوجود، ولو كان ذلك كذلك لفسدت العوالم، ولما كان لها نظام، بل ما كان لشيء منها وجود، فهنا ثلاث ملازمات، وبيان الأولى منها ما نقرر "], [90, "في العقول من أن ما كان ربا كان إلها وبالعكس، ولا يعرف العقلاء سوى هذا، ولولا مشاغبة هذا المجترح لهذه البدعة وفريق المخدوعين برأيه لكان الكلام في إيضاحها ضربا من العبث. وبيان الملازمة الثانية ما تقدم من أن الممكن لذاته لا يملك الوجود فضلا عن الإيجاد، فمتى كان الشيء خالقا وموجدا كان لا محالة واجبا لا ممكنا، وقد فصلناه فيما سبق وقررناه وكررناه. وأما بيان الملازمة الثالثة وهي أنه لو تعدد واجب الوجود ما كان هذا النظام، بل ما كان وجود لكائن من الممكنات، فإنه محتاج إلى شيء من البسط، فافتح قلبك واستعن بالله ثم انظر معي إلى ما تعرف من الحقائق ولوازمها، فستجد أن الحقائق إذا اختلفت كانت لوازمها مختلفة لا محالة، كالحار يلزمه التبريد، وإذا وجدت لازما واحدا لحقيقتين فلا يكون لازما لهما من حيث ما اختلفا فيه، بل هو لازم لهما من حيث ما اشتركا فيه، فهو إذا ليس لازما، إلا للأمر الأعم المشترك بينهما، كالمتحرك اللازم للإنسان وغيره من الحيوان، فهو لازم لهما من حيث الأمر الأعم وهو الحيوان، فان حقيقة الإنسان وسواه من مشاركيه في الجنس مركبة مما به الاشتراك وما به الامتياز، ثم اللوازم منها ما يكون لأمر خارج عن الشيء وتسمى عرضية، ومنها ما يكون لذات الشيء لا لأمر خارج وتسمى ذاتية فما لزم الحقائق من حيث ما به اختلافها كان مختلفا غير متحد. وقد أراك الله ذلك فيما خلق، فترى لكل شخص شكلا خاصا، وترى للبياض لوازم تخصه، وللسواد لوازم تخبصه، ولكل عنصر ولكل مركب خواص تباين خواص الآخر غير أنه ليس في الممكنات الموجودة من ذوات ولوازم إلا ما هو بالجعل كما قدمناه مفصلا في بحث الممكنات، وقررنا هناك أن اللزوم في الأغلب عادي، ومن أجل هذا جاز التخلف، ولكنا ذكرنا ذلك هنا لترقى به إلى ما سنلقي عليك وهو أن الواجب لا يجوز في حقيقته التركب، فإن التركب من لوازم الإمكان كما مر ولا يكون له شيء بالجعل، وإلا كان ممكنا بالبداهة، وقد سبق أن الواجب له الغنى الأتم "], [91, "فكمالاته اللائقة بمرتبة وجوده لا تكون إلا لوازم ذاتية هي له بمقتضى ذاته وموجب حقيقته الخاصة. إذا فهمت هذا وأتقنته حق إتقانه تبين لك أنه لو تعددت ذوات واجب لوجود لكانت مختلفة كل الاختلاف متباينة كل التباين لأنه لا تركب في حقيقة الواجب، حتى يكون هناك ذاتي يشترك فيه، ولوازم حقيقة الواجب ذاتية، فيكون لكل واجب لوازم تخصه وكمالات هي له بمقتضى ذاته المباينة لذات الآخر، ومتى اختلفت الحقائق كل الاختلاف تبعها اختلاف لوازمها وتباينها كل التباين، ومن كمالات الواجب ولوازمه الذاتية العلم والإرادة والقدرة كما أسلفنا، وفعل كل إنما يكون بالقدرة على حسب الإرادة، والإرادة على وفق العلم، ووجود الكائنات ونظامها إنما هو بحسب ذلك، فلو كان في الوجود أكثر من واجب لتخالفت علومهم وإراداتهم حسب اختلاف حقائقهم، وهذا اختلاف ذاتي يستحيل معه الوفاق، ولو كان كذلك ما اتحد هذا النظام الذي تراه، بل كان مختلفا مضطربا بل لما وجد نظام، بل لما وجد، كائن من الكائنات لأن السلطة على كل ممكن عامة والممكن من حيث ذاته قابل للتأثر، والقوى في الواجبين متكافئة متدافعة متشاكسة فأنى يوجد كائن؟ وهانت ذا ترى النظام مؤتلفا غير مختلف، مرتبطا غير مفكك، أفلا ينطق ذلك بوحدانية واجب الوجود في ذاته العلية وكمالاته المقدسة التي لا تصح إلا له بمقتضى ذاته وموجب حقيقته، بلى، فتعالى الله عما يشركون. وربما احتاج غير اللبيب في هذا المقام: إلى أبسط من هذا البيان، لكن مقام هذا الوجيز لا يسمح بأكثر من هذا، وفيه لذي اللب مقنع إن شاء الله تعالى.\rوبما سلف من التقرير تعلم أن هذا الدليل القرآني على الوحدانية برهاني تام لا خطابي إقناعي، وهو الذي عليه المحققون من فرسان المعقول والمدققين في فهم المنقول، حتى شنعوا على العلامة سعد الدين التفتازاني في قولنه بأنه خطابي، وبعد فلا خفاء على من تدبر كتاب الله في أن توحيد الربوبية وتوحيد الألوهية "], [92, "متلازمان في نظر العقل والشرع، فالقول بأحدهما قول بالآخر، وانتفاء أحدهما في اعتقاد من اعتقد الانتفاء قول منه بانتفاء الآخر، والبرهنة على أحدهما هو استدلال على الآخر، والقول بأن المرسلين عليهم الصلاة والسلام ما جاءوا بتوحيد الربوبية لأن الناس كانوا في غنية عن بيانه، وما جاءوا إلا بتوحيد العبادة احتجاجا ببعض الآيات التي لم يحسنوا فهمها، قول بما تكذبه نصوص الكتاب العزيز، ودعوى يدحضها العلم بتاريخ المشركين قديمه وحديثه، ما حكاه الكتاب العزيز من ذلك وما علمه الناس. هؤلاء المفتتنون بفتنة السامري من بني إسرائيل أشركونا العجل في عبادة ربهم، فقال لهم نبي الله هارون بصيغة الحصر {وَإِنَّ رَبَّكُمُ الرَّحْمَنُ} [طه: 90] يعني لا هذا العجل، فهل يصح منه عليه السلام هذا الكلام إلا إذا كان إشراكهم في العبادة مبنيا على الإشراك في الربوبية؟ اللهم إن القول بخلاف هذا معاندة للحق، وانقياد لمحض الهوى، وصح أن سائلا سأله عليه الصلاة والسلام عن وصية موجزة كافية لا يسأل بعدها أحدا غيره، فقال له: بأبي هو وأمي، عليه الصلاة والسلام (قل ربي الله ثم استقم) فلو كان كما يقول ذلك المفرق بين التوحيدين الذي استحلت بناء على فتياه هذه دماء لا تحصى، حقنها الإسلام وحرمها الله ورسوله، لكانت هذه الوصية غير كافية مؤدية لما جاء به المرسلون، وحاشاها من ذلك، كذلك قال تعالى: {إِنَّ الَّذِينَ قَالُوا رَبُّنَا اللَّهُ ثُمَّ اسْتَقَامُوا} [فصلت: 30] الآية، وهذه العبارة في موضعين من كتاب الله تعالى: في سورة حم السجدة وسورة الأحقاف وقد رتب السعادة كلها على الاستقامة المبنية على قول (ربنا الله) دون أن يقول إلهنا، فهل بعد الله ورسوله لأحد من قول؟ {فَبِأَيِّ حَدِيثٍ بَعْدَ اللَّهِ وَآيَاتِهِ يُؤْمِنُونَ} [الجاثية: 6] وسنعود إلى هذا الموضوع مرة أخرى في الخاتمة عند بيان معنى العبادة شرعا. وإني لعلى ثقة أن هذا البيان كاف إن شاء الله لمن نور الله بصيرته، ولم يستفحل به داء البدعة أجارنا الله منها وإياكم أهل السنة. وإن أضعاف هذا البيان لا يكفي من أشربوا في قلوبهم حب "]], "pg": [87, 92]}, "526.29": {"x": [[93, "الانحراف عن جماعة أهل الحق، وأغرموا بالتشنيع على جماهير المسلمين وتكفيرهم ونبز أكابرهم من العلماء العاملين وأهل السنة المحققين، بأنهم أئمة الكفر والهادمون للإسلام، والمنابذون للسنة والقرآن، والخائنون لدين الله، إلى أشباه ذلك مما يعبس له وجه الإسلام، وتغضب له الحقائق، ويلقى بذور الشقاق بين الأمة، التي وحد الإسلام الصحيح بينها، وأوصى الإسلام أهله بالمحافظة عليها ــ أعني تلك الوحدة ــ فنسأل الله الكريم بنبيه العظيم نبي الرحمة أن يلهم جميع الأمة الرشد حتى تجتمع ولا تتفرق، وتتحاب ولا تتباغض. إنه ذو الفضل العظيم.\r(فصل\rفيما يوهم التشبيه عند العامة من ظاهر الكتاب والسنة)\rسبق لك في فصول هذا المقصد أن القرآن يدل صراحة أن كل مقدر مخلوق، وأن كل ما في المادة من الصفات كالصغر والكبر وقبول الانقسام والكون في الجهة والمكان والعلو والنزول والتجزؤ وغيرها مما مر إنما هو من علامات الحدوث وسمات الإمكان، وبينا دلالة الكتاب العزيز على ذلك دلالة لا اشتباه فيها ولا التباس، إلا على من نبذ الفهم وأطاع الوهم واتبع الوساوس أو قلد متبعيها وتقدم أيضا أن الاتصاف بالخالقية يدل على التنزه عن الإمكان وعن كل ما يستلزمه، ويقتضي الاتصاف بوجوب الوجود وما يستتبعه، وأريناك كيف يفيد القرآن ذلك على أوضح وجه وأبينه، فيكون ما أجمع عليه أهل الحق من علماء السلف والخلف من تنزه الحق عن الجهة وتقدسه عن المكان وتعاليه عن التجزؤ والتبعيض والصعود والنزول والقرب والبعد والذهاب والمجيء والحركة والسكون وما أشبه ذلك، ما أجمع عليه أهل الحق من تعالى الملك القدوس عن ذلك كله، ليس هو مما أخذه العلماء من فلسفة اليونان، كما يشنع به على "], [94, "القوم ابن تيمية وإنما هو من حكمة القرآن وفلسفة الإسلام لمن فقه في دين الله أحسن تدبر كتابه كما تقدمت الشواهد على ذلك من الكتاب العزيز مشروحة مبسوطة. وهذا هو السر الذي جعلهم رضي الله عنهم في اتفاق على أن كل ما دل من الكتاب والسنة بظاهره على ما هو من صفات الجسم وسمات الحدوث، فهو مصروف عن هذا الظاهر قطعا، لا خلاف في ذلك بين علماء الصحابة والتابعين فمن بعدهم من أهل الفقه في كتاب الله وسنة رسوله صلى الله عليه وسلم وعلى آله وسلم، سلفا وخلفا، وحجتهم في ذلك في كتاب الله واضحة، وأدلتهم عليه في آيات القرآن لائحة، والبراهين العقلية الصحيحة به ناطقة مفصحة، وقد أسلفنا منها في هذه الرسالة الشيء الكثير البين فلا نعيده، فكان ذلك قرائن صارفة لهذه النصوص عن هذه الظواهر، إلا أن الغالب على أكثر السلف الكف عن بيان المعنى المراد اللائق بالحق تعالى من هذه النصوص، والإمساك عن تعيينه ورعا وتهيبا لذلك المقام الأقدس، لا سيما إن كان اللفظ الشريف يحتمل بمقتضى اللغة معنيين أو أكثر كل منها لائق بالجناب الأقدس، وكفا لمن لا يعرف شروط التأويل عن الخوض فيما لا يحسنه، فإن العامي الجاهل إذا سمع من العالم تأويلا لكلمة يوجب العلم صرفها عن ظاهرها، سوغ لنفسه أن يقول بغير علم بما شاء له الهوى في الكتاب والسنة، فضل ضلالا بعيدا، فسدوا الذريعة وحسموا المادة وأوصدوا الباب في وجوه العوام حتى لا يتهجم منهم متهجم على حرم الآيات والأحاديث الممنوع على أمثاله، لعدم اتصافه بالمؤهلات التي يفرق بها بين ما يجوز من التأويل وما لا يجوز منه، ولذلك كان الكثير منهم يقول ((تفسيرها قرائنها)) ويقولون: أمروها كما جاءت من غير كيف. فقولهم رضي الله عنهم من غير كيف، ونهيهم عن التفسير، صريح في صرفها عن المعنى الظاهري التشبيهي، الذي يتبادر إلى الذهن العامي، وإلا فلو كان هذا المعنى مرادا ومعتقدا للسلف كما يصرح به أدعياء السلفية، لفسروا ولما نهوا عن التفسير، "], [95, "ولما نفوا المكيف كما هو واضح، ولحجة الإسلام الغزالي رضي الله عنه كتاب نفيس في هذه المسألة سماه ((إلجام العوام عن علم الكلام)) أفاد فيه وأجاد كعادته جزاه الله خير الجزاء، لا غنى لمن يريد تحقيق هذا المقام عن مطالعته ومذاكرته.\r(فائدة مهمة في أن أكثر السلف يقولون بالصرف عن الظواهر)\r"]], "pg": [93, 95]}, "526.30": {"x": [[95, "إن أهل العلم نقلهم عن أكثر السلف القول بالصرف عن الظواهر وعدم الخوض في بيان المعنى المراد، اختلفوا هل يسمى هذا الصرف مع عدم تعيين المراد تأويلا، أولا يسمى ذلك تأويلا حتى يعين المعنى المراد؟ وبالثاني قال كثير من أهل العلم؛ فإنهم رأوا أن التأويل هو بيان المعنى الذي يقصد من الكلام فإذا صرف الكلام عن الظاهر فقط وفوض المعنى المراد إلى قائله لم يسم تأويلا. والأمر في ذلك هين، فإن الصرف عن الظاهر متفق عليه سمي تأويلا أم لا، فتفطن لهذه الفائدة، فإن مما يموه به المبتعدة لا سيما ابن تيمية، نقل نفي التأويل عن السلف يلبس بهذا النقل على القاصرين عن معرفة هذه المسألة، ويوهمهم أن السلف يحملون هذه الألفاظ على ظواهرها، وحاشاهم من ذلك، وإنما معنى ما نقل عنهم أنهم لا يعينون المعنى المراد، مع الصرف عن الظواهر.\r(بيان ما دعا الكثير من علماء السلف والخلف إلى تعيين المعنى المراد)\r"]], "pg": [95, 95]}, "526.31": {"x": [[95, "ولما كثر الجاهلون الذين لا خبرة لهم بما أشار إليه القرآن من أصول الدين في باب التنزيه، وكانوا قد جمعوا من الحديث، ولم يكن لهم من الورع ما يحملهم على الكف عن تفسير هذه النصوص ولا من الفقه في لغة العرب ما يتنبهون به إلى غير ما يتبادر إلى أذهانهم القاصرة، اجترؤوا على تفسيرها بما ينكره أهل العلم بالقرآن، وتزيد آخرون في الرواية لما لا يصح، اضطر بعض السلف إلى بيان المعنى المراد على ما يقتضيه اللسان الذي نزل به القرآن، وتبعهم الكثير من "], [96, "الخلق، فإن الخطب بالمجسمة والمشبهة كان في أزمانهم أعم وأطم، وتوسع منهم ناس في التأويل، واقتصد آخرون. ومن أحسن ما ينبغي أن يعول عليه في هذا الباب، بل أحسنه ما قاله الإمام الحجة في المعقول والمنقول سيف الله على المبتدعة من الحشوية وسواهم ((ابن دقيق العيد)) رضي الله عنه، وهو: ((أنه إن كان التأويل من المجاز البين الشائع فالحق سلوكه من غير توقف، وإن كان من المجاز البعيد الشاذ فالحق تركه، وإن استوى الأمران فالاختلاف في جوازه وعدم جوازه مسألة فقهية اجتهادية، والأمر فيها ليس بالخطر بالنسبة للفريقين)) اهـ. وهذه قاعدة تنبئ عن مزيد فضل واضعها وتضلعه في علم الكتاب والسنة، وتمكنه من أسرار هذه اللغة الفصحى التي نزل بها كتاب الله، فان القول بالتأويل مطلقا بلا قيد ولا شرط كما يشاء الهوى هو خروج عن الملة، ودخول في الكفر والإلحاد، وأول من ابتدعه فرقة تسمى بالباطنية بدؤوا يظهرون في القرن الرابع، يزعمون أن ظواهر الآيات غير مرادة، فأنكروا كل شيء حتى ما علم من الدين بالضرورة: وعلى هذا الوتر ضربت الجماعة التي سمت أنفسها إخوان الصفا فألفوا تلك الرسائل المضافة إلى هذا الاسم، ودسوا فيها ما شاؤوا من الكيد للإسلام وأهله\rثم افترق الباطنية إلى فرق تسمت بأسماء مختلفة ليس هذا محل بسطها، ومن أحدثها عهدا فرقة البهائية، وهم فرقة ينتسبون إلى رجل يقال له مرازا حسين. ويلقبونه بالبهاء، يزعمون فيه ما زعمت النصارى في عيسى من الألوهية، ويكفرون بالقرآن كله، ويتسترون بالتأويل، ويزعمون نسخ دين الإسلام بدينهم الذي ما أنزل الله به من سلطان. وعلى نهج هؤلاء الكفرة سارت فرقة القاديانية إلا أنهم أحذق منهم ضلالا وإضلالا؛ زعموا أن متبوعهم غلام أحمد القادياني ــ نسبة إلى قرية بالهند يقال لها قاديان ــ جاءته النبوة، وتأولوا ما لا يقبل التأويل وهو قوله تعالى في نبيه المصطفى عليه الصلاة والسلام {وَخَاتَمَ النَّبِيِّينَ} [الأحزاب: 40] فنعوذ بالله من الفتن ما ظهر منها وما بطن. وقد ألفت كتب من أكابر الفضلاء "], [97, "للرد على هذه الفرق، وإنما سمينا هاتين الفرقتين لوجودهما في عصرنا واهرار بعض الجاهلين بمظاهرهما، ونفاقهما. فليعلموا أنهم إذا دخلوا فيهم فقد خرجوا من الإسلام وإن نسموا بأسماء المسلمين.\rولنعد بك إلى ما نحن بسبيله فنقول: كما أن التأويل بلا قيد ولا شرط ضلال أي ضلال، فكذلك الجمود على الظاهر وترك التأويل مطلقا فسق وابتداع وربما أفضى إلى صريح الكفر، فمن قال في قوله تعالى {لَيْسَ كَمِثْلِهِ شَيْءٌ} [الشورى: 11] إن ظاهره أن لله مثلا وليس كهذا المثل شيء، فلنقل بظاهره كما هو، والصرف عن الظاهر تأويل، والتأويل بدعة وكل بدعة ضلالة، كان مشركا بالله، كاذبا على كتاب الله، خارجا على الإسلام وأهله، منابذا للغة القرآن. فالحق الذي لا معدل عنه هو ما قرره الإمام ابن دقيق العيد. ومن تتبع براهين القرآن واستقرأ آياته العظام، وجد كثيرا مما تشابه على من ليس في درجته قد صار لديه محكما وزال عنه التشابه فيه ورأى كثيرا منه من القسم الأول وهو ما كان من المجاز البين الشائع في لغة العرب، وعلى قدر الرسوخ في العلم يكون زوال التشابه أو أكثره عن الكثير من المتشابه. وقد مر نحو من هذا فيما نقلناه عن ابن جرير في تفسير قوله تعالى {فَيَتَّبِعُونَ مَا تَشَابَهَ مِنْهُ} [آل عمران: 7] فلا تغفل. ولما كان الراسخون في العلم متفاوتين لا جرم تفاوتت أنصباؤهم في زوال التشابه عنهم، وقد جمع كتاب الأسماء والصفات للإمام الحافظ أبي بكر البيهقي من علم الراسخين ما لم يجمعه كتاب قبله، ولذلك ننصح لأهل العلم الذين تأهلوا للغوص على درر الكتاب والسنة أي يقرأوه ويديموا مذكراته لا سيما مع التعليقات التي تفضل بوضعها عليه العلامة المحقق الزاهد حفظه الله. وسنتمم هذا الفصل بذكر أمثلة تنبهك على غيرها إن شاء الله تعالى. قال الله تعالى في عيسى {إِذْ قَالَتِ الْمَلَائِكَةُ يَامَرْيَمُ إِنَّ اللَّهَ يُبَشِّرُكِ بِكَلِمَةٍ مِنْهُ} [آل عمران: 45] وقال {وَكَلِمَتُهُ أَلْقَاهَا إِلَى مَرْيَمَ} [النساء: 171] قد فسرت معناها الآية القائلة {إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُ} [آل عمران: 47] فالكلمة في عيسى مجاز "], [98, "مرسل من إطلاق السبب على المسبب، وقوله تعالى {أَنْ تَقُولَ نَفْسٌ يَاحَسْرَتَا عَلَى مَا فَرَّطْتُ فِي جَنْبِ اللَّهِ} [الزمر: 56] ظاهر أن معناه في حقه وما يتعلق به من أمره ونهيه، وقوله تعالى في آدم {لِمَا خَلَقْتُ بِيَدَيَّ} [ص: 75] هو كناية عن أنه فاز من عنايته تعالى بما لم يفز به ملك ولا جن. وقوله في آية أخرى في حق آدم {خَلَقَهُ مِنْ تُرَابٍ ثُمَّ قَالَ لَهُ كُنْ فَيَكُونُ} [آل عمران: 59] فقد سلك فيه طريق التصريح دون الكناية، ولكل من التصريح والكناية في الجملتين الشريفتين مقام اقتضاه يعرفه من أنعم التأمل. وقال تعالى: {وَالَّتِي أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهَا مِنْ رُوحِنَا} [الأنبياء: 91] فإسناد النفخ إليه تعالى مجازي فإن المباشر للنفخ جبريل عليه السلام وهو المراد بالروح المضاف إليه تعالى للتشريف بدليل قوله تعالى {فَأَرْسَلْنَا إِلَيْهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرًا سَوِيًّا} [مريم: 17] الآيات كما أن قوله تعالى: {وَلِنَجْعَلَهُ آيَةً لِلنَّاسِ وَرَحْمَةً مِنَّا} [مريم: 21] فسر قوله تعالى في عيسى (وروح منه) فإن من معاني الروح ــ بضم الراء ــ الرحمة. وما أحسن ما أنشد أبو بكر بن العربي في هؤلاء المجسمة المشبهة: ــ\rقالوا الظواهر أصل لا يجوز لنا ... عنها العدول إلى رأي ولا نظر\rبينوا عن الخلق لستم منهم أبدا ... ما للأنام ومعلوف من البقر\rوالمحققون من أكابر السلف يسلكون هذا المنهج حيث لا يكون عن التأويل معدل، ولا لبقاء اللفظ على ظاهره محل. ودونك كلام ترجمان السلف وإمام المفسرين أبي جعفر في الاستواء على العرش الذي دندن حوله أدعياء السلف وأغبياء الخلف، وتشبثوا به في القول بالجهة والمكان في حق الله تعالى الله عما قالوا. ولا أظن منصفا ينازع في سلفية ابن جرير رضي الله عنه. قال في تفسير قوله تعالى {ثُمَّ اسْتَوَى إِلَى السَّمَاءِ فَسَوَّاهُنَّ سَبْعَ سَمَاوَاتٍ} [البقرة: 29] في سورة البقرة وأحال عليه بعد ذلك تفسير الاستواء على العرش حيث ذكر في القرآن ما لفظه ((الاستواء في كلام العرب منصرف على وجوه: منها انتهاء شباب الرجل وقوته فيقال إذا صار كذلك: قد استوى الرجل. ومنها استقامة ما كان فيه أود من الأمور "], [99, "والأسباب، يقال منه استوى لفلان أمره إذا استقام له بعد أود ــ والأود كالقول الاعوجاج ــ ومنه قول الطرماح بن حكيم.\rطال على رسم مهدد أبده. ... وعفا واستوى به بلده\rوالطرماح بكسر الطاء والراء وشد الميم كسنمار، ومهدد على وزن جعفر اسم امرأة ــ يعني استقام به. ومنها الإقبال على الشيء بالفعل كما يقال استوى فلان على فلان بما يكرهه ويسوءه بعد الإحسان إليه. ومنها الاحتياز والاستيلاء كقولهم استوى فلان على المملكة بمعنى احتوى عليها وحازها. ومنها العلو والارتفاع، كقول القائل استوى فلان على سريره يعني به علوه عليه. وأولى المعاني بقول الله جل ثناؤه {ثُمَّ اسْتَوَى إِلَى السَّمَاءِ فَسَوَّاهُنَّ} [البقرة: 29] علا عليهن وارتفع فد برهن بقدرته، وخلقهن سبع سموات. والعجب ممن أنكر المعنى المفهوم من كلام العرب في تأويل قول الله {ثُمَّ اسْتَوَى إِلَى السَّمَاءِ} [البقرة: 29] الذي هو بمعنى العلو والارتفاع، هربا عند نفسه من أن يلزمه بزعمه إذا تأوله بمعناه المفهوم كذلك أن يكون إنما علا وارتفع بعد أن كان تحتها، إلى أن تأوله بالمجهول من تأويله المستنكر، ثم لم ينج مما هرب منه فيقال له: زعمت أن تأويل قوله استوى: أقبل أفكان مدبرا عن السماء فأقبل إليها؟ فإن زعم أن ذلك ليس بإقبال فعل ولكنه إقبال تدبير، قيل له فكذلك فقل علا عليها علو ملك وسلطان، لا علو انتقال وزوال، ثم لن يقول في شيء من ذلك قوله إلا ألزم في الآخر مثله، ولولا أنا كرهنا إطالة الكتاب بما ليس من جنسه لأنبأنا عن فساد قول كل قائل قال في ذلك قولا لقول أهل الحق فيه مخالفا. وفيما بينا منه ما يشرف بذي الفهم على ما فيه له الكفاية إن شاء الله تعالى. ((فأنت تراه لم يفسر الاستواء على العرش بالجلوس ولا بالاستقرار بل فسره بعلو الملك والسلطان، وكذلك فسر العلو في حق الله تعالى حيث ذكر من القرآن. وقال رضي الله عنه في تفسير آية الكرسي ((وأما تأويل قوله (وهو العلي) فإنه يعنى والله العلي، والعلي الفعيل من قولك علا يعلو "], [100, "علوا إذا ارتفع، فهو عال وعلي، والعلي ذو العلو والارتفاع على خلقه بقدرته، وكذلك قوله ((العظيم)) ذو العظمة الذي كل شيء دونه فلا شيء أعظم منه)). انتهى\rوقال رضي الله عنه في تفسير سورة النساء ((القول في تأويل قوله تعالى (إن الله كان عليا كبيرا) يقول إن الله ذو علو على كل شيء، فلا تبغوا أيها الناس على أزواجكم إذا أطعنكم فيما ألزمهن الله لكم من حق سبيلا لعلو أيديكم على أيديهن فإن الله أعلى منكم ومن كل شيء، وأعلى منكم عليهن وأكبر منكم ومن كل شيء، وأنتم في يده وقبضته، فاتقوا الله أن تظلموهن وتبغوا عليهن سبيلا، وهن لكم مطيعات فينتصر لهن منكم ربكم الذي هو أعلى منكم ومن كل شيء وأكبر منكم ومن كل شيء)). وقال رضي الله عنه في قوله تعالى: {عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْكَبِيرُ الْمُتَعَالِ} [الرعد: 9] يقول تعالى ذكره ((والله عالم ما غاب عنكم وعن أبصاركم فلم تروه، وما شاهدتموه فعاينتم بأبصاركم لا يخفى عليه شيء لأنهم خلقه وتدبيره، الكبير الذي كل شيء دونه المتعال المستعلي على كل شيء بقدرته، وهو المتفاعل من العلو مثل المتقارب من القرب والمتداني من الدنو)) انتهى.\rأقول: والعرب الذين نزل القرآن بلغتهم لا يفهمون سوى هذا، فإن العرش سرير الملك الذي يجلس عليه للحكم، والاستواء عليه هو العلو عليه، هذا هو أصل الوضع، ثم كنوا به عن علو الملك والسلطان حتى صار يستعمل في هذا المعنى بحيث يكون هو المقصود بالإثبات، فإذا قيل لم يستو على العرش، كان هذا المعنى هو المقصود بالنفي كما هو الشأن في المعنى المكنى عنه وفي المعنى المجازي لا يكون مورد الإثبات والنفي إلا إياهما لا المعنى المكنى به ولا المنقول عنه كما هو مبين في محله من علم البيان، ومن تتبع القرآن هداه إلى ما قلنا، فإن الاستواء على العرش مذكور في سبع آيات مقترنا بذكر فعل من أفعاله تعالى، دال على وجوب وجوده وغناه الغنى المطلق، وهو رفع السموات بغير عمد، أو خلق السموات والأرض وما بينهما في ستة أيام، فقد أقام القرآن القرينة اللفظية في كل موضع ذكر فيه الاستواء "], [101, "على أنه لم يرد ظاهره، وإنما معناه أنه سبحانه لما انفرد بإيجاد الأشياء كلها نوحد في التصرف فيها، فكما أنه لا شريك له في الخلق لا شريك له في الملك، ولذلك ختم بعض هذه الآيات بقوله تعالى: {أَلَا لَهُ الْخَلْقُ وَالْأَمْرُ تَبَارَكَ اللَّهُ رَبُّ الْعَالَمِينَ} [الأعراف: 54] بتقديم الخبر وهو (له) على المبتدأ وهو يدل على الحصر. فالخلق ناظر إلى انفراده بخلق السموات والأرض. والأمر عائد إلى توحده يعلو الملك. وقد يذكر في غير هذه الآيات خله لكل شيء ويردفه بما يؤدي هذا المعنى بكناية أخرى غير كناية الاستواء على العرش، كقوله {اللَّهُ خَالِقُ كُلِّ شَيْءٍ وَهُوَ عَلَى كُلِّ شَيْءٍ وَكِيلٌ (62) لَهُ مَقَالِيدُ السَّمَاوَاتِ وَالْأَرْضِ} [الزمر: 62، 63] وقوله {خَالِقُ كُلِّ شَيْءٍ فَاعْبُدُوهُ وَهُوَ عَلَى كُلِّ شَيْءٍ وَكِيلٌ} [الأنعام: 102] أي المدبر للكل القائم عنهم بجلب النفع إليهم ودفع الضر عنهم وقوله: {اللَّهُ الَّذِي خَلَقَ سَبْعَ سَمَاوَاتٍ وَمِنَ الْأَرْضِ مِثْلَهُنَّ} [الطلاق: 12] فانظر ماذا قال بعدها قال: (يتنزل الأمر بينهن) وهذه من روادف علو الملك وارتفاع السلكان. وعادة القرآن تصريف الآيات كما قال سبحانه {وَكَذَلِكَ نُصَرِّفُ الْآيَاتِ} [الأنعام: 105] وهو إدارة المعنى الواحد بطرق متنوعة وأساليب مختلفة رائعة. ومن زعم أن القرآن يقول بالعلو الحسمي في حق الله فما عرف الله ولا عرف كتابه، وقد سمعت ما قال شيخ المفسرين الطبري في تفسير اسمه تعالى (العلي) وأنت لو أنعمت في مواقع هذا الاسم الكريم من كتاب الله تعالى لم تجد له إلا ما قال الحبر الطبري وهو قول محققي علماء الملة سلفا وخلفا، فانظر فيما أتلو عليك. قوله تعالى في خاتمة آية الكرسي (وهو العلي) بعد ما مر من وصفه بالوحدانية والحياة والقيومية، وأن كل شيء فهو له ملكا وملكا، وأنه أحاط بكل شيء علما. وأن السموات والأرض لا يثقل عليه حفظهما ولا يشق عليه. ثم عقب بعد هذا كله بقصر العلو عليه سبحانه. فبربك هل يفهم منه ذو علم إلا علو الاقتدار، وسمو الكمال الذي لا يحد له مقدار كما أشار إليه الشيخ رضي الله عنه؟ وقوله تعالى: {سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى (1) الَّذِي خَلَقَ فَسَوَّى} [الأعلى: 1، 2] فهل هذا العلو الأكمل الواقع بين تسبيح اسمه "], [102, "تعالى معنونا عنه بالربوبية وبين خلقه لكل شيء وتسويته إياه، وتقدير المقدرات وتهيئتها لما خلقت له الخ إلا علو الكمال؟ وهل يفهم منه علو المكان إلا من تسفل عن مقام أهل الفهم والعرفان؟ وأبصر إلى قوله {فَتَعَالَى اللَّهُ الْمَلِكُ الْحَقُّ} [طه: 114] بعد نفى العبث عن ذاته على أبلغ وجه في الآية قبلها ومع التعبير عن ذاته بهذه الأسماء العليا: الله الملك الحق. أيخطر بعقل ذي لب أنه جلوس على عرش وارتفاع مكان؟ حاشا أن يكون ذلك من أفهام العقلاء. ونعوذ بالله من غلبة الوهم على الفهم وتلاعب الهوى بالذهن.\r(بيان أن العلو المعنوي من المجاز الشائع في كلام العرب)\r"]], "pg": [95, 102]}, "526.32": {"x": [[102, "والعلو المعنوي منتشر في القرآن مستفيض في لغة العرب في وصف الخالق والمخلوق على ما يليق بكل {وَلَا تَهِنُوا وَلَا تَحْزَنُوا وَأَنْتُمُ الْأَعْلَوْنَ} [آل عمران: 139] {أَلَّا تَعْلُوا عَلَيَّ وَأْتُونِي مُسْلِمِينَ} [النمل: 31] {إِنَّهُمْ إِنْ يَظْهَرُوا عَلَيْكُمْ يَرْجُمُوكُمْ} [الكهف: 20] والظهور هنا هو العلو {إِنَّ فِرْعَوْنَ عَلَا فِي الْأَرْضِ} [القصص: 4] {وَإِنَّا فَوْقَهُمْ قَاهِرُونَ} [الأعراف: 127] {وَأَنْ لَا تَعْلُوا عَلَى اللَّهِ إِنِّي آتِيكُمْ بِسُلْطَانٍ مُبِينٍ} [الدخان: 19] {وَلِيُتَبِّرُوا مَا عَلَوْا تَتْبِيرًا} [الإسراء: 7] {لَا تَخَفْ إِنَّكَ أَنْتَ الْأَعْلَى} [طه: 68] ولما ذاق المشركون حلاوة النصر المؤقت يوم أحد قال قائلهم (أعل هبل) وهو اسم صنم لهم أجابهم المسلمون عن أمر رسول الله صلى الله عليه وسلم بقولهم: (الله أعلى وأجل) وفي شعر العرب:\rولما علونا واستوينا عليهم. ... تركنا هموا مرعي لنسر وكاسر\rولو ذهبنا نستقصي ما في الكتاب العزيز من ذلك وما في كلام العرب لكان مجلدا، وأين علو المكان من علو السلطان؟ وهل العلو في المكان إلا كمال جسماني عرضي نازل كل النزول عن الكمال الذاتي الأصلي؟ تعالى الله عما يخطر للواهمين. وقال الإمام أبو جعفر في قوله تعالى: {كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ} [القصص: 88] إلا هو. وقال البخاري في "], [103, "جامعه في تفسير سورة القصص {كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ} [القصص: 88] إلا ملكه ويقال: إلا ما أريد به وجه الله. اهـ، فقد حمل الوجه على الملك جازما به. ولا أظن عاقلا يرتاب في أن البخاري من خير السلف. وقال البخاري أيضا في تفسير سورة هود في قوله تعالى {مَا مِنْ دَابَّةٍ إِلَّا هُوَ آخِذٌ بِنَاصِيَتِهَا} [هود: 56] في ملكه وسلطانه. اهـ كلام البخاري رضي الله عنه.\rوقال الله تعالى {وَاللَّهُ وَاسِعٌ عَلِيمٌ} [البقرة: 247] فالسعة المتعارفة عظم امتداد الجسم فهل قال ذلك أحد من السلف؟ حاشاهم من ذلك. واستمع إلى ما قال الإمام الطبري رضي الله عنه قال يقول ((جل ثناؤه: {وَاللَّهُ وَاسِعٌ} [البقرة: 247] الفضل جواد بعطاياه فزوجوا إماءكم فإن الله واسع يوسع عليهم من فضله إن كانوا فقراء (عليم) يقول هو ذو علم بالفقير منهم والغني، لا يخفى عليه حال خلقه في شيء وتدبيرهم اهـ وقال تعالى {وَإِذْ قُلْنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِالنَّاسِ} [الإسراء: 60] وقال في آية أخرى {أَلَا إِنَّهُ بِكُلِّ شَيْءٍ مُحِيطٌ} [فصلت: 54] هل فهم فيه أحد من السلف إلا إحاطة العلم والاقتدار؟ فبينوا المعنى وعينوا. قال الإمام الطبري في تفسير الآية الأولى: يقول جل ثناؤه واذكر يا محمد إذ قلنا لك إن ربك أحاط بالناس قدرة، فهم في قبضته لا يقدرون على الخروج من مشيئته ونحن مانعوك منهم فلا تتهيب منهم أحدا وامض لما تاك به من تبليغ رسالتنا. ثم نقل بأسانيده نحو ذلك عن أحبار المفسرين من التابعين: الحسن ومجاهد وقتادة. وقال في الآية الثانية: يقول تعالى ذكره أَلَا {إِنَّهُ بِكُلِّ شَيْءٍ} [فصلت: 54] مما خلق (محيط) علما بجميعه وقدرته عليه لا يعزب عنه علم شيء منه أراده فيفوته، ولكنه المقتدر عليه العالم بمكانه اهـ وقال تعالى {للَّهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ} [النور: 35] هل فهم أحد من السلف أنه هو ذلك النور الفائض على الحيطان والجدران المنتشر في الجو؟ جل مقام العلماء بالله وكتابه أن يفهموا هذا المعنى الظاهر العامي. قال حبر الأمة ابن عباس فيما رواه عنه الطبري بالسند الصحيح: الله سبحانه هادي أهل السموات والأرض. وروى نحوه عن أنس بن مالك، وروى عن مجاهد أن معناه "], [104, "المدبر، ورجح الإمام الأول وزيف ما عداه، وقد سمعت ما قاله في معنى الإحاطة وأنها مصروفة إلى إحاطة العلم والمشيئة والاقتدار، وليس معناها ما يفهم من إحاطة جسم بجسم والتفافه حوله واشتماله عليه، تعالى الله عن صفات الأجسام وسمات الحدوث. وهكذا لو استقريت أقوال السلف من مظانها لرأيت الكثير الطيب من بيان المعاني اللائقة بالله تعالى على سبيل التعيين، فمن نقل عدم التعيين مطلقا عن السلف فما دقق البحث ولا اتسع اطلاعه. وهذا صحيح البخاري بين أيدينا وتفسير ابن جرير الطبري بين أظهرنا يناديان بما قلنا، وإنما ذكرنا ما ذكرنا لك من ذلك على سبيل التمثيل لندلك بما سمعت على ما لم تسمع، ولا نريد في هذا الوجيز الاستقصاء، وعليك بكتاب الأسماء والصفات للحافظ البيهقي وبمراجعة ما قال العلماء في شروح الأحاديث المشكلة وما نقلوه عن أكابر السلف في ذلك فقد قدمنا لك نقل الإمام أبي بكر بن العربي عن مالك أنه قال في حديث النزول: هو نزول رحمة لا نزول نقلة، ولعله رضي الله عنه لم يبلغه الحديث المفسر له أو لم يستحضره أو بلغه من طريق لا يعتمد عليه، وقد أخرج النسائي في سننه عن أبي هريرة رضي الله عنه رفعه ((إن الله يمهل حتى إذا مضى شطر الليل أمر مناديا أن ينادي ألا من سائل فأعطيه)) الحديث. فتبين به أن إسناد النزول إليه تعالى إسناد مجازي، فالمجاز في الإسناد وليس في الطرف، وليس ذلك بغريب ففي القرآن العزيز {فَإِذَا قَرَأْنَاهُ فَاتَّبِعْ قُرْآنَهُ} [القيامة: 18] والمعنى إذا قرأه عليك جبريل بأمرنا، كما يعلم ذلك من قرأ ما أخرج البخاري عن ابن عباس في بدء الوحي فقد أزيل الاشتباه في الحديث بهذه الرواية كما تزيل الاشتباه في الآية الآية الأخرى، وصح النقل عن حبر الأمة ابن عباس أنه فسر الاستواء بالعلو ولم يفسره بالجلوس. وقد علمت ما قاله الإمام الطبري في معنى العلو، ونقلنا لك عن الذهبي نفسه ما يفيد إجماع علماء الأمصار أنهم يقولون كلهم بلا كيف، وشرحنا معناه بما يزيل عنك الالتباس إن شاء الله تعالى "], [105, "وبعد ــ فقد سبقتنا أساطين العلماء رضي الله عنهم فدونوا في المتشابهات الكتب الكثيرة القيمة بين مطول مفيد ومقل مجيد، فاملأ قلبك بتنزه الله تعالى عن هذه الظواهر الحسية الجسمية، ولا عليك إذا لم تصل إلى المعنى المعين فله أهل، فرد الأمر إلى أهله، ويكفيك هذا القدر، ولا تظن أن ما خفي عليك هو خفي على غيرك من أكابر أهل العلم، فقد قدمنا أنه على قدر الرسوخ في العلم يزول التشابه. وكان الحبر ابن عباس يقول أنا من الراسخين في العلم، يشير إلى أنه زال عنه التشابه وبان له الإحكام في كثير مما تشابه على غيره، فالمتشابهات كلها محكمات بالإضافة إلى رسول الله صلى الله عليه وسلم حتى الحروف المقطعة في أوائل السور، وليس يخفى عليه من علم ذلك إلا ما لا يحتمله الممكن ولا يطيقه المخلوق، وإنما هو مختص بالحق جل شأنه من كنه الذات وحقائق الصفات على ما هي في علم الواجب جل جلاله، فإن ذلك إنما هو من خصائصه جل شأنه، وهذا الأمر مبين في المطولات. والخلاصة أن التشابه أمر نسبي والذي يتضح لنا والله أعلم بمراده بعد الاطلاع على أقوال أحبار المفسرين في قوله تعالى {وَمَا يَعْلَمُ تَأْوِيلَهُ إِلَّا اللَّهُ} [آل عمران: 7] إن الوقف على الجلالة والقصر فيها موجه إلى نفي العلم بالتأويل الحق إلى الذين في قلوبهم زيغ ثم ابتدأ الكلام عن الراسخين في العلم فهم يقولون آمنا به إلى آخر ما حكى الله عنهم، مستبصرين في إيمانهم قد زال عنهم من التشابه على نسبة رسوخهم وسعة اطلاعهم وما أوتوا من النور الإلهي المقتبس من بركة المتابعة للحضرة المصطفوية على صاحبها أفضل الصلاة والسلام، وما منهم من أحد إلا له في العلم مقام معلوم ولا يبلغ الحد الأقصى إلا سيد المصطفين الاخيار وفوق مقامه الأعلى للرب جل جلاله من العلم ما لا يليق إلا به عز وجل، فرحم الله امرأ عرف قدره ولم يتعد طوره، ونسأل الله تعالى أن يجعلنا وإياكم من الذين يستمعون القول فيتبعون أحسنه، وأن يطهر قلوبنا من الزيغ وأن يثبتنا على الجادة حتى نلقاه على صراط مستقيم بجاه نبيه الأمين عليه وعلى آله أفضل الصلاة والسلام. "], [106, "(خاتمة)\r("]], "pg": [102, 106]}, "526.33": {"x": [[106, "نسأل الله حسن الخاتمة)\rاعلم أنه تعالى منذ أنشأ هذا النوع الإنساني لم يزل يتعهده برسله الكرام إقامة لحجته وإظهارا لمحجته، كما قال سبحانه {رُسُلًا مُبَشِّرِينَ وَمُنْذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى اللَّهِ حُجَّةٌ بَعْدَ الرُّسُلِ} [النساء: 165] وكان كل نبي يبعث إلى قومه خاصة وينزل من كتبه ما يناسب استعداد الأمم، حتى إذا أوشك العالم على النهاية واقتربت الساعة وترقى استعداد النوع بعث إلى الناس كافة عربا وعجما بل إنسا وجنا نوره المبين وحجته الكبرى ونعمته العظمى خاتم النبيين وتمام المرسلين سيدنا ومولانا ونبينا محمدا صلى الله عليه وسلم، وأنزل عليه القرآن الحكيم والفرقان العظيم فيه الشريعة العامة الصالحة لكل زمان ومكان، وأيده من آياته بما أظهر صدقه ظهور الشمس وتكفل بحفظ كتابه حتى تبقى حجته ظاهرة إلى أن يرث الله الأرض ومن عليها وهو خير الوارثين، واختار له أصحابا يكفيك في شرفهم أنهم المواجهون بالخطاب في قوله تعالى {كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ} [آل عمران: 110] ولم يخرج عليه الصلاة والسلام من الدنيا حتى أنزل عليه في حجة الوداع يوم عرفة ــ وكان يوم جمعة ــ قوله تعالى {لْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا} [المائدة: 3] وكان قد أوتي جوامع الكلم وهي ما يجمع العلوم الكثيرة في الألفاظ الموجزة القليلة، وذلك ظاهر في كتابه المنزل عليه، وفي نصائحه التي يرشد بها الأمة. ولما اقترب أجله الشريف أكثر من الخطب حتى لقد روى في الصحيح عن عمر وحذيفة رضي الله عنهما ((أنه عليه الصلاة والسلام صلى الصبح ذات يوم ثم قام فيهم خطيبا إلى الظهر، ثم صلى الظهر وعاد إلى خطبته حتى إذا كان العصر صلى العصر وقام خطيبا حتى غاب قرص الشمس. قال حذيفة "], [107, "رضي الله عنه فما ترك من حادثة تكون بين يديه إلى قيام الساعة إلا ذكرها لنا ولا ترك من قائد فتنة يكون معه ثلاثمائة فصاعدا إلا سماه لنا باسمه واسم قبيلته فأعلمنا أحفظنا)) الحديث. فصلى الله وسلم وبارك عليه ما أحرصه على الخير لأمته وإنقاذها من الهلكة، ولقد كان قبل وفاته بنحو شهر في مجلس جامع فجعل يقول: يا أيها الناس سلوني، ويكرر ذلك، فهابوا أن يسألوه فأنزل الله الروح الأمين جبريل صلى الله عليه وسلم فجعل يسأله وطفق صلى الله عليه وسلم يجيبه، وكان في ذلك إجمال الدين كله)). وقد روى هذه القصة البخاري ومسلم في صحيحيهما وغيرهما، وتلخيصها على ما يؤخذ من عدة روايات أنه صلى الله عليه وسلم بعد ما كرر عليهم أن يسألوه وسكتوا إذا هم قد طلع عليهم رجل شديد بياض الثياب، شديد سواد الشعر، لا يرى عليه أثر السفر ولا يعرفه منهم أحد، فوقف على المجلس ونادى. يا رسول الله: السلام عليكم أأدنو؟ فرد عليه السلام وأذن له بالدنو فدنا واستأذن في الجلوس فأذن له فجلس فقال: ما الإيمان؟ فقال هو أن تؤمن بالله وملائكته وكتبه ورسله وبلقائه وتؤمن بالبعث الآخر وتؤمن بالجنة والنار، وبالصراط والميزان، وتؤمن بالقضاء والقدر خيره وشره، حلوه ومره من الله تعالى فقال صدقت، فعجبوا كيف يسأله ويصدقه. ثم قال: ما الإٍسلام؟ قال هو أن تشهد أن لا إله إلا الله وأن محمدا رسول الله وتقيم الصلوات المكتوبة وتؤدي الزكان المفروضة وتصوم رمضان وتحج البيت إن استطعت إليه سبيلا وتعتمر وتغتسل من الجنابة وتسبغ الوضوء. قال فإذا فعلت ذلك فأنا مسلم؟ قال نعم، قال صدقت. ثم قال: ما الإحسان؟ قال: هو أن تعبد الله ــ وفي رواية ــ أن تخشى الله ــ كإنك تراه، فإن لم تكن تراه فإنه يراك)) الحديث، وفي آخره أنه صلى الله عليه وسلم قال لهم: ((أتدرون من هذا؟ قالوا الله ورسول أعلم قال: هذا جبريل جاء يسألني لتتعلموا دينكم)). وما انتقل عليه الصلاة والسلام من الدنيا حتى تركهم على الملة بيضاء نقية ليلها كنهارها، لا يضل عنها إلا هالك. وقد قام أصحابه الكرام بعده خير قيام بما عهد إليهم من نشر العلم "], [108, "وتبليغ الشرع وتعليم السنن حتى كان الكتاب العزيز محفوظ اللفظ معروف المعنى وكانت الدولة بحمد الله لهذه الأمة من أول عهدها، فقاموا بأمر الله وأنفذ الله لهم وعده الصادق في قوله {هوَ الَّذِي أَرْسَلَ رَسُولَهُ بِالْهُدَى وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ} [التوبة: 33] {وَعَدَ اللَّهُ الَّذِينَ آمَنُوا مِنْكُمْ وَعَمِلُوا الصَّالِحَاتِ لَيَسْتَخْلِفَنَّهُمْ فِي الْأَرْضِ كَمَا اسْتَخْلَفَ الَّذِينَ مِنْ قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ الَّذِي ارْتَضَى لَهُمْ} [النور: 55] الآية. وحقق لهم سبحانه قوله رسوله الكريم صلى الله عليه وسلم ((يحمل هذا العلم من كل خلف عدوله)) الحديث. وقد مر في المقدمة متنا وتخريجا، وليعلم المطلع على كتابنا هذا أنا لم نضع فيه حديثا موضوعا ولا شديد الضعف والحمد لله على فضله.\rفقام أولئك السادات جيلا بعد جيل لإظهار الدين وبيان السنن، حتى إذا ظهر خارجي أو تكلم في الدين مبتدع أو تلاعب زنديق قام العلماء رضي الله عنهم بما وجب عليهم من البيان، وكثيرا ما ظاهرهم الحكام بالسيف والسنان فكان هذا الدين بحمد الله في كل عصر ظاهرا جليا، والعلم المنزل في كل أوان واضحا غير خفي، وكان من آثار ذلك أن عرفت الفرق الضالة بآرائها وأسمائها، وهي كما سبق أول الرسالة أقليات إن تقوى بعضها حينا فما أسرع ما يؤيد الله أهل السنة بنصره ويظهر سنة نبيه صلى الله عليه وسلم، وسير أصحابه الكرام والسلف العظام رضي الله عنهم. ولكنا أصبحنا في زمان قد ساد فيه الجهل بما كان قبلنا يعد من بديهيات العلم، وانتشرت الدعوى حتى ادعى الاجتهاد المطلق من لم يكن يصلح في الازمان القريبة منا للجلوس بين طلبة الكتب المتوسطة، فالتبس الحق بالباطل واشتبه على الناس الإيمان بالكفر، والطاعة بالمعصية، حتى إن كثيرا ممن يعدون أنفسهم أو تعدهم العامة من العلماء والمتنورين ليرمون بالكفر من نادى رسول الله مستغيثا أو سأل الله مستشفعا به صلى الله عليه وسلم، وهو يعلم أنه عبد الله ورسوله قد جعله الله منبع كل خير، ومظهر كل بركة، وقرن قضاء الحوائج بذكره والاستشفاع به والصلاة عليه، واتخاذه صلى الله عليه وسلم وسيلة إليه عز وجل، فنرى من النصح لك أيها "], [109, "الأخ في دين الله أن نرجع بك إلى المفزع عن التنازع، وهو الرد إلى كتاب الله تعالى وسنة رسوله فتنظر ما حقيقة الإيمان والإسلام فيهما، وما هي حقيقة العبادة شرعا، ثم نقف بك بين يدي الكتاب والسنة وما عليه أكابر الأمة في هذه المسألة وما يتصل بها، على قدر ما تسعه هذه العجالة، فإذا انتهينا من القول في ذلك أريناك أين نبتت هذه التهويشات. وإلى الله المشتكى وهو المستعان.\r(وصل في معنى الإيمان والإسلام)\r"]], "pg": [106, 109]}, "526.34": {"x": [[109, "الإيمان على ما دل عليه حديث جبريل السابق ويرشد إليه استقراء الكتاب العزيز هو تصديق النبي صلى الله عليه وسلم فيما علم مجيئه به من عند الله علما ظاهر مشتهرا بحيث يشبه ما علم بالضرورة إجمالا فيما علم مجيئه به إجمالا، وتفصيلا في غيره على وجه مخصوص، وهو أن يكون بحيث ترضخ له النفس ولا تأنف من إعلانه وترضى بتبعية هذا الرسول ولا تتكبر عنها، فهو أخص من مطلق التصديق الذي هو المعنى اللغوي، كما هو الشأن في المعاني الشرعية مع المعاني اللغوية، وأخص أيضا من التصديق المنطقي كما لا يخفى، وخرج بالقيد الأخير إيمان أهل الكتاب الذين يعرفونه كما يعرفون أبناءهم وتكبروا عن متابعته، وأنفوا عن الدخول في دينه حسدا وبغيا، وكتموا ما علموا من الحق، فإذا قوى هذا التصديق تفرع عنه التحلي بأداء الأوامر والتخلي عما نهى عنه من الرذائل، فالأعمال الصالحة تكملة ولذلك عطفت عليه في الآيات {وَبَشِّرِ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ} [البقرة: 25] {إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ} [الشعراء: 227] {إنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ كَانَتْ لَهُمْ جَنَّاتُ الْفِرْدَوْسِ نُزُلًا} [الكهف: 107] وهو في القرآن كثير (وإن طائفتان من المؤمنين اقتتلوا) سماهم كما ترى مؤمنين، وقد يطلق على بعض الأعمال مجازا مرسلا من إطلاق اسم السبب على المسبب، كقوله تعالى {وَمَا كَانَ اللَّهُ لِيُضِيعَ إِيمَانَكُمْ} [البقرة: 143] أي صلاتكم كما يعلم من سبب نزولها، وقد يطلق مجازا أيضا على ما يشمل التصديق بالجنان "], [110, "والإقرار باللسان والعمل بالأركان إطلاقا للفظ على جزئي خاص من جزئيات معناه من حيث خصوصه. وهذا الجزئي الخاص هو الفرد الكامل (وهو التصديق المصحوب بما ذكر، وهذا الإطلاق كثير في كلام السلف ردا منهم على المبتدعة القائلين بعدم اعتبار الأعمال أصلا وعدم ضرر المعاصي رأسا، لا قولا منهم بتكفير مرتكب الكبيرة ــ كما هو قول الخوارج ــ ولا قولا بتخليده في النار وإن لم يكن كافرا ولا مؤمنا كما هو قول المعتزلة، فإن السلف والخلف من أهل السنة قالون بأنه لا يخلد في النار إلا الكافر، وبجواز العفو عن مرتكب غير الكفر بشفاعة من ارتضى وبدونها، وأما الإسلام فهو النطق بالشهادتين فإن واطأ فيه القلب اللسان أنجاه دنيا وأخرى من الخلود في عذاب الله، وإلا أجريت عليه الأحكام الدنيوية وكان خالدا مخلدا في عذاب الله أبدا. وهؤلاء هم الذين قيل فيهم {إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الْأَسْفَلِ مِنَ النَّارِ} [النساء: 145] الآية. وبهذا تعلم أن الإسلام المنجى لا ينفك عن الإيمان تحققا، وقد ينفك الإيمان عن الإسلام بالمعنى المذكور كمن صدق بقلبه بما سبق واخترمته المنية قبل التمكن من النطق أو عاجله عارض خرس، وقد يطلق الإسلام على جميع الأعمال الظاهرة المأمور بها وترك المنهيات، وقد يطلق على الدين كله الشامل لجميع الأحكام، وعليه قوله تعالى: {إِنَّ الدِّينَ عِنْدَ اللَّهِ الْإِسْلَامُ} [آل عمران: 19] وكل من الأول والثالث إطلاق على طريق الحقيقة الشرعية، والثاني على سبيل المجاز المرسل. والإسلام إذا أطلق على ما يشمل النطق وغيره فالمراد به الفرد الكامل. والصحيح من أقوال العلماء أن ما عدا النطق والتصديق مكملات له، والتقصير فيه ينقصه ولا يفوته، فإذا فقد التصديق أو ترك النطق كبرا وعنادا فاتت النجاة، والعياذ بالله تعالى. ولهذا المقام بسط وتتميم تجدهما في المطولات.\rفلننتقل بك إلى معنى العبادة شرعا، وأرجو أن تعطي هذا المقام فضل "], [111, "تنبه فإن الغلط فيه هو المزلقة الكبرى والمزلة العظمى، التي استحلت بها دماء لا تحصى وانتهكت بها أعراض لا تعد، وتقاطعت فيها أرحام أمر الله بها أن توصل، عياذا بالله من المزالق والفتن. ولا سيما فتن الشبهات. فاعلم أنهم فسروا العبادة بالإتيان بأقصى غاية الخضوع، وأرادوا بذلك المعنى اللغوي، أما معناها الشرعي فهو أخص من هذا كما يظهر للمحقق الصبار على البحث من استقراء مواردها في الشرع، فإنه الإتيان بأقصى غاية الخضوع قلبا باعتقاد ربوبية المخضوع له، أو قالبا مع ذلك الاعتقاد ــ وأوفيه للتقسيم ــ فإن انتفى ذلك الاعتقاد لم يكن ما أتى به من الخضوع الظاهري من العبادة شرعا في كثير ولا قليل مهما كان المأتى به ولو سجودا. ومثل اعتقاد الربوبية اعتقاد خصيصة من خصائصها كالاستقلال بالنفع والضر، وكنفوذ المشيئة لا محالة ولو بطريق الشفاعة لعابده عند الرب الذي هو أكبر من هذا المعبود. وإنما كفر المشركون بسجودهم لأوثانهم ودعائهم إياهم وغيرهما من أنواع الخضوع لنحقق هذا القيد فيهم، وهو اعتقادهم ربوبية ما خضعوا له، أو خاصة من خواصها كما سيأتيك تفصيله. ولا يصح أن يكون السجود لغير الله فضلا عما دونه من أنواع الخضوع بدون هذا الاعتقاد عبادة شرعا، فانه حينئذ يكون كفرا، وما هو كفر فلا يختلف باختلاف الشرائع، ولا بأمر الله عز وجل به {قُلْ إِنَّ اللَّهَ لَا يَأْمُرُ بِالْفَحْشَاءِ} [الأعراف: 28] {وَلَا يَرْضَى لِعِبَادِهِ الْكُفْرَ} [الزمر: 7] وذلك ظاهر إن شاء الله. وها أنت ذا تسمع الله تعالى قد قال للملائكة: {اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ أَبَى وَاسْتَكْبَرَ} [البقرة: 34] وقال: {أَنَا خَيْرٌ مِنْهُ} [الأعراف: 12]. وقال: {أَأَسْجُدُ لِمَنْ خَلَقْتَ طِينًا} [الإسراء: 61]. والقول بأن آدم كان قبلة قول لا يرضاه التحقيق ويرفضه التدقيق في فهم الآيات كما ينبغي أن تفهم، فإن قصر فهمك عن هذا فهذا نبي الله يعقوب وامرأته وأولاده الأحد عشر قال الله فيهم {وَخَرُّوا لَهُ سُجَّدًا} [يوسف: 100] أي ليوسف صلى الله عليه وسلم. قال الحافظ ابن كثير في تفسيرها: ((أي سجد له أبواه وإخوته الباقون وكانوا أحد عشر رجلا، وقد كان هذا سائغا في شرائعهم إذا سلموا على "], [112, "الكبير يسجدون له. ولم يزل هذا جائزا من لدن آدم إلى شريعة عيسى عليه السلام، فحرم هذا في هذه الملة، وجعل السجود مختصا بجناب الرب تعالى. هذا مضمون قول قتادة وغيره. وفي الحديث ((أن معاذا قدم الشام فوجدهم يسجدون لأساقفتهم فلما رجع سجد لرسول الله صلى الله عليه وسلم، فقال: ما هذا يا معاذ؟ فقال: إني رأيتهم يسجدون لأساقفتهم وأنت أحق أن يسجد لك. قال: لو كنت آمرا أحدا أن يسجد لأحد لأمرت المرأة أن تسجد لزوجها من عظم حقه عليها)). وفي حديث آخر ((أن سلمان لقي النبي صلى الله عليه وسلم في بعض طرق المدينة ــ وكان سلمان حديث عهد بالإسلام ــ فسجد للنبي صلى الله عليه وسلم فقال: لا تسجد لي يا سلمان واسجد للحي الذي لا يموت)) والغرض أن هذا كان جائزا في شريعتهم اهـ. وقال الإمام أبو جعفر في تفسيرها نحوا من هذا. وقد علمت أن ما هو كفر لا يختلف باختلاف الشرائع ولا يأمر الله به في حين من الأحيان. فلم يكن سجود الملائكة لآدم ولا السجود ليوسف عليهما الصلاة والسلام مع خلو الساجدين من اعتقاد خصيصة من خصائص الربوبية بمن سجدوا له كفرا، بل هو من الملائكة عبادة لله الذي أمرهم سبحانه، وممن سجد ليوسف تحية جائزة، ونسخ الجواز في شريعتنا، وإنما حكم العلماء بالكفر على من سجد لشمس أو قمر أو وثن من أجل أنه أمارة على الكفر الذي هو إنكار ما علم من الدين بالضرورة كما حكموا بالإيمان ــ وهو معنى قلبي كما علمت ــ لمن نطق بالشهادتين من أجل أنه دليل عليه، لا لأن الأول بمجرده كفر والثاني بمجرده إيمان. فإن تعسر عليك فهم هذا وهو ليس بعسير إن شاء الله تعالى، فانظر إلى نفسك فإنه قد يقضى عليك أدبك مع أبيك واحترامك له أن لا تسمح بالجلوس أو الاضطجاع بين يديه، فتقف أو تقعد ساعة أو فوقها، ولا يكون ذلك منك عبادة له، لماذا؟ لأنه لم يقارن هذا الفعل منك اعتقاد شيء من خصائص الربوبية فيه. وتقف في الصلاة قدر الفاتحة وتجلس فيها قدر التشهد وهو قدر دقيقة أو "], [113, "دقيقتين فيكون ذلك منك عبادة لمن صليت له، وسر ذلك هو أن هذا الخضوع الممثل في قيامك وقعودك يقارنه اعتقادك الربوبية لمن خضعت له عز وجل. وتدعو رئيسك في عمل من الأعمال أو أميرك أن ينصرك على باغ عليك أو يغيثك من أزمة نزلت بك وأنت معتقد فيه أنه لا يستقل بجلب نفع أو دفع ضر، ولكن الله جعله سببا في مجرى العادة يقضى على يديه من ذلك ما يشاء فضلا منه سبحانه، فلا يكون ذلك منك عبادة لهذا المدعو وأنت على ما وصفنا، فإن دعوته وأنت تعتقد فيه أنه مستقل بالنفع أو الضر أو نافذ المشيئة مع الله لا محالة، كنت له بذلك الدعاء عابدا، وبهذه العبادة أشركته مع الله عز وجل، لأنك قد اعتقدت فيه خصيصة من خصائص الربوبية، فإن الاستقلال بالجلب أو الدفع ونفوذ المشيئة لا محالة هو من خصائص الربوبية، والمشركون إنما كفروا بسجودهم لأصنامهم ونحوه لاعتقادهم فيها الاستقلال بالنفع أو الضر ونفوذ مشيئتهم لا محالة مع الله تعالى، ولو على سبيل الشفاعة عنده، فإنهم يعتبر ونه الرب الأكبر ولمعبوداتهم ربوبية دون ربوبيته، وبمقتضى ما لهم من الربوبية وجب لهم نفوذ المشيئة معه لا محالة. ويدل لما قلنا آيات كثيرة كقوله تعالى (أم من هذا الذي هو جند لكم ينصركم من دون الرحمن؟ إن الكافرون إلا في غرور) وقوله {أَمْ لَهُمْ آلِهَةٌ تَمْنَعُهُمْ مِنْ دُونِنَا لَا يَسْتَطِيعُونَ نَصْرَ أَنْفُسِهِمْ وَلَا هُمْ مِنَّا يُصْحَبُونَ} [الأنبياء: 43] والاستفهام في الآيتين إنكاري على سبيل التوبيخ لهم على ما اعتقدوه. وحكى الله عن قوم هود قولهم له عليه السلام {إِنْ نَقُولُ إِلَّا اعْتَرَاكَ بَعْضُ آلِهَتِنَا بِسُوءٍ} [هود: 54] وقوله لهم {فَكِيدُونِي جَمِيعًا ثُمَّ لَا تُنْظِرُونِ (55) إِنِّي تَوَكَّلْتُ عَلَى اللَّهِ رَبِّي وَرَبِّكُمْ} [هود: 55، 56] الآية وكقوله تعالى موبخا لهم يوم القيامة على ما اعتقدوه لها من الاستقلال بالنفع ووجوب نفوذ مشيئتها {أَيْنَ مَا كُنْتُمْ تَعْبُدُونَ (92) مِنْ دُونِ اللَّهِ هَلْ يَنْصُرُونَكُمْ أَوْ يَنْتَصِرُونَ} [الشعراء: 92، 93] وقولهم وهم في النار يختصمون يخاطبون من اعتقدوا فيهم الربوبية وخصائصها {تَاللَّهِ إِنْ كُنَّا لَفِي ضَلَالٍ مُبِينٍ (97) إِذْ نُسَوِّيكُمْ بِرَبِّ الْعَالَمِينَ} [الشعراء: 97، 98] "], [114, "فانظر إلى هذه التسوية التي اعترفوا بها حيث يصدق الكذوب، ويندم المجرم حين لا ينفعه ندم. فإن التسوية المذكورة إن كانت في إثبات شيء من صفات الربوبية فهو المطلوب، ومن هذه الحيثية شركهم وكفرهم، لأن صفاته تعالى تجب لها الوحدانية بمعنى عدم وجود نظير لها في سواه عز وجل، كما مر مفصلا في المقصد. وإن كانت التسوية في استحقاقها للعبادة فهو يستلزم اعتقاد الاشتراك فيها به الاستحقاق، وهو صفات الألوهية أو بعضها، وإن كانت في العبادة نفسها فهي لا تكون من العاقل إلا لمن يعتقد استحقاقه لها كرب العالمين، تعالى الله عما يشركون. وكيف ينفى عنهم اعتقاد الربوبية بآلهتهم وقد اتخذوها أندادا وأحبوها كحب الله كما قال تعالى فيهم {وَمِنَ النَّاسِ مَنْ يَتَّخِذُ مِنْ دُونِ اللَّهِ أَنْدَادًا يُحِبُّونَهُمْ كَحُبِّ اللَّهِ} [البقرة: 165] والأنداد جمع ند وهو على ما قاله أهل التفسير واللغة المثل المناوي، فهذا ينادي عليهم أنهم اعتقدوا فيها ضربا من المقاومة للحق تعالى عما يقولون. أما قوله تعالى فيهم: {وَلَئِنْ سَأَلْتَهُمْ مَنْ خَلَقَهُمْ لَيَقُولُنَّ اللَّهُ} [الزخرف: 87] ونحوه فليس معناه أنهم لا يثبتون لآلهتهم ربوبية ولا خاصة من خواصها، بل معناه أنهم إذا نوقشوا اعترفوا بالحق الذي فطر الله عليه النفوس، ودلت عليه الكائنات، ثم ما أصرع ما يرجعون إلى اعتقاد الربوبية الباطلة آلهتهم، فينتكسون ويرتكسون كما قال عنهم في آية أخرى: {يَعْرِفُونَ نِعْمَتَ اللَّهِ ثُمَّ يُنْكِرُونَهَا وَأَكْثَرُهُمُ الْكَافِرُونَ} [النحل: 83] وكقوله تعالى في طائفة منهم {كُلَّ مَا رُدُّوا إِلَى الْفِتْنَةِ أُرْكِسُوا فِيهَا} [النساء: 91] وليس ذلك بعجيب ممن اتخذ إلهه هواه وإنك لتشاهد بين أهل الأهواء من تناقشه في بدعته ويصغي إليك فيقتنع بالحجة وقت المناقشة ويعترف بمخالفته للحق وتظهر فيه مخايل الإنصاف، فإذا انقضى المجلس عاد إلى ما ألف من الهوى، وارتكس في بدعته كأن لم يكن بينك وبينه نقاش ــ إلا من رحم الله ــ وقد رأينا ذلك كثيرا في كثير ممن لقينا من أهل الأهواء ــ نسأل الله العافية بفضله ــ على أنه لو سلم أنهم لم يعتقدوا "], [115, "لآلهتهم خلقا ولا رزقا ولا تدبيرا للأمر، فهم يعتقدون فيها غير ذلك من خصائص الألوهية وهو وجوب نفوذ مشيئتها، فإنهم يرون أن شفاعتها مقبولة لا ترد وليست متوقفة على إذنه تعالى عما يقول الجاهلون به علوا كبيرا. ولذلك قال الله تعالى في سيدة آي القرآن ردا على هذا الزعم {مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ} [البقرة: 255] قال القاضي ناصر الدين البيضاوي في تفسيرها: بيان لكبرياء شأنه ولأنه لا أحد يساويه أو يدانيه يستقل بأن يدفع ما يريده شفاعة واستكانة فضلا أن يعارضه عنادا ومناصبة. أهـ. فانظر إلى قوله ((يستقل بأن يدفع ما يريده شفاعة)) تجده صريحا في اعتقاد وجوب مشيئتها معه عز وجل، ووجوب نفوذ المشيئة من خصائص الربوبية كما لا يخفى. وهذا النوع من الشفاعة هو الشفاعة الشركية وهي التي أبطلها القرآن، فإن اعتقادها كفر، كما قال تعالى، {أَمِ اتَّخَذُوا مِنْ دُونِ اللَّهِ شُفَعَاءَ} [الزمر: 43] الآيتين. فانظر إلى قوله {مِنْ دُونِ اللَّهِ} [البقرة: 23] وكما قال الله تعالى {قُلْ مَنْ ذَا الَّذِي يَعْصِمُكُمْ مِنَ اللَّهِ إِنْ أَرَادَ بِكُمْ سُوءًا أَوْ أَرَادَ بِكُمْ رَحْمَةً} [الأحزاب: 17] أما الشفاعة التي يعتقدها أهل التوحيد وجاء بها الكتاب والسنة فهي بعيدة من هذا بعد الإيمان عن الكفر والنور عن الظلمة، وهي دعاء الشافع للمشفوع فيه فيستجيب بفضله لمن شاء، وهو معنى الاستثناء في قوله تعالى {إِلَّا بِإِذْنِهِ} [البقرة: 255] والمراد هنا بالإذن الرضا كما قال في الآية الأخرى {وَلَا يَشْفَعُونَ إِلَّا لِمَنِ ارْتَضَى} [الأنبياء: 28] وكقوله: {وَكَمْ مِنْ مَلَكٍ فِي السَّمَاوَاتِ لَا تُغْنِي شَفَاعَتُهُمْ شَيْئًا إِلَّا مِنْ بَعْدِ أَنْ يَأْذَنَ اللَّهُ لِمَنْ يَشَاءُ وَيَرْضَى} [النجم: 26] وبهذا يتبين لك الفرق بين ما أثبته القرآن من الشفاعة وبين ما نفاه منها، وهو ما كان بغير إذنه ورضاه، جل أن يكون في ملكه إلا ما يشاء، أما الشفاعة بإذنه ورضاه من عباده المصطفين الأخيار لعصاة الموحدين فهي جائزة بل واقعة لثبوتها بالتواتر وليس فيها محذور، واعتقادها من الدين، فإنها من باب الدعاء وهو تعالى يستجيب الذين آمنوا وعملوا الصالحات ويزيدهم من فضله. وعسى أن يكون قد وضح لك إن شاء الله ما هو معنى العبادة شرعا، وحينئذ تعلم أنه ليس "], [116, "من عبادة غير الله في شيء أن يبتغي المسلم إلى الله الوسيلة، فلننقل الكلام إلى ما كان عليه النبي صلى الله عليه وسلم وأصحابه الكرام ومن تبعهم بإحسان من العلماء سلفا وخلفا في ابتغاء الوسيلة فنقول وبالله التوفيق وعليه الاعتماد لا رب غيره. قال تعالى: {يَاأَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَابْتَغُوا إِلَيْهِ الْوَسِيلَةَ} [المائدة: 35] وهي كل ما جعله الله سببا في الزلفى عنده، ووصلة إلى قضاء الحوائج منه، واتخاذ الوسيلة يسمى توسلا، والتوسل إليه تعالى إما بأسمائه وصفاته وهو ثابت من فعله صلى الله عليه وسلم مروي في السنن والمسانيد، غني بشهرته عن ذكر شواهده في هذا المختصر، داخل في الآية الكريمة. وإما بالأعمال الصالحة المأمور بها شرعا، وإما بالذوات المرضية عنده من الأنبياء والملائكة والصالحين ثم التوسل بالعمل المأمور به على قسمين (أحدهما): فعله والاتيان به على الوجه الذي أمر به من أداء شرائطه وأركانه وآدابه وتجنب ما يفسده أو يخل به توسلا بذلك إلى قربه سبحانه ورضاه والفوز بما وعد به عباده الصالحين فضلا منه ورحمة. ولا خفاء في أن هذا النوع من التوسل هو ما عليه النبيون والمرسلون والملائكة المقربون وجميع عباد الله الصالحين، ولا ينكره إلا خارج على الأديان السماوية والكتب المنزلة، وهو من أول ما تشمله الآية الكريمة. والقسم الثاني أن يدعو الله بعمله إذا وقع في شدة كما وقع للثلاثة الذين آواهم المبيت إلى غار فسال السيل فألقى على الغار صخرة سدت فمه فصاروا لا يستطيعون الخروج، فقال بعضهم لبعض: يا هؤلاء إنه لا ينجيكم مما أنتم فيه إلا أن تدعوا الله تعالى بصالح ما عملتم عسى أن يفرج الله عنكم ما نزل بكم، فدعا كل منهم بصالح ما يرجو قبوله من عمله، فحقق الله رجاءهم وفرج كربتهم بفضله وليس هذا من القسم الأول كما لا يخفى، فانهم في الغار لم يعملوا هذه الأعمال بل دعوا بما عملوا، فكان ما نالوا من الفرج ليس مسببا عن العمل نفسه بل عن الدعاء متشفعين إلى الله به. وحديث قصتهم صحيح بل مشهور مستفيض أخرجه البخاري في صحيحه وغيره من الأئمة، فالآية الكريمة تشمله أيضا. "], [117, "وأما التوسل بالذوات الفاضلة النبي صلى الله عليه وسلم فمن دونه من المرضيين عنده تعالى فمهو على ثلاثة أنواع نذكر منها، (النوع الأول) أن يسأل الله مستشفعا بهم كأن يقول: اللهم إني أسألك بنبيك محمد أو أتوجه إليك به أو أتوسل أو أتشفع به أو بجاهه أو بقدره أو بحرمته أو بحقه، ويريد من الحق ما تفضل الله به عليه من الكرامة وعلو المنزلة لديه، أو بالأنبياء والملائكة والصالحين، فقد وردت به الأحاديث الصحاح فتعمه الآية الكريمة، وهو من فعل النبي صلى الله عليه وسلم والصحابة والتابعين لهم بإحسان، قبل وجود المتوسل به في حياته الدنيا وبعده في أثنائها وفي حياته في البرزخ: أخرج البيهقي في دلائل النبوة وهو الكتاب الذي قال فيه الذهبي: عليك به فكله هدى ونور، والطبراني في المعجم الصغير، والحاكم في مستدركه على الصحيحين أو أحدهما عن عمر بن الخطاب رضي الله عنه قال قال رسول الله صلى الله عليه وسلم: ((لما اقترف آدم عليه السلام الخطيئة قال يا رب أسألك بحق محمد لما غفرت لي، فقال الله يا آدم وكيف عرفت محمدا ولم أخلقه؟ قال يا رب لأنك لما خلقتني بيدك ونفخت في من روحك رفعت رأسي فرأيت على قوائم العرش مكتوبا لا إله إلا الله محمد رسول الله، فعرفت أنك لم تضف إلى اسمك إلا أحب الخلق إليك، فقال الله صدقت يا آدم إنه لأحب الخلق إلى إذ سألتني بحقه فقد غفرت لك. ولولا محمد ما خلقتك اهـ ولفظ الطبراني في المعجم: ((إلا غفرت لي)) بدل ((لما)) وهو بمعناه، وفيه أن آدم عليه السلام قال: تبارك اسمك لما خلقتني رفعت رأسي إلى عرشك فإذا فيه مكتوب لا إله إلا الله محمد رسول الله فعلمت أنه ليس أحد أعظم قدرا ممن جعلت اسمه مع اسمك، فأوحى الله عز وجل إليه يا آدم إنه آخر النبيين من ذريتك وإن أمته آخر الأمم من ذريتك ولولاه يا آدم ما خلقتك. قال الحاكم هذا حديث صحيح الإسناد وهو أول حديث ذكرته لعبد الرحمن بن زيد بن أسلم في هذا الكتاب. وذكر الحاكم مع هذا الحديث أثرا عن ابن عباس وصححه: ((أوحى الله إلى عيسى عليه السلام يا عيسى "], [118, "آمن بمحمد وأمر من أدركه من أمتك أن يؤمنوا به، فلولا محمد ما خلقت آدم، ولولاه ما خلقت الجنة والنار. ولقد خلقت العرش على الماء فاضطرب فكتبت عليه لا إله الله محمد رسول الله فسكن)) ورواه كذلك أبو الشيخ في طبقات الأصفهانيين وأقره السبكي في شفاء السقام، والبلقيني في فتاويه، ومثله لا يقال رأيا فحكمه الرفع. ذكره الزرقاني في شرح المواهب. وفي هذا الأثر أن الله تبارك وتعالى قد جعل في اسمه البركة فما الظن بمسماه صلى الله عليه وسلم. وقد تعقب الذهبي وتبعه ابن تيمية فحكم بوضع هذا الحديث من أجل عبد الرحمن بن زيد أحد رواته، وقد جازف في هذا الحكم كعادتهم فيما لم يوافق أهواءهم، فإن عبد الرحمن بن زيد لم يتهمه أحد من النقدة بالوضع وإنما طعن فيه لسوء حفظه وغفلته مع قول الكثير غيه إن عبد الرحمن صالح في نفسه وهو من رجال الترمذي، وقال فيه ابن عدي له أحاديث حسان وهو ممن احتمله الناس وصدقه بعضهم وهو ممن يكتب حديثه، وقال أبو حاتم الرازي هو أحب إلى من ابن أبي الرجال، وقد علم أهل الخبرة بهذا الفن أن الرجل يكون فيه سوء الغلط والغفلة في سن دون سن، وفي الرواية عن رجل دون رجل. وعبد الرحمن قد روى هذا الحديث عن أبيه والرجل في الرواية عن أبيه أبعد عن الغلط وأقرب إلى الضبط، ولعل هذا من القرائن التي قامت عند الحاكم كم على القول بتصحيح حديث عبد الرحمن هذا، وقد سمعت قول ابن عدي فيه: إن له أحاديث حسانا فلا يبعد إذن تصحيح الحاكم لهذا الحديث كما لا يخفى. وقد روى القاضي عياض بالسند الصحيح إلى الإمام مالك أن أبا جعفر المنصور استغناء في استقبال رسول الله صلى الله عليه وسلم وقت الدعاء عند الزيارة الشريفة. قال وما لك لا تستقبله وهو وسيلتك ووسيلة أبيك آدم. وما أبدع ما قال العلامة المحقق الألوسي في تفسيره في قوله تعالى {فَتَلَقَّى آدَمُ مِنْ رَبِّهِ كَلِمَاتٍ} [البقرة: 37] بعد أن ذكر وجهين في تفسير (كلمات): ((وقيل رأى مكتوبا على ساق العرش محمد رسول الله فتشفع به. وإذا أطلقت الكلمة على عيسى عليه السلام فلتطلق الكلمات على الروح "], [119, "الأعظم والحبيب الأكرم صلى الله عليه وسلم فما عيسى بل وما موسى بل وما وما إلا بعض من ظهور أنواره وزهرة من رياض أنواره اهـ. وكأنه لم يطلع على حديث الحاكم وهذا الأثر فحكاه بقيل، أو أن ذلك من زيادة ابنه السيد لعمان عفا الله عنه فقد حدثنا الثقة أنه زاد في تفسير والده شيئا مما يوافق أهواء ابن تيمية\rوأخرج الحاكم في المستدرك والبيهقي في الدلائل من طريق عبد الملك بن هارون عن ابن عباس وله طريق أخرى عن عطاء عن الضحاك عن الحبر رضي الله عنه أخرجه منها أبو نعيم في الدلائل أن يهود كانوا إذا قاتلوا غطفان وأسد وغيرهما من مشركي العرب من قبل أن يبعث محمد صلى الله عليه وسلم يستفتحون الله يدعون على الذين كفروا يقولون: اللهم إنا نستنصرك بحق النبي الأمي إلا نصرتنا عليهم فينصرون {فَلَمَّا جَاءَهُمْ مَا عَرَفُوا} [البقرة: 89] يريد محمدا صلى الله عليه وسلم ولم يشكوا فيه (كفروا به) قال العلامة المحدث الشريف الحسني عبد الله بن محمد بن الصديق العماري في كتابه الذي سماه ((إنحاف الأذكياء بما ورد في التوسل بسيد الأنبياء وغيره من الصالحين والأولياء)) ووجه الدليل من هذا الأثر ظاهر فان الله تعالى أقرهم على توسلهم بالنبي صلى الله عليه وسلم ولم يذمهم عليه. وإنما ذمهم على جحودهم وكفرهم به بعد ما شاهدوا من بركة التوسل به ما لا ينكره إلا من كان مثلهم أعمى القلب والبصيرة عافانا الله من ذلك بحق نبيه. اهـ، وأخرج الترمذي في جامعه وصححه والحاكم في المستدرك وصححه وأقره الذهبي والبيهقي في الدلائل وصححه وغيرهم عن عثمان بن حنيف ــ بالتصغير ــ أن رجلا ضريرا أتى النبي صلى الله عليه وسلم فقال: ادع الله أن يعافيني قال إن شئت دعوت وإن شئت صبرت فهو خير لك. فقال يا رسول الله ليس لي قائد وقد شق على فادعه، فأمره أن يتوضأ فيحسن وضوءه ويصلى ركعتين ثم يدعو بهذا الدعاء: اللهم إني أسألك وأتوجه إليك بنبيك محمد نبي الرحمة يا محمد إني أتوجه بك إلى ربي في حاجتي هذه لتقضي لي، اللهم فشفعه في - أي اقبل تشفعي به ــ قال عثمان بن حنيف فوالله ما تفرقنا ولا طال بنا الحديث حتى دخل الرجل وقد "], [120, "أبصر كأنه لم يكن به ضر)) وأخرج أبو نعيم في المعرفة والديلمي في مسند الفردوس عن ابن عباس بسند قال السيوطي هو حسن والطبراني واللفظ له في معجميه الكبير والأوسط بسند قال فيه نور الدين الهيثمي في كتابه مجمع الزوائد رجاله رجال الصحيح إلا واحدا وثقه الحاكم وابن حبان. قال وفيه ضعف، قلت: ولكنه قد جبر بروايته من عدة طرق عن أنس بن مالك رضي الله عنه قال: ((لما ماتت فاطمة بنت أسد أم علي رضي الله عنهما دخل عليها رسول الله صلى الله عليه وسلم فجلس عند رأسها فقال رحمك الله يا أمي، كنت أمي بعد أمي تجوعين وتشبعينني، وتعرين وتكسينني وتمنعين نفسك طيبا وتطعمينني، تريدين بذلك وجه الله والدار الآخرة ثم أمر أن تغسل ثلاثا ثلاثا. فلما بلغ الماء الذي فيه الكافور سكبه رسول الله صلى الله عليه وسلم بيده ثم خلع رسول الله صلى الله عليه وسلم قميصه فألبسها إياه وكفنها ببرد فوقها، ثم دعا رسول الله صلى الله عليه وسلم أسامة بن زيد وأبا أيوب الأنصاري وعمر بن الخطاب وغلاما أسود يحفرون فحفروا قبرها، فلما بلغوا اللحد حفره رسول الله صلى الله عليه وسلم بيده وأخرج ترابه بيده، فلما فرغ دخل رسول الله صلى الله عليه وسلم فاضطجع فيه، وقال: الله الذي يحيي ويميت وهو حي لا يموت اغفر لأمي فاطمة بنت أسد ولقنها حجتها ووسع عليها مدخلها بحق نبيك والأنبياء الذين من قبلي فإنك أرحم الراحمين، وكبر عليها أربعا وأدخلها اللحد هو والعباس وأبو بكر الصديق رضي الله عنهما)): وأخرج الطبراني في معجميه الكبير والصغير بسنده عن عثمان بن حنيف أن رجلا كان يختلف إلى عثمان بن عفان رضي الله عنه في حاجة له فكان عثمان لا يلتفت إليه ولا ينظر في حاجته فلقي ابن حنيف فشكا إليه ذلك فقال له عثمان بن حنيف إيت الميضأة فتوضأ ثم ائت المسجد فصل فيه ركعتين ثم قل: ((اللهم إني أسألك وأتوجه إليك بنبينا محمد نبي الرحمة يا محمد إني أتوجه بك إلى ربك فيقضي حاجتي ــ وتذكر حاجتك ــ ورح حتى أروح معك، فانطلق الرجل فصنع ما قال له ثم أتى باب عثمان بن عفان رضي الله عنه فجاء البواب حتى أخذ بيده فأدخله على عثمان بن عفان فأجلسه على "], [121, "الطنفسة فقال ما حاجتك؟ فذكر حاجته وقضاها له، ثم قال له ما ذكرت حاجتك حتى كان الساعة. وقال ما كانت لك من حاجة فاذكرها، ثم إن الرجل خرج من عنده فلقي عثمان بن حنيف فقال له جزاك الله خيرا ما كان ينظر في حاجتي ولا يلتفت إلي حتى كلمته في، فقال عثمان بن حنيف والله ما كلمته ولكن شهدت رسول الله صلى الله عليه وسلم وأتاه ضرير فشكا إليه ذهاب بصره. وساق القصة المتقدمة في حديث الترمذي الذي سبق قريبا. ثم قال والحديث صحيح وقال العلامة المحث عبد الله بن محمد في كتابه السابق لم ينص في معاجمه على تصحيح حديث غير هذا الحديث وأقره على هذا التصحيح الحافظان زكي الدين المنذري ونور الدين الهيثمي اهـ. وأخرج الإمام أحمد والحافظ ابن خزيمة والطبراني في الدعاء وأبو نعيم الأصبهاني وابن ماجه واللفظ له عن أبي سعيد الخدري قال قال رسول الله صلى الله عليه وسلم ((من خرج من بيته إلى الصلاة فقال اللهم إني أسألك بحق السائلين عليك وأسألك بحق ممشاي هذا فإني لم أخرج أشرا ولا بطرا ولا رياء ولا سمعة وخرجت اتقاء سخطك وابتغاء مرضاتك، فأسألك أن تعيذني من النار، وأن تغفر لي ذنوبي إنه لا يغفر الذنوب إلا أنت، أقبل الله عليه بوجهه واستغفر له سبعون ألف ملك)) قال الحافظ العراقي في المغني في هذا الحديث: إنه حسن وأخرجه ابن السني في عمل اليوم والليلة عن بلال مؤذن رسول الله صلى الله عليه وسلم قال ((كان النبي صلى الله عليه وسلم إذا خرج إلى الصلاة قال بسم الله آمنت بالله توكلت على الله لا حول ولا قوة إلا بالله، اللهم إني أسألك بحق السائلين عليك)) الحديث إلا أنه قال مخرجي بدل ممشاي، وقال بعد أن تعيذني من النار وتدخلني الجنة. قال السيد محمد مرتض الزبيدي في شرحه للأحياء في تفسير السائلين: هم المتضرعون إلى الله بخالص طوياتهم، وهذا أخص أوصاف الأولياء والصالحين رضي الله عنهم ونفعنا بهم. أهـ. وكفى بهذه الأحاديث حجة على عمل بهذا النوع وشمول الآية الكريمة له لمن أنصف. والنوع الثاني من التوسل بأهل الفضل هو أن يطلب المتوسل من المتوسل به أن "], [122, "يشفع إلى الله في حوائجه بأن يدعو الله له في قضائها، فإنه لا معن للشفاعة عند الموحدين إلا هذا. والنوع الثالث هو أن يطلب نفس الحوائج منه وهو يريد أن يتسبب في قضائها من الله تعالى بشفاعته فيها عند الله سبحانه ودعائه ربه في قضائها للمتوسل، فيرجع إلى النوع الثاني كما لا يخفى. وظاهر أن كلا النوعين لا يتصور إلا بعد وجود المتوسل به وكل منهما ثابت من فعل الصحابة معه صلى الله عليه وسلم في حياته الدنيا وبعد وفاته في حياته في البرزخ، فلا وجه لإخراجهما من الآية الكريمة، أما ما كان منهم معه في حياته الدنيا صلى الله عليه وعليهم فهو مشهور مستفيض بل متواتر امتلأت به كتب الأحاديث كلها، لا يرتاب فيه سني ولا مبتدع، وقد كانوا رضي الله عنهم يفزعون إليه عند النوائب ولا بأس بذكر شيء من ذلك تبركا. أخرج البخاري في أبواب الاستقاء من صحيحه عن أنس بن مالك رضي الله عنه من طرق قال ((بينما النبي صلى الله عليه وسلم يخطب يوم الجمعة إذ دخل رجل من باب المسجد فاستقبل النبي صلى الله عليه وسلم قائما فنادى يا رسول الله هلكت الأموال وانقطعت السبل فادع الله يغيثنا، فرفع يديه صلى الله عليه وسلم فقال: اللهم أغثنا، ثلاثا. قال أنس: ولا والله ما نزى في السماء من سحاب فمطرتنا يومنا هذا والذي يليه إلى الجمعة الأخرى، فجاء ذلك الرجل أو غيره وقال يا رسول الله تهدمت البيوت وتقطعت السبل وهلكت المواشي، فرفع يديه صلى الله عليه وسلم وقال: اللهم حوالينا ولا علينا، وجعل يشير بيده فلا يشير إلى ناحية إلا انجاب عنها السحاب، وخرجنا نمشي في الشمس)). وأخرجه مسلم وفيه ((فجعلت تمطر حول المدينة ولا تمطر بالمدينة قطرة، فنظرت إلى المدينة وإنها لمثل الكليل)). وأخرج البيهقي في الدلائل أن أعرابيا جاء إلى النبي صلى الله عليه وسلم فقال يا رسول الله أتيناك وما لنا بعير يئط ولا صبي يغط ثم أنشده شعرا يقول فيه:\rأتيناك والعذراء يدمى لبانيها ... وقد شغلت أم الصبي عن الطفل\rإلى أن قال "], [123, "وليس لنا إلا إليك فرارنا ... وأين فرار الناس إلا إلى الرسل\rفقام يجر رداءه حتى صعد المنبر فرفع يديه فقال: اللهم اسقنا. وذكر دعاء إلى أن قال: فما رد النبي صلى الله عليه وسلم يده حتى ألقت السماء بأرواقها، وجاء الناس يضجون الغرق الغرق. فقال النبي صلى الله عليه وسلم ((حوالينا ولا علينا)) فانجاب السحاب عن المدينة وضحك النبي صلى الله عليه وسلم حتى بدت نواجذه. ثم قال لله در أبي طالب، لو كان حيا قرت عيناه. من ينشدنا قوله، فقال علي بن أبي طالب رضي الله عنه يا رسول الله كأنك تريد قوله:\rوأبيض يستسقى الغمام بوجهه ... تمال اليتامى عصمة للأرامل\rيطوف به الهلاك من آل هاشم ... فهم عنده في نعمة وتواصل\rوقوله (يئط) بفتح فكسر وطاء مشددة من الأطيط وهو هنا صوت البعير من نقل الحمل. ويغط كيئط، من الغطيط وهو صوت النائم، والكلام كناية عن شدة الفقر والجوع والقحط. ويدمى كيسعي واللبان بالفتح ــ الصدر، وهو كناية عن الجهد، وأرواق السحاب مياهها الصافية جمع روق بفتح فسكون. وأخرج البخاري عن عبد الله بن مسعود أن قريشا أبطؤوا عن الإسلام فدعا عليهم النبي صلى الله عليه وسلم فأخذتهم سنة حتى هلكوا فيها وأكلوا الميتة والعظام. فجاءه أبو سفيان فقال يا محمد جئت تأمر بصلة الرحم وإن قومك هلكوا فادع الله تعالى، فدعا رسول الله صلى الله عليه وسلم فسقوا الغيث فأطبقت عليهم سبعا وشكا الناس كثرة المطر قال اللهم حوالينا ولا علينا. فانحدرت السحابة عن رأسه فسقوا والناس حولهم)) قال الحافظ في الفتح والظاهر أن ذلك كان بمكة. وأخرج عن أبي هريرة ((أنه شكا إليه صلى الله عليه وسلم النسيان لما يسمع من حديثه الشريف، وهو يريد أن يزول عنه ذلك، فأمره صلى الله عليه وسلم أن يبسط رداءه فبسطه فقذف بيده الشريفة من الهواء في الرداء ثم قال ضمه فضمه قال أبو هريرة فما نسيت شيئا بعد)). وثبت أنهم شكوا إليه الحمي ((فدعا الله فحولها عنهم)) وصح أن قتادة أصيب بسهم في عينه فسالت على "], [124, "خده فالتفت إلى رسول الله فقال عيني يا رسول الله ((فخيره بين الصبر وبين أن يدعو له فاختار الدعاء فردها عليه الصلاة والسلام إلى موضعها وقال: اللهم اجعلها أحسن عينيه فعادت أحسن ما كانت)) وهذا بحر واسع لا سبيل إلى استقصائه. والأحاديث والآثار صريحة في النوعين جميعا. تارة يقولون ادع يا رسول الله، وتارة يرفعون إليه ما يريدون ويطلبون منه الحاجة وهم يريدون الشفاعة فيها إلى الله والدعاء والتسبب بما أقدره الله عليه، فإذا الحاجة قد قضيت بإذن الله تعالى. وأخرج البخاري عن عبد الله بن عمر: ربما ذكرت قول الشاعر ــ يعني قول أبي طالب المار ــ وأنا أنظر إلى وجه النبي صلى الله عليه وسلم يستسقى فما ينزل حتى يجيش كل ميزاب. وعن أنس أن عمر بن الخطاب رضي الله عنه كان إذا قحطوا استسقى بالعباس بن عبد المطلب فقال اللهم إنا كنا نتوسل إليك بنبينا صلى الله عليه وسلم فتسقينا وإنا نتوسل إليك بعم نبينا فاسقنا. وذكر الحافظ في الفتح عن الزبير بن بكار بأسناده عن عبد الله بن عمر قال استسقى عمر بن الخطاب عام الرمادة ــ بفتح الراء وتخفيف الميم ــ بالعباس بن عبد المطلب ثم خطب الناس فقال إن رسول الله صلى الله عليه وسلم كان يرى للعباس ما يرى الولد للوالد فاقتدوا أيها الناس برسول الله صلى الله عليه وسلم في عمه العباس، واتخذوه وسيلة إلى الله. وكان من كلام العباس لما استسقى به عمر أن قال: اللهم إنه لم ينزل بلاء إلا بذنب ولم يكشف إلا بتوبة وقد توجه القوم بي إليك لمكاني من نبيك، وهذه أيدينا إليك بالذنوب ونواصينا إليك بالتوبة فاسقنا الغيث. فأرخت السماء مثل الجبال حتى أخصبت الأرض وعاش الناس. قال الحافظ ويستفاد من قصة العباس استحباب الاستشفاع بأهل الخير والصلاح وأهل بيت النبوة، وفيه فضل العباس وفضل عمر لتواضعه للعباس ومعرفته بحقه اهـ. ومن دعاء العباس الذي ذكرناه لك تعرف أن العباس إنما توسل في دعائه بالنبي صلى الله عليه وسلم، ألا ترى إلى قوله ((وقد توجه القوم بي إليك لمكاني من نبيك)) أي لقرابتي منه. فكأنه قال بعد هذه اللفظة ((فاحفظ اللهم نبيك في "], [125, "عمه)) بل روى التصريح بها. ومن خطبة عمر السابقة عمر تعرف جليا أنه إنما أراد إظهار فضل أهل بيته صلى الله عليه وسلم وعليهم، وتوقير العباس اقتداء به عليه الصلاة والسلام في توقيره. وتعليم الناس ذلك. وفي قوله رضي الله عنه ((واتخذوه وسيلة إلى الله)) بمحضر الصحابة أن الصحابة رضي الله عنهم لم يكونوا يفهمون من قوله تعالى (وابتغوا إليه الوسيلة) قصر الوسيلة على الأعمال كما يتشدق به جهلة العصر تبعا لمن غلط قبلهم في ذلك، وفي رواية بعد قول عمر فاسقنا أنه أمر العباس بالدعاء فقال ادع يا عباس، فدعا العباس بما سبق. وفي هذا الأثر الصحيح الجمع بين النوعين الأولين والتوسل بالنبي صلى الله عليه وسلم بعد وفاته على أبلغ وجه ــ وأما ما كان من الصحابة الكرام معه صلى الله عليه وسلم بعد وفاته فمنه ما أخرج ابن أبي شيبة بسند صحيح كما في الفتح، والبيهقي في الدلائل بسند صحيح أيضا عن مالك الداري ــ وكان خازن عمر ــ قال: أصاب الناس قحط في زمان عمر فجاء رجل إلى قبر النبي صلى الله عليه وسلم فقال يا رسول الله استسق لأمتك فإنهم قد هلكوا، فأتى النبي صلى الله عليه وسلم الرجل في المنام فقال: إيت عمر فأقرئه السلام وأخبره أنهم مسقون وقل له عليك الكيس الكيس، فأتى الرجل عمر فأخبره فبكى عمر رضي الله عنه وقال: يا رب ما آلو إلا ما عجزت عنه، وهو مضارع ألا أي قصر وترك. وذلك الرجل هو بلال بن الحارث المزني أحد الصحابة الكرام. وقوله ((الكيس)) بفتح الكاف وسكون الياء المثناة ــ النشاط والاجتهاد. وأخرج الدارمي بسند صحيح في (باب ما أكرم الله به نبيه صلى الله عليه وسلم بعد الموت) من كتاب السنن له عن أبي الجوزاء أوس بن عبد الله التابعي الجليل قال قحط أهل المدينة قحطا شديد فشكوا إلى عائشة فقالت انظروا قبر النبي صلى الله عليه وسلم فاجعلوا منه كوى إلى السماء حتى لا يكون بينه وبين السماء سقف، قال ففعلوا فمطرنا مطرا حتى نبت العشب وسمنت الإبل حتى تفتقت من الشحم فسمي عام الفتق ــ وكأنها رضي الله عنها أرادت المبالغة في الاستشفاع به صلى الله عليه وسلم. وقولها: اجعلوا منه، أي مما يحازيه "], [126, "من سقف الحجرة الشريفة كما هو ظاهر. والكوى جمع كوة كقوة والمراد بها النوافذ الصغيرة ــ فأنت ترى في أثر بلال بن الحارث الصحابي أنه نادى النبي صلى الله عليه وسلم عند قبره مستغيثا به للأمة أن يستسقى لها، ولم ينكر عليه أحد ذلك، وفي حديث عثمان بن حنيف أن النبي صلى الله عليه وسلم علم الضرير أن يسأل الله به وأن يناديه وهو غائب عنه بقوله يا محمد إني أتوجه بك إلى ربي، ثم علم عثمان بن حنيف هذا الدعاء بعد وفاته صلى الله عليه وسلم للرجل الذي شكا إليه إبطاء الخليفة عثمان بن عفان عن حاجته ففعل الرجل وأخبره، ولما ظن أن حاجته قضيت بسبب كلامه مع الخليفة بادر ابن حنيف بنفي ذلك وحدثه بقصة الضرير التي شهدها ليثبت له أن حاجته إنما قضيت بسبب ما علمه من التوسل برسول الله صلى الله عليه وسلم وندائه إياه واستغاثته به وأكد ذلك بالحلف له فإنه قال والله ما كلمته ولكني شهدت رسول الله صلى الله عليه وسلم، إلى آخر ما مر. ومن الضروري أن يعلم هذا الرجل هذا الدعاء لأحبائه ويشيع هذه البركات التي نالته بسبب توسله بالنبي صلى الله عليه وسلم واستغاثته به. والعهد عهد الصحابة والتابعين. ولم ينقل عن أحد من السلف والذين رووا هذا الحديث أن أحدا توقف في حله فضلا عن أن جعله مكروها فضلا عن أن يكون حراما فضلا عن أن يكون شركا، والكتب المذكور فيها هذه الآثار والأحاديث هي لأكابر متقدمين قد تداولها علماء الأمة لا سيما طلبة الحديث وقد كانوا في تلك العهود جل أهل العلم، ولا يظن ظان أن أهل العلم في تلك العهود كانوا من الجهل بفن الحديث على ما يرى في هذا الزمان. ومن أراد أن يعرف قدر عنايتهم بجمع الحديث حفظا وكتابة ومدارسة فليرجع إلى التاريخ فسيجد أن الأجزاء الصغيرة، فضلا عن السنن والمسانيد والمعاجم والجوامع والمستخرجات والمستدركات كانت بينهم مشهورة متداولة محفوظة في الصدور حفظها في السطور، أفيعقل أن يكون فيها الشرك مأثورا عن الصحابة والتابعين ويسكتون عن بيان وضع تلك الأحاديث والآثار حاشا وكلا، فالتوسل بالنبي صلى الله عليه وسلم والصالحين سواء كان من النوع "], [127, "الأول وهو أن يسأل الله الحاجة بهم، أو النوع الثاني وهو طلب الدعاء منهم، أو الثالث وهو رفع الحاجة إليهم بعد وفاتهم لم يزل بين العلماء متعارفا سلفا وخلفا يرجون بركته ويحقق الله رجاءهم في الأعم الأغلب، ولا يجدون في صدورهم حرجا من ذلك، فأنهم إنما يطلبون حوائجهم من الله ويسألونه، ويعلمون أنه الخالق لا رب غيره، وأن النبي صلى الله عليه وسلم وصالحي أمته في حياتهم وبعد وفاتهم قد جعلهم الله أسبابا لقضاء حوائج عباده بشفاعتهم ودعائهم فضلا منه ورحمة. ونداء الصالح حيا أو ميتا حاضرا أو غائبا ليتوجه إلى الله في شأن المنادى الموحد ليس إلا استفتاحا لرحمة الله تعالى ببعض ما جعل من مفاتيحها له والمستغيث برسول الله صلى الله عليه وسلم ليس طالبا منه أن يخلق مع الله شيئا ولكنه طالب منه أن يدعو له، والأنبياء أحياء في قبورهم، يطلعهم الله على ما شاء من أحوال هذا العالم ــ وقد جمع الحافظ البيهقي جزءا في حياة الأنبياء. وقد ثبت أن النبي صلى الله عليه وسل تعرض عليه أعمال أمته كل يوم، بكرة وعشيا، ويبلغ صلاة المصلين عليه في أقطار الأرض عقب انتهائهم منها ويدعو لهم. واجتماع الأنبياء به عليه وعليهم الصلاة والسلام في الأرض والسماء ودعاؤهم له مشهور في الأحاديث الصحاح. وفيما أظهر الله في هذا الزمان من سماع المصري في مصر صوت الأمريكي وهو في أمريكا بواسطة التيار الكهربائي المادي المتبادل ما يقرب للجاهلين ما قال أهل البصائر في أمر العالم الروحاني وسماعه من الأحياء في هذا العالم لا سيما الأرواح العليا المحبوبة للحق جل وعلا والتسبب به صلى الله عليه وسلم ورجاء بركة الله بالتعلق به هو من أقوى ما يستجلب به الخير ولا يفسد التوسل بالأنبياء والصالحين إلا أن يجعلهم أربابا من دون الله ويتخذ هذا الجعل وسيلة إليهم أن يشفعوا له؛ فهذا لا ينفعه شيء من التوسل ولا غيره لأنه باعتقاد الربوبية أو شيء من خواصها لغيره تعالى صار كافرا مشركا كما فعل النصارى مع المسيح اتخذوه ربا ليشفع لهم عند أبيه تعالى الله عما قالوا وكما فعل الوثنيون فيما حكى الله عنهم من قولهم {مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى} [الزمر: 3] "], [128, "والعبادة شرعا كما مر لا تتحقق إلا إذا اعتقد الربوبية فيمن خضع له وليس في المسلمين كلهم أثر من هذا. أما من لم يعبد إلا الله وحده ثم امتلأ بتعظيم حبيبه المصطفى وكمل أتباعه وتوسل إلى الله بهم على أي نحو من الأنحاء السابقة فهو أهل أن يحقق الله رجاءه، وهو حال المسلمين المتوسلين من الخاصة والعامة في كل عصر بحمد الله، لا يعرفون خلافه وهو سبيل المؤمنين والعلماء العاملين من أهل السنة قديما وحديثا. ولم نر أحدا أنكر ذلك إلا رجلا في القرن الثامن وتعصب له ناس ابتلوا بما ابتلى به فجعل يلبس على العامة وتصدى علماء عصره لرد بدعته هذه ولرد بدعه الأخرى، ذلك الرجل هو (ابن تيمية) وكان هذا الرجل أولا متشبها بالصالحين ثم انسلخ عن ذلك إلى التشنيع على علماء الأمة بتفسيقهم وتكفيرهم. وأنقل لك عبارات بعض الأفاضل فيه وأبدأ بعبارة الذهبي من نصيحة بعث بها إليه. قال فيها يخاطبه: طوبي لمن شغله عيبه عن عيوب الناس، وتبا لمن شغله عيوب الناس عن عيبه، إلى كم ترى القذاة في عين أخيك وتنسى الجذع في عينك، إلى كم تمدح نفسك وشقاشقك وعباراتك وتذم العلماء ... إلى أن قال: كان سيف الحجاج ولسان ابن حزم شقيقين فواخيتهما. ثم قال: إن سلم لك إيمانك بالشهادتين فأنت سعيد يا خيبة من اتبعك فإنه معرض للزندقة والانحلال، لا سيما إذا كان قليل العلم والدين يا طوليا شهوانيا لكنه ينفعك ويجاهد عندك بيده ولسانه، وفي الباطن عدو لك بحاله وقلبه، فهل معظم أتباعك إلا قعيد مربوط، خفيف العقل أو عامي كذاب بليد الذهن أو غريب واجم قوى المكر؛ أو ناشف صالح عديم الفهم فإن لم تصدقني ففتشهم وزنهم بالعدل .. إلى كم تصادق نفسك وتعادى الأخيار إلى كم تصادقها وتزدرى الأبرار إلى كم تعظمها وتصغر العباد إلى كم تخاللها وتمقت الزهاد إلى متى تمدح كلامك بكيفية لا تمدح ــ والله ــ بها أحاديث الصحيحين، يا ليت أحاديث الصححيين تسلم منك، بل في كل وقت تغير "], [129, "عليها بالتضعيف والأهدار، أو بالتأويل والإنكار، أما آن لك أن ترعوى أما حان لك أن تتوب وتنيب؟ أما أنت في عشر السبعين وقد قرب الرحيل؟ إلى أن قال: فما أظنك تقبل على قولي ولا تصغى إلى وعظي، بل لك همة كبيرة في نقض هذه الورقة بمجلدات، وتقطع لي أذناب الكلام ولا تزال تنتصر حتى أقول البتة سكت، فإذا كان هذا حالك عندي وأنا الشفوق المحب الواد، فكيف حالك عند أعدائك، وأعداؤك والله فيهم صلحاء، وعقلاء وفضلاء، كما أن أولياءك فيهم فجرة وكذبة وجهلة، وبطلة وعور وبقر. اهـ ما أردنا نقله منها، وقد نقلها بتمامها العلامة المحقق الزاهد الكوثري في كتابه (التكملة على شرح شيخ الإسلام تقي الدين على السبكي) وقد كان شيخ الإسلام التقي معاصرا للذهبي وابن تيمية وولى مشيخة دار الحديث وخطابة الجامع الأموي بدمشق ومدحه الذهبي بقوله.\rليهن المنبر الأموي لما ... علاه الحاكم البحر التقي\rشيوخ العصر أحفظهم جميعا ... وأخطبهم وأقضاهم على\rفهذه شهادة الذهبي على ابن تيمية ولشيخ الإسلام التقي، فانظر ما قال شيخ الإسلام التقي في ابن تيمية حين أظهر بدعة تحريم الزيارة المحمدية وإنكار التوسل والاستغاثة بحضرته عليه الصلاة والسلام في كتابه (شفاء السقام) قال رضي الله عنه\r(الباب الثامن في التوسل والاستغاثة والتشفع بالنبي صلى الله عليه وسلم)\rاعلم أنه يجوز ويحسن التوسل والاستغاثة والتشفع بالنبي صلى الله عليه وسلم إلى ربه سبحانه وتعالى، وجواز ذلك وحسنه من الأمور المعلومة لكل ذي دين المعروفة من فعل الأنبياء والمرسلين وسير السلف الصالحين والعلماء والعوام من المسلمين، ولم ينكر أحد ذلك من أهل الأديان، ولا سمع به في زمن من الأزمان، حتى جاء ابن تيمية فتكلم في ذلك بكلام يلبس فيه على الضعفاء الأغمار، وابتدع ما لم يسبق "], [130, "إليه في سائر الأعصار. إلى أن قال: وحسبك أن إنكار ابن تيمية للاستغاثة والتوسل قول لم يقله عالم قبله، وصار به بين أهل الإسلام مثلة. ثم قال وأقول: إن التوسل بالنبي صلى الله عليه وسلم جائز في كل حال قبل خلقه وبعد خلقه في مدة حياته في الدنيا وبعد موته في مدة البرزخ وبعد البعث في عرصات القيامة والجنة. ثم ذكر الأنواع الثلاثة وفصلها نوعا نوعا مبينا مستدلا، إلى أن قال: والنوع الثالث من التوسل أن يطلب منه ذلك الأمر المقصود بمعنى أنه صلى الله عليه وسلم قادر على التسبب فيه بسؤاله ربه وشفاعته إليه فيعود إلى النوع الثاني في المعنى، وإن كانت العبارة مختلفة. ومن هذا قول القائل للنبي صلى الله عليه وسلم: أسألك مرافقتك في الجنة. قال: ((أعنى على نفسك بكثرة السجود)). قلت: أخرجه مسلم. قال: ولا يقصد الناس بسؤالهم ذلك إلا كون النبي صلى الله عليه وسلم سببا وشافعا،. إلى أن قال وليس المراد نسبة النبي صلى الله عليه وسلم إلى الخلق والاستقلال بالأفعال، هذا لا يقصده مسلم، فصرف الكلام إليه ومنعه من باب التلبيس في الدين والتشويش على عوام الموحدين. وإذ قد تحررت هذه الأنواع والأحوال في الطلب من النبي صلى الله عليه وسلم وظهر المعنى فلا عليك في تسميته توسلا أو تشفعا أو استغاثة أو تجوها أو توجها، لأن المعنى في جميع ذلك سواء)) اهـ وقال الإمام القدوة، حامي السنة وقامع البدعة ابن الحاج المعاصر لابن تيمية أيضا، وقد توفى بعده بتسع سنين في كتابه (المدخل) في فصل زيارة القبور: ((وأما عظيم جناب الأنبياء والرسل صلوات الله وسلامه عليهم أجمعين فيأتي إليهم الزائر ويتعين عليه قصدهم من الأماكن البعيدة، فإذا جاء إليهم فليتصف بالذل، والانكسار والمسكنة والفقر والفاقة والحاجة والاضطرار والخضوع، ويحضر قلبه وخاطره إليهم وإلى مشاهدتهم بعين قلبه لا بعين بصره، لأنهم لا يبلون ولا يتغيرون، ثم يثنى على الله تعالى بما هو أهله، ثم يصلى عليهم ويترضى عن أصحابهم، ثم يترحم على التابعين لهم بإحسان إلى يوم الدين، ثم يتوسل إلى الله تعالى بهم في قضاء ما ربه ومغفرة ذنوبه "], [131, "ويستغيث بهم ويطلب حوائجه منهم، ويجزم بالإجابة ببركتهم، ويقوى حسن ظنه في ذلك، فإنهم باب الله المفتوح، وجرت سنته سبحانه وتعالى بقضاء الحوائج على أيديهم وبسببهم. ومن عجز عن الوصول إليهم فليرسل بالسلام عليهم، ويذكر ما يحتاج إليه من حوائجه ومغفرة ذنوبه وستر عيوبه إلى غير ذلك، فإنهم السادة الكرام، والكرام لا يردون من سألهم ولا من توسل بهم، ولا من قصدهم ولا من لجأ إليهم. هذا الكلام في زيارة الأنبياء والمرسلين عليهم الصلاة والسلام عموما. قال رضي الله عنه (فصل) وأما في زيارة سيد الأولين والآخرين صلوات الله عليه وسلامه فكل ما ذكر يزيد عليه أضعافه أعني في الانكسار والذل والمسكنة، لأنه الشافع المشفع الذي لا ترد شفاعته ولا يخيب من قصده، ولا من نزل بساحته، ولا من استعان أو استغاث به، إذ أنه عليه الصلاة والسلام قطب دائرة الكمال، وعروس المملكة، ثم قال: فمن توسل به أو استغاث به أو طلب حوائجه منه فلا يرد ولا يخيب لما شهدت به المعاينة والآثار، ويحتاج إلى الأدب الكلى في زيارته عليه الصلاة والسلام. وقد قال علماؤنا رحمة الله عليهم. إن الزائر يشعر نفسه بأنه واقف بين يديه عليه الصلاة والسلام كما هو في حياته، إذ لا فرق بين موته وحياته ــ أعني في مشاهدته لأمته ومعرفته بأحوالهم ونياتهم وعزائمهم وخواطرهم وذلك عنده جلى لا خفاء فيه ــ إلى أن قال: فالتوسل به عليه الصلاة والسلام هو محل حط أحمال الأوزار وأثقال الذنوب والخطايا، لأن بركة شفاعته عليه الصلاة والسلام وعظمها عند ربه لا يتعاظمها ذنب، إذ أنها أعظم من الجميع، فليستبشر من زاره وليلجأ إلى الله تعالى بشفاعة نبيه عليه الصلاة والسلام من لم يزره. اللهم لا تحرمنا من شفاعته بحرمته عندك آمين يا رب العالمين ومن اعتقد خلاف هذا فهو المحروم)) اهـ بحروفه.\rوقال الإمام الفقيه المجمع على جلالته وفضله شهاب الدين ابن حجر الهيتمي "], [132, "في كتابه ((الجوهر المنظم في زيارة القبر الشريف النبوي المكرم)) فإن قلت: كيف تحكى الإجماع السابق على مشروعية الزيارة والسفر إليها وطلبها؟ وابن تيمية من متأخري الحنابلة منكر لمشرعية ذلك كله كما رآه السبكي في خطه، وأطال أعنى ابن تيمية في الاستدلال لذلك بما تمجه الاسماع وتنفر عنه الطباع، بل زعم حرمة السفر لها إجماعا، وأنه لا تقصر فيه الصلاة وأن جميع الأحاديث الواردة فيها موضوعة، وتبعه بعض من تأخر عنه من أهل مذهبه؟ قلت: من هو ابن تيمية حتى ينظر إليه أو يعول في شيء من أمور الدين عليه؟ وهل هو إلا كما قال جماعة من الأئمة الذين تعقبوا كلماته الفاسدة وحججه الكاسدة حتى أظهروا عوار سقطاته وقبائح أوهامه وغلطاته كالعز بن جماعة: عبد أضله الله تعالى وأغواه وألبسه رداء الخزي وأرداه، وبوأه من قوة إلا فتراء والكذب ما أعقبه الهوان وأوجب له الحرمان. وقال في فتاواه الحديثيه نحوا من هذا حين سئل عنه. وبالجملة فهذا الرجل ينطبق عليه كل الانطباق ما أخرج أبو نعيم بسند جيد عن حذيفة رضي الله عنه قال قال رسول الله صلى الله عليه وسلم: ((إن مما أتخوف عليكم رجلا قرأ القرآن حتى إذا ريئت عليه بهجته، وكان ردءا للإسلام غيره الله إلى ما شاء فانسلخ منه ونبذه وراء ظهره وخرج على جاره بالسب ورماه بالشرك قلت: يا رسول الله أيهما أولى بالشرك؟ الرامي أم المرمى؟ قال: بل الرامي)) قوله ريئت بمعنى رؤيت وكذلك كان هذا الرجل، بدأ حياته بطلب العلم على ذكاء وتصالح، ورفق به أكابر العلماء لأن أباه كان رجلا هادئا، وكان من بيت علم، فساعدوه وشجعوه وأثنوا عليه خيرا، حتى إذا أقبل عليه الناس بدأ يظهر بالبدع وأبطرته الغرة فتمادى في التعصب لآرائه، وما زال يتلاعب به الهوى حتى كان مجموعة بدع شنعاء ودائرة جهالات وأباطيل شوهاء، منها ما سبق به ومنها ما لم يسبق إليه فتجده في مسائل من علم التوحيد حشويا كراميا، يقول في الله بالأجزاء والجهة والمكان، والنزول والصعود الحسيين وحلول الحوادث بذاته تعالى، ومن ناحية "], [133, "أخرى تجد فيه حضيضة الخوارج، يكفر أكابر الأمة ويخطئ أعاظم الأئمة وقال: من نذر شيئا للنبي صلى الله عليه وسلم أو غيره من النبيين والأولياء من أهل القبور أو ذبح له ذبيحة كان كالمشركين الذين يذبحون لأوثانهم وينذرون لها فهو عابد لغير الله فيكون بذلك كافرا ويطيل في ذلك الكلام ــ واغتر بكلامه بعض من تأخر عنه من العلماء ممن ابتلى بصحبته أو صحبة تلاميذه وهو منه تلبيس في الدين، وصرف إلى معنى لا يريده مسلم من المسلمين. ومن خبر حال من فعل ذلك من المسلمين وجدهم لا يقصدون بذبائحهم ونذورهم للميتين من الأنبياء والأولياء إلا الصدقة عنهم، وجعل ثوابها إليهم، وقد علموا أن أجماع أهل السنة منعقد على أن صدقة الأحياء نافعة للأموات، واصلة إليهم، والأحاديث في ذلك صحيحة مشهورة فمنها ما صح: عن سعد أنه سأل النبي صلى الله عليه وسلم قال يا نبي الله إن أمي قد افتلتت وأعلم أنها لو عاشت لتصدقت أفأن تصدقت عنها أينفعها ذلك؟ قال: نعم. فسأل النبي صلى الله عليه وسلم أي الصدقة أنفع يا رسول الله؟ قال الماء فحفر بئرا وقال: هذه لأم سعد. فهذه اللام هي الداخلة على الجهة التي وجهت إليها الصدقة لا على المعبود المتقرب إليه، وهي كذلك في كلام المسلمين، فهم سعد يون لا وثنيون، وهي كلام في قوله إنما الصدقات للفقراء، لا كاللام التي في قول القائل صليت لله ونذرت لله فإذا ذبح للنبي أو المولى أو نذر الشيء له، فهو لا يقصد إلا أن يتصدق بذلك عنه، ويجعل ثوابه إليه فيكون من هدايا الأحياء للأموات المشروعة المثاب على إهدائها والمسألة مبسوطة في كتب الفقه وفي كتب الرد على هذا الرجل ومن شايعه، وقال من طاف بقبور الصالحين أو تمسح بها كان مرتكبا أعظم العظائم وأتى بكلام ملتبس فمرة يجعله من الكبائر وأخرى من الشرك إلى مسائل من أشباه ذلك قد فرغ العلماء المحققون والفقهاء المدققون من بحثها وتدوينها قبل أن يولد هو بقرون، فيأبى إلا أن يخالفهم وربما اعي الإجماع على ما يقول وكثيرا ما يكون الإجماع قد العقد قبله على خلاف قوله كما يعلم ذلك من أنعم النظر في "], [134, "كلامه وكلام من قبله وكلام من بعده ممن تعقبه من أهل الفهم المستقيم والنقد السليم. وإليك مثالا التمسح بالقبر أو الطواف به من عوام المسلمين فأهل العلم فيه على ثلاثة أقوال الجواز مطلقا والمنع مطلقا على وجه كراهة التنزيه الشديدة ولكنها لا تبلغ حد التحريم. والتفصيل بين من غلبه شدة شوق إلى المزور فتنتفي عنه هذه الكراهة ومن لا فالأدب تركه وأنت إذا تأملت في الأمور التي كفر بها المسلمين وجعلها عبادة لغير الله وجدت حجته ترجع إلى مقدمتين صدقت كبراهما وهي: كل عبادة لغير الله شرك وهي معلومة من الدين بالضرورة ثم يسوق عليها الأدلة بالآيات الواردة في المشركين. وكذبت صغراهما وهي قوله كل نداء لميت أو غائب أو طواف بقبر أو تمسح به أو ذبح أو نذر لصاحبه الخ الخ فهو عبادة لغير الله ثم يسوق الآيات والأحاديث الصحاح التي لم يفهمها أو تعمد تأويلها على غير وجهها ثم يخرج من هذا القياس الذي فسدت إحدى مقدمتيه بنتيجة لا محالة كاذبة وهي أن جمهور المسلمين إلا إياه ومن شايعه مشركون كافرون وقد أجاد تلخيص هذا المذهب وأدلته وتزييفها منطقيا وأصوليا كل الإجادة سيد أهل التحقيق وتاج أهل التدقيق الإمام أبو عبد الله محمد بن عبد المجيد الفاسي المتوفى سنة تسع وعشرين ومائتين وألف في مؤلف رد به على ذلك المذهب ينطق بعلو كعب هذا الإمام وتفوقه على كثير من الأعلام في المعقول والمنقول وهذا مجمل من القول قد فصله العلماء قبلنا بما لا مزيد عليه فيما صنفوه لرد مفترياته شكرا لله سعيهم. ولولا ما قاموا به من ذلك لانقلبت البلاد الإسلامية كلها إلى براكين من الاخطار التي لا يعلم مدى أضرارها إلا الله عز وجل\rولقد تعدى هذا الرجل حتى على الجناب المحمدي، فقال: إن شد الرحال إلى زيارته معصية. وأن من ناداه مستغيثا به عليه الصلاة والسلام بعد وفاته فقد أشرك، فتارة يجعله شركا أصغر وأخرى يجعله شركا أكبر، وإن كان المستغيث ممتلئ القلب بأنه لا خالق ولا مؤثر إلا الله، وأن النبي صلى الله عليه وسلم إنما ترفع "], [135, "إليه الحوائج ويستغاث به، على أن الله جعله منبع كل خير، مقبول الشفاعة مستجاب الدعاء صلى الله عليه وسلم، كما هي عقيدة جميع المسلمة مهما كانوا من العامة.\rوالنبي القول في تكفير المسلمين بما كفرهم على أن توحيد الربوبية لا يستلزم التوحيد في العبادة، وأن الرسل إنما جاءوا بالثاني ولفتوا الأنظار إلى الأول الذي كان عليه المشركون ولم يتفطن إلى ما اعتبره الشرع في معنى العبادة الذي قدمناه. ولا إلى ما امتلأت الأرض به من القول بالتثنية والتثليث والتربيع فما فوقه للأرباب، ولا إلى ما أجمع عليه العقلاء وأفاده الكتاب العزيز بوضوح والأحاديث الصحاح من التلازم بينهما. وقد قدمنا ذلك. فارجع إليه إن شئت وقد أوضح ذلك كل الايضاح قبلنا أكابر جهابذة لا سيما علم أعلام هذا العصر حامل لواء الحكمة الإسلامية وأحد جماعة كبار العلماء بحق الشيخ يوسف الدجوى فيما كتبه في مجلة الأزهر أدام الله تأييده بروح منه وجلله بالعافية من لدنه. وهذه البدعة من مبتكراته قد اغتر بها ناس فقالوا بكفر من عداهم من جماهير المسلمين وسفكت في ذلك دماء لا تحصى. وقد ألفت الكتب الكثيرة في رد هذه البدعة وفروعها بين مطول قد جوده صاحبه، ومختصر أفاد مؤلفه وأجاد، ومن عجيب أمر هذا الرجل، أنه إذا ابتدع شيئا حكى عليه إجماع الأولين والآخرين كذبا وزورا، وربما تجد تناقضه في الصفحة الواحدة، فتجده في منهاجه مثلا يدعي أنه ما من حادث إلا وقبله حادث إلى ما لا نهاية له في جانب الماضي، ثم يقول: وعلى ذلك أجمع الصحابة والتابعون، وبعد قليل يحكى اختلاف لحق الصحابة في أول مخلوق ما هو؟ أهو القلم أم الماء؟؟ وبينما تراه يتكلم بلسان أهل الحق المنزهين إذا بك تراه قد انقلب جهويا وسمى كل من لا يقول بذلك معطلا وزنديقا وكافرا، وقد جمع تلميذه ابن زفيل سفاهاته ووساوسه في علم أصول الدين في قصيدته النونية، وبينما تراه يسب جهما والجهمية إذا بك تراه يأخذ بقوله في أن النار تفنى وأن أهلها ليسوا خالدين فيها أبدا، على حين يعيب ابن العربي "], [136, "الحاتمي بقوله إن العذاب ينقلب عذابا على الكفار والنار كما هي أبدا وهم خالدون فيها أبدا، كما قال القرآن، ويبدعه بذلك القول، فأي الرجلين أدخل في البدعة احكم منصفا، وفتح أبواب استباحة الفروج فنقل الثقات عن خطه القول بأن الطلاق الثلاث إذا جمع في لفظة واحدة لا يقع أصلا والمشهور عنه القول بأنه يقع واحدة، ويحكى على ذلك الإجماع، وقد علم أهل العلم أن الاجماع من عهد عمر إلى زمانه منعقد على خلافه: قال الحافظ بن حجر في الفتح بعد ما ذكر أجوبة العلماء عن الحديث الذي تمسك بظاهره هذا المبتدع، وبعد ما حكى خلافا عن بعض الناس قال في آخر البحث ((وفي الجملة فالذي وقع في هذه المسألة نظير ما وقع في مسألة المتعة سواء، أعنى قول جابر: إنها كانت تفعل في عهد النبي صلى الله عليه وسلم وأبي بكر وصدر من خلافة عمر، قال ثم نهانا عمر عنها فانتهينا، فالراجح في الموضعين تحريم المتعة وإيقاع الثلاث للإجماع الذي انعقد في عهد عمر على ذلك، ولا يحفظ أن أحدا في عهد عمر خالفه في واحدة منهما، وقد دل إجماعهم على وجود ناسخ وإن كان خفى عن بعضهم قبل ذلك حتى ظهر لجميعهم في عهد عمر، فالمخالف بعد هذا الاجماع منابذ له، والجمهور على عدم اعتبار من أحدث الاختلاف بعد الاتفاق)) اهـ بحروفه.\rولم يكتف ــ أعني ابن تيمية ــ في باب الطلاق بهذا القدر، بل قال: إن الطلاق المعلق على وجه اليمين ولو ثلاثا كأن دخلت الدار فأنت طالق. وحكى عن الصحابة أنهم لم يتكلموا في المسألة فضلا عن أنها وقعت منهم، ولا يخجل من أن البخاري ذكر في صحيحه تعليقا بصيغة الجزم عن ابن عمر أنه سئل عن رجل قال لامرأته أنت طالق البتة إن خرجت، فقال: إن خرجت فقد بانت منه، وأن لم تخرج فليس بشيء. وصح عن ابن مسعود أنه سئل عمن قال لامرأته: (إن فعلت كذا وكذا فهي طالق) ففعلته قال: هي واحدة وهو أحق بها، وكذلك رويت آثار صحاح عن علي في القول بوقوع الطلاق المعلق عند وقوع المعلق "], [137, "عليه، وكذلك صح عن أبي ذر علقه تعليقا، ومن العجيب أنه بعد ما حكى عن الصحابة أنهم لم يتكلموا في هذه المسألة يحكى عنهم أنهم قائلون بقوله، ويعمد إلى آيات يتأولها على غير وجهها، يضل بها العامة والقريبين من درجتهم من أهل العلم، ويحكى الخلاف في وقوع الطلاق المعلق على وجه اليمين كذبا وزورا، وقد حكى الإجماع على وقوع الطلاق المعلق مطلقا ــ الإمام الشافعي، والإمام أبو عبيد القاسم بن سلام، والإمامان أبو بكر بن المنذر وأبو جعفر الطبري. والإمام محمد بن نصر المروزي والحافظ ابن عبد البر في كتابيه التمهيد والاستذكار، في آخرين يطول ذكرهم.\rوليس من غرضنا بسط الكلام في بدع هذا الرجل فقد كفانا العلماء شكر الله سعيهم من عصره إلى هذا العهد المؤنة بالتصانيف الممتعة في الرد عليها، وإنما أردنا أن ننبهك أيها الأخ المشفق على دينه على خطر هذا الرجل وشدة جراءته على الله ورسوله وكتابه. وعلماء هذه الأمة وأئمتها. وقد سيق للمحاكمة مرارا فتارة ينكر، وأخرى يعترف ويعلن رجوعه ثم لا يلبث أن ينقض عهده. وكان كثير من أهل العلم يتوقفون في أمره وينفون عنه كثيرا مما هو قائل به لاختفاء مصنفاته، حتى إذا رفع الجهل رأسه في عصرنا هذا انتدب ناس من شيعته لطبع الكثير من كتابه وكتب تلميذه ابن زفيل ففضحوا الرجل وشهروا به عند المحقق من أهل الفقه في الدين، وتبينت صحة نسبة ما كان يتورع العلماء عن نسبته إليه، حسن ظن بالرجل. وإن نصيحتي التي أسديها لكل مسلم نصيحة لله ولرسوله ولكتابه، وأئمة المسلمين وعامتهم هي لزوم جماعة المسلمين في أصول الدين وفروعه كما أسلفنا الإشارة إليه في المقدمة.\rولو لا أني أشفق على القاري أن يمل لتحدثت إليه طويلا فيما أصاب الإسلام والمسلمين من عظائم هذا الرجل، ولبسطت له ما قال أكابر العلماء فيه وفي شيعته، ولكني أرجو أن يكون ما قدمناه كافيا لذوي النهي ــ وأحمد الله "], [138, "الذي تفضل علينا بالنجاة من بدعه مع كثرة ما قرأنا من كتبه، وكتب شيعته قديما وحديثا، ونسأله أن يديمنا على السنة ويتوفانا عليها غير محرفين ولا منحرفين هداة مهتدين بجاه أفضل أنبيائه وخاتم رسله وأجل أصفيائه، وبجاه سائر أنبيائه الكرام، وسائر الصالحين من أهل السموات والأرضين، على نبينا وعليهم من الصلوات أفضلها، ومن التسليمات أكملها ــ والحمد لله رب العالمين.\rوكان الفراغ من هذه الرسالة ليلة الخميس السادس من ربيع الثاني\rسنة ثمان وخمسين وثلاثمائة وألف من هجرة حامل لواء\rالعز والشرف صلى الله عليه وعلى آله وسلم\rكلما ذكره الذاكرون وغفل عن\rذكره الغافلون "], [139, "ـــــــــــــــــــــــــــــ\r(كلمة لصاحب الامضاء)\r"]], "pg": [109, 139]}, "526.35": {"x": [[139, "يستطيع الإنسان أن يدرك سر جمال الكون ويخترق بنظراته تلك الحجب الكثيفة فيرى عظمة هذا الملكوت، ويشاهد في صفحته ما تنطوي عليه قائقه وجلائله فينظر إلى الإبل كيف خلقت، وإلى السماء كيف رفعت، وإلى الجبال كيف نصبت وإلى الأرض كيف سطحت مما لا يعلمه إلا الله والراسخون في العلم، فإذا أعوزك الشعور إلى السعادة فانظر ببصرك وبصيرتك إلى هذه الرسالة الربانبية، والنفحة الإلهية (فرقان القرآن بين صفات الخالق وصفات الأكوان) فإنك ترى فيها آيات قد فصلت ومعان قد أحكمت وأسرارا قد نشرت وحكما قد ظهرت وتدرك فيها كأنها خطاب السماء إلى الأرض ووحيه إلى العباد يهيى بها من يشاء إلى الحق وإلى طريق مستقيم ولا غر وفانها مظهر من خواطر ذلك القطب الرباني وآية من آيات ذلك النور الروحاني (أستاذنا ومولانا الشيخ سلامة العزامي) ذلك الذي اتصل قلبه بجلال الخالق وجمال توحيده حتى أصبح سرا من الأسرار وصورة من الروح تعجز عن وصفها العقول وتحار في كنهها الأفئدة فما هذا بشرا إن هذا إلا ملك كريم\rوإني مع عجزي وتقصيري أقف عند قولي\rسل عن (سلامة) قاصيها ودانيها ... تستلهم النفس ما يجلو غواشيها\rلا بدع إن هم في الأيام يصرفها ... عن غيها وبنور الله يهديها\rيفيض علما وآيات مفصلة ... كأنها روح وحي الله تنزيها\rلم يطلب المجد في الدنيا بدعوته ... يوجه الروح للرحمن توجيها\rبقوة الحق قد أدى رسالته ... وما يزال يؤديها ويذكيها\rوهذه آية الفرقان شاهدة ... تشع نورا على الدنيا ومن فيها\rأدامه الله مشكاة وتبصرة ... وللحنيفة حصنا من أعاديها\rمحمد الفقي. من علماء الأزهر الشريف ... بدار الكتب المصرية"]], "pg": [139, 139]}}, "units": {"1": {"tit": "فرقان القرآن بين صفات الخالق وصفات والأكوان", "lvl": 1, "pg": [7, 11]}, "5": {"tit": "فصل ما من بدعة إلا وفي كتاب الله وسنة رسوله الرد عليها", "lvl": 2, "pg": [11, 12]}, "6": {"tit": "فصل: بيان أن بعض الحفاظ وقع في الخطأ لخوضه فيما لا يحسنه", "lvl": 2, "pg": [12, 15]}, "9": {"tit": "فصل: من أراد فهم هؤلاء الفرق", "lvl": 2, "pg": [15, 19]}, "13": {"tit": "فصل: في بيان كتاب البيهقي", "lvl": 2, "pg": [19, 21]}, "15": {"tit": "المقدمة", "lvl": 3, "pg": [21, 25]}, "19": {"tit": "فصل في أن الأسباب المتوقفة بعضها على بعض", "lvl": 2, "pg": [25, 30]}, "24": {"tit": "فصل: في تحقيق معنى قوله تعالى: ولن تجد لسنة الله تبديلا", "lvl": 2, "pg": [30, 32]}, "26": {"tit": "فصل: في أنه سبحانه هو فاعل للوجود", "lvl": 2, "pg": [32, 38]}, "32": {"tit": "فصل: قد بأن أن البرهان القاطع ناطق بأن ما وجد ويوجد من الذوات والصفات لا يهبه الوجود وتوابعه إلا واجب الوجود", "lvl": 2, "pg": [38, 43]}, "37": {"tit": "فصل: في فضل الإيمان بالغيب وحكته، وعظم نقص من لم يتصف به", "lvl": 2, "pg": [43, 49]}, "43": {"tit": "تنوير في تفسير إقتربت الساعة", "lvl": 2, "pg": [49, 52]}, "46": {"tit": "المقصد في الصفات المختصة بالخلق والصفات المختصة بالحق", "lvl": 1, "pg": [52, 56]}, "50": {"tit": "فصل", "lvl": 2, "pg": [56, 59]}, "53": {"tit": "فصل في أن كل مقدر بقدر ومحدود بحدود، فهو حادث", "lvl": 2, "pg": [59, 62]}, "56": {"tit": "فصل في أن بين المقدرات من الجواهر وبين المكان والجهة لزوما بينا", "lvl": 2, "pg": [62, 67]}, "61": {"tit": "فصل في نقول مهمة عن أكابر السلف تجلى لك الأمر", "lvl": 2, "pg": [67, 71]}, "65": {"tit": "زيادة تبصير وتنوير", "lvl": 2, "pg": [71, 73]}, "67": {"tit": "تتمة تشمل على نص سؤال الى شيخ الإسلام سليم البشري في رجل يعتقد الفوقية المحدودة", "lvl": 2, "pg": [73, 79]}, "73": {"tit": "فصل في أن صفات المحدثات على قسمين", "lvl": 2, "pg": [79, 80]}, "74": {"tit": "مطلب في بيان وحدة الوجود", "lvl": 2, "pg": [80, 81]}, "75": {"tit": "تنبيه مهم: في بيان عبارات بعض السلف إنما نؤمن بأن له وجها لا كالوجوه", "lvl": 2, "pg": [81, 82]}, "76": {"tit": "فصل فيما يختص به عز وجل من الصفات الواجبة له", "lvl": 2, "pg": [82, 85]}, "79": {"tit": "فصل في الوحدانية وأن دليل القرآن عليها برهاني لا خطابي", "lvl": 2, "pg": [85, 87]}, "81": {"tit": "مطلب في بيان أن توحيد الربوبية وتوحيد الألوهية متلازمان لا ينفك أحدهما عن صاحبه", "lvl": 2, "pg": [87, 93]}, "87": {"tit": "فصل فيما يوهم التشبيه عند العامة من ظاهر الكتاب والسنة)", "lvl": 2, "pg": [93, 95]}, "89": {"tit": "فائدة مهمة في أن أكثر السلف يقولون بالصرف عن الظواهر", "lvl": 2, "pg": [95, 102]}, "96": {"tit": "بيان أن العلو المعنوي من المجاز الشائع في كلام العرب", "lvl": 2, "pg": [102, 106]}, "100": {"tit": "خاتمة", "lvl": 1, "pg": [106, 109]}, "103": {"tit": "وصل في معنى الإيمان والإسلام", "lvl": 2, "pg": [109, 139]}, "133": {"tit": "كلمة لصاحب الامضاء", "lvl": 2, "pg": [139, 139]}}};
